          onOpenChange={setIsInstitutionDialogOpen}
        >
          <DialogTrigger asChild>
            <Button className="gap-2">
              <Plus className="h-4 w-4" />
              Add Institution
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Add New Institution</DialogTitle>
              <DialogDescription>
                Create a new educational institution on the platform
              </DialogDescription>
            </DialogHeader>
            <form onSubmit={handleCreateInstitution}>
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label htmlFor="name">Institution Name *</Label>
                  <Input
                    id="name"
                    placeholder="e.g., University of Technology"
                    value={newInstitution.name}
                    onChange={(e) =>
                      setNewInstitution({
                        ...newInstitution,
                        name: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="description">Description</Label>
                  <Textarea
                    id="description"
                    placeholder="e.g., A leading educational institution"
                    value={newInstitution.description}
                    onChange={(e) =>
                      setNewInstitution({
                        ...newInstitution,
                        description: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="website">Website</Label>
                  <Input
                    id="website"
                    type="url"
                    placeholder="e.g., https://www.university.edu"
                    value={newInstitution.website}
                    onChange={(e) =>
                      setNewInstitution({
                        ...newInstitution,
                        website: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <DialogFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setIsInstitutionDialogOpen(false)}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={createInstitutionMutation.isPending}
                >
                  {createInstitutionMutation.isPending
                    ? "Creating..."
                    : "Create Institution"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Tabs defaultValue="institutions" className="space-y-6">
        <TabsList>
          <TabsTrigger value="institutions">
            <Building2 className="h-4 w-4 mr-2" />
            Institutions
          </TabsTrigger>
          <TabsTrigger value="programmes" disabled={!selectedInstitution}>
            <GraduationCap className="h-4 w-4 mr-2" />
            Programmes
          </TabsTrigger>
        </TabsList>

        <TabsContent value="institutions">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle className="flex items-center gap-2">
                    <Shield className="h-5 w-5 text-role-admin" />
                    All Institutions
                  </CardTitle>
                  <CardDescription>
                    {institutions?.length || 0} total institutions
                  </CardDescription>
                </div>
                <Dialog
                  open={isInstitutionBulkUploadDialogOpen}
                  onOpenChange={setIsInstitutionBulkUploadDialogOpen}
                >
                  <DialogTrigger asChild>
                    <Button variant="outline" className="gap-2">
                      <Upload className="h-4 w-4" />
                      Bulk Upload
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-2xl">
                    <DialogHeader>
                      <DialogTitle>Bulk Upload Institutions</DialogTitle>
                      <DialogDescription>
                        Upload multiple institutions via file (JSON/CSV) or
                        paste data directly
                      </DialogDescription>
                    </DialogHeader>
                    <form onSubmit={handleInstitutionBulkUpload}>
                      <div className="space-y-4 py-4">
                        <div className="space-y-2">
                          <Label>Upload File</Label>
                          <Input
                            type="file"
                            accept=".json,.csv"
                            onChange={(e) => {
                              const file = e.target.files?.[0];
                              if (file) {
                                setSelectedFile(file);
                                setInstitutionBulkData("");
                              }
                            }}
                          />
                          <p className="text-sm text-muted-foreground">
                            Supported formats: JSON, CSV
                          </p>
                        </div>

                        <div className="relative">
                          <div className="absolute inset-0 flex items-center">
                            <span className="w-full border-t" />
                          </div>
                          <div className="relative flex justify-center text-xs uppercase">
                            <span className="bg-background px-2 text-muted-foreground">
                              Or paste data
                            </span>
                          </div>
                        </div>

                        <div className="flex gap-2">
                          <Button
                            type="button"
                            variant={
                              institutionBulkFormat === "json"
                                ? "default"
                                : "outline"
                            }
                            size="sm"
                            onClick={() => setInstitutionBulkFormat("json")}
                            className="gap-2"
                          >
                            <FileJson className="h-4 w-4" />
                            JSON Format
                          </Button>
                          <Button
                            type="button"
                            variant={
                              institutionBulkFormat === "csv"
                                ? "default"
                                : "outline"
                            }
                            size="sm"
                            onClick={() => setInstitutionBulkFormat("csv")}
                            className="gap-2"
                          >
                            <FileSpreadsheet className="h-4 w-4" />
                            CSV Format
                          </Button>
                        </div>

                        <div className="space-y-2">
                          <Label>
                            {institutionBulkFormat === "json"
                              ? "JSON Data"
                              : "CSV Data"}
                          </Label>
                          <Textarea
                            value={institutionBulkData}
                            onChange={(e) => {
                              setInstitutionBulkData(e.target.value);
                              setSelectedFile(null);
                            }}
                            placeholder={
                              institutionBulkFormat === "json"
                                ? `[\n  {\n    "name": "University of Technology",\n    "profileSlug": "university-of-technology",\n    "description": "A leading tech university",\n    "website": "https://utech.edu",\n    "country": "Ghana",\n    "city": "Accra",\n    "address": "123 University Road",\n    "email": "info@utech.edu",\n    "phone": "+233-123-456-789",\n    "type": "University",\n    "founded": 1960,\n    "studentCount": 10000\n  }\n]`
                                : "name,profileSlug,description,website,country,city,address,email,phone,type,founded,studentCount\nUniversity of Technology,university-of-technology,A leading tech university,https://utech.edu,Ghana,Accra,123 University Road,info@utech.edu,+233-123-456-789,University,1960,10000"
                            }
                            rows={10}
                            className="font-mono text-sm"
                          />
                          <p className="text-sm text-muted-foreground">
                            <strong>Required:</strong> name<br />
                            <strong>Optional:</strong> profileSlug, description, website, country, city, address, postalCode, email, phone, type, founded, studentCount, logoUrl<br />
                            <strong>Note:</strong> If profileSlug is not provided, it will be auto-generated from the institution name (lowercase, URL-friendly format)
                          </p>
                        </div>
                      </div>
                      <DialogFooter>
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => {
                            setIsInstitutionBulkUploadDialogOpen(false);
                            setInstitutionBulkData("");
                            setSelectedFile(null);
                          }}
                        >
                          Cancel
                        </Button>
                        <Button
                          type="submit"
                          disabled={bulkInstitutionUploadMutation.isPending}
                        >
                          {bulkInstitutionUploadMutation.isPending
                            ? "Uploading..."
                            : "Upload Institutions"}
                        </Button>
                      </DialogFooter>
                    </form>
                  </DialogContent>
                </Dialog>
              </div>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <div className="space-y-3">
                  {[1, 2, 3].map((i) => (
                    <Skeleton key={i} className="h-16 w-full" />
                  ))}
                </div>
              ) : !institutions || institutions.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground">
                  <Building2 className="h-16 w-16 mx-auto mb-4 opacity-20" />
                  <p>No institutions found</p>
                  <p className="text-sm mt-2">
                    Click "Add Institution" to create one
                  </p>
                </div>
              ) : (
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Institution</TableHead>
                        <TableHead>Description</TableHead>
                        <TableHead>Website</TableHead>
                        <TableHead>Created</TableHead>
                        <TableHead>Actions</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {institutions.map((institution) => (
                        <TableRow
                          key={institution.id}
                          className={
                            selectedInstitution === institution.id
                              ? "bg-muted/50"
                              : ""
                          }
                        >
                          <TableCell className="font-medium">
                            <div className="flex items-center gap-3">
                              <div className="h-10 w-10 rounded-md bg-role-institution/10 flex items-center justify-center">
                                <Building2 className="h-5 w-5 text-role-institution" />
                              </div>
                              <div>
                                <p className="font-semibold">
                                  {institution.name}
                                </p>
                              </div>
                            </div>
                          </TableCell>
                          <TableCell className="text-muted-foreground">
                            {institution.description || "No description"}
                          </TableCell>
                          <TableCell>
                            {institution.website ? (
                              <a
                                href={institution.website}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-primary hover:underline"
                              >
                                Visit
                              </a>
                            ) : (
                              <span className="text-muted-foreground">-</span>
                            )}
                          </TableCell>
                          <TableCell className="text-muted-foreground">
                            {institution.createdAt
                              ? new Date(
                                  institution.createdAt,
                                ).toLocaleDateString()
                              : "Unknown"}
                          </TableCell>
                          <TableCell>
                            <Button
                              size="sm"
                              variant={
                                selectedInstitution === institution.id
                                  ? "default"
                                  : "outline"
                              }
                              onClick={() =>
                                setSelectedInstitution(institution.id)
                              }
                            >
                              {selectedInstitution === institution.id
                                ? "Selected"
                                : "Manage Programmes"}
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="programmes">
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-xl font-semibold">
                  Programmes for{" "}
                  {
                    institutions?.find((i) => i.id === selectedInstitution)
                      ?.name
                  }
                </h2>
                <p className="text-sm text-muted-foreground mt-1">
                  {programmes?.length || 0} programmes
                </p>
              </div>
              <div className="flex gap-2">
                <Dialog
                  open={isBulkUploadDialogOpen}
                  onOpenChange={setIsBulkUploadDialogOpen}
                >
                  <DialogTrigger asChild>
                    <Button variant="outline" className="gap-2">
                      <Upload className="h-4 w-4" />
                      Bulk Upload
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-2xl">
                    <DialogHeader>
                      <DialogTitle>Bulk Upload Programmes</DialogTitle>
                      <DialogDescription>
                        Upload multiple programmes via JSON or CSV format
                      </DialogDescription>
                    </DialogHeader>
                    <form onSubmit={handleBulkUpload}>
                      <div className="space-y-4 py-4">
                        <div className="flex gap-2">
                          <Button
                            type="button"
                            variant={
                              bulkFormat === "json" ? "default" : "outline"
                            }
                            size="sm"
                            onClick={() => setBulkFormat("json")}
                            className="gap-2"
                          >
                            <FileJson className="h-4 w-4" />
                            JSON Format
                          </Button>
                          <Button
                            type="button"
                            variant={
                              bulkFormat === "csv" ? "default" : "outline"
                            }
                            size="sm"
                            onClick={() => setBulkFormat("csv")}
                            className="gap-2"
                          >
                            <FileSpreadsheet className="h-4 w-4" />
                            CSV Format
                          </Button>
                        </div>

                        <div className="space-y-2">
                          <Label>
                            {bulkFormat === "json" ? "JSON Data" : "CSV Data"}
                          </Label>
                          <Textarea
                            value={bulkData}
                            onChange={(e) => setBulkData(e.target.value)}
                            placeholder={
                              bulkFormat === "json"
                                ? `[\n  {\n    "name": "Computer Science",\n    "code": "CS",\n    "degree": "Bachelor",\n    "duration": 4,\n    "description": "Bachelor of Computer Science"\n  }\n]`
                                : `name,code,degree,duration,description\nComputer Science,CS,Bachelor,4,Bachelor of Computer Science\nBusiness Administration,BA,Bachelor,4,Bachelor of Business Administration`
                            }
                            className="font-mono text-sm min-h-[200px]"
                          />
                        </div>

                        <div className="rounded-md bg-muted p-4 text-sm">
                          <p className="font-medium mb-2">Format Guidelines:</p>
                          {bulkFormat === "json" ? (
                            <ul className="list-disc list-inside space-y-1 text-muted-foreground">
                              <li>Must be a valid JSON array</li>
                              <li>
                                Required field:{" "}
                                <code className="bg-background px-1 rounded">
                                  name
                                </code>
                              </li>
                              <li>
                                Optional fields:{" "}
                                <code className="bg-background px-1 rounded">
                                  code
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  degree
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  duration
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  description
                                </code>
                              </li>
                            </ul>
                          ) : (
                            <ul className="list-disc list-inside space-y-1 text-muted-foreground">
                              <li>First row must contain column headers</li>
                              <li>
                                Required column:{" "}
                                <code className="bg-background px-1 rounded">
                                  name
                                </code>
                              </li>
                              <li>
                                Optional columns:{" "}
                                <code className="bg-background px-1 rounded">
                                  code
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  degree
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  duration
                                </code>
                                ,{" "}
                                <code className="bg-background px-1 rounded">
                                  description
                                </code>
                              </li>
                            </ul>
                          )}
                        </div>
                      </div>
                      <DialogFooter>
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => setIsBulkUploadDialogOpen(false)}
                        >
                          Cancel
                        </Button>
                        <Button
                          type="submit"
                          disabled={bulkUploadMutation.isPending}
                        >
                          {bulkUploadMutation.isPending
                            ? "Uploading..."
                            : "Upload Programmes"}
                        </Button>
                      </DialogFooter>
                    </form>
                  </DialogContent>
                </Dialog>

                <Dialog
                  open={isProgrammeDialogOpen}
                  onOpenChange={setIsProgrammeDialogOpen}
