                  <DialogTrigger asChild>
                    <Button className="gap-2">
                      <Plus className="h-4 w-4" />
                      Add Programme
                    </Button>
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Add New Programme</DialogTitle>
                      <DialogDescription>
                        Create a new programme for this institution
                      </DialogDescription>
                    </DialogHeader>
                    <form onSubmit={handleCreateProgramme}>
                      <div className="space-y-4 py-4">
                        <div className="space-y-2">
                          <Label htmlFor="prog-name">Programme Name *</Label>
                          <Input
                            id="prog-name"
                            placeholder="e.g., Computer Science"
                            value={newProgramme.name}
                            onChange={(e) =>
                              setNewProgramme({
                                ...newProgramme,
                                name: e.target.value,
                              })
                            }
                            required
                          />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-2">
                            <Label htmlFor="code">Programme Code</Label>
                            <Input
                              id="code"
                              placeholder="e.g., CS"
                              value={newProgramme.code}
                              onChange={(e) =>
                                setNewProgramme({
                                  ...newProgramme,
                                  code: e.target.value,
                                })
                              }
                            />
                          </div>
                          <div className="space-y-2">
                            <Label htmlFor="degree">Degree</Label>
                            <Input
                              id="degree"
                              placeholder="e.g., Bachelor"
                              value={newProgramme.degree}
                              onChange={(e) =>
                                setNewProgramme({
                                  ...newProgramme,
                                  degree: e.target.value,
                                })
                              }
                            />
                          </div>
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="duration">Duration (years)</Label>
                          <Input
                            id="duration"
                            type="number"
                            min="1"
                            max="10"
                            placeholder="e.g., 4"
                            value={newProgramme.duration}
                            onChange={(e) =>
                              setNewProgramme({
                                ...newProgramme,
                                duration: e.target.value,
                              })
                            }
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="prog-description">Description</Label>
                          <Textarea
                            id="prog-description"
                            placeholder="e.g., Bachelor of Computer Science"
                            value={newProgramme.description}
                            onChange={(e) =>
                              setNewProgramme({
                                ...newProgramme,
                                description: e.target.value,
                              })
                            }
                          />
                        </div>
                      </div>
                      <DialogFooter>
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => setIsProgrammeDialogOpen(false)}
                        >
                          Cancel
                        </Button>
                        <Button
                          type="submit"
                          disabled={createProgrammeMutation.isPending}
                        >
                          {createProgrammeMutation.isPending
                            ? "Creating..."
                            : "Create Programme"}
                        </Button>
                      </DialogFooter>
                    </form>
                  </DialogContent>
                </Dialog>
              </div>
            </div>

            <Card>
              <CardContent className="pt-6">
                {!programmes ? (
                  <div className="space-y-3">
                    {[1, 2, 3].map((i) => (
                      <Skeleton key={i} className="h-16 w-full" />
                    ))}
                  </div>
                ) : programmes.length === 0 ? (
                  <div className="text-center py-12 text-muted-foreground">
                    <GraduationCap className="h-16 w-16 mx-auto mb-4 opacity-20" />
                    <p>No programmes found</p>
                    <p className="text-sm mt-2">
                      Click "Add Programme" or "Bulk Upload" to add programmes
                    </p>
                  </div>
                ) : (
                  <div className="rounded-md border">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Programme Name</TableHead>
                          <TableHead>Code</TableHead>
                          <TableHead>Degree</TableHead>
                          <TableHead>Duration</TableHead>
                          <TableHead>Description</TableHead>
                          <TableHead>Actions</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {programmes.map((programme) => (
                          <TableRow key={programme.id}>
                            <TableCell className="font-medium">
                              <div className="flex items-center gap-3">
                                <div className="h-10 w-10 rounded-md bg-primary/10 flex items-center justify-center">
                                  <GraduationCap className="h-5 w-5 text-primary" />
                                </div>
                                {programme.name}
                              </div>
                            </TableCell>
                            <TableCell>{programme.code || "-"}</TableCell>
                            <TableCell>{programme.degree || "-"}</TableCell>
                            <TableCell>
                              {programme.duration
                                ? `${programme.duration} years`
                                : "-"}
                            </TableCell>
                            <TableCell className="text-muted-foreground max-w-xs truncate">
                              {programme.description || "-"}
                            </TableCell>
                            <TableCell>
                              <Button
                                size="sm"
                                variant="ghost"
                                className="text-destructive hover:text-destructive hover:bg-destructive/10"
                                onClick={() => {
                                  if (
                                    confirm(
                                      "Are you sure you want to delete this programme?",
                                    )
                                  ) {
                                    deleteProgrammeMutation.mutate(
                                      programme.id,
                                    );
                                  }
                                }}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

