import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Pencil, Trash2, Plus, Tag, Search, RefreshCw, Palette, Merge } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";

interface BlogTag {
  id: string;
  name: string;
  slug: string;
  color: string | null;
  usageCount: number;
  createdAt: string;
}

export default function BlogTags() {
  const queryClient = useQueryClient();
  const { toast } = useToast();

  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);
  const [deleteConfirmName, setDeleteConfirmName] = useState<string>("");
  const [newTagName, setNewTagName] = useState("");
  const [newTagColor, setNewTagColor] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [selectedTags, setSelectedTags] = useState<Set<string>>(new Set());
  const [editingTag, setEditingTag] = useState<BlogTag | null>(null);
  const [editForm, setEditForm] = useState({ name: "", slug: "", color: "" });
  const [showMergeDialog, setShowMergeDialog] = useState(false);
  const [mergeSourceTag, setMergeSourceTag] = useState<string>("");
  const [mergeTargetTag, setMergeTargetTag] = useState<string>("");

  const { data: tags = [], isLoading, refetch } = useQuery<BlogTag[]>({
    queryKey: ["/api/blog/tags"],
  });

  const filteredTags = tags.filter((tag) => {
    const matchesSearch = searchQuery === "" || tag.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = filterStatus === "all" || 
      (filterStatus === "published" && tag.usageCount > 0) ||
      (filterStatus === "unused" && tag.usageCount === 0);
    return matchesSearch && matchesStatus;
  });

  const createTagMutation = useMutation({
    mutationFn: async (data: { name: string; color?: string }) => {
      const slug = data.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
      const response = await fetch("/api/admin/blog/tags", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: data.name, slug, color: data.color || null }),
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to create tag");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog/tags"] });
      setNewTagName("");
      setNewTagColor("");
      toast({ title: "Success", description: "Tag created successfully" });
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to create tag", variant: "destructive" });
    },
  });

  const updateTagMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: { name?: string; slug?: string; color?: string | null } }) => {
      const response = await fetch(`/api/admin/blog/tags/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to update tag");
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog/tags"] });
      setEditingTag(null);
      toast({ title: "Success", description: "Tag updated successfully" });
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to update tag", variant: "destructive" });
    },
  });

  const deleteTagMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await fetch(`/api/admin/blog/tags/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to delete tag");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog/tags"] });
      setDeleteConfirmId(null);
      toast({ title: "Success", description: "Tag deleted successfully" });
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to delete tag", variant: "destructive" });
    },
  });

  const bulkDeleteMutation = useMutation({
    mutationFn: async (ids: string[]) => {
      const response = await fetch("/api/admin/blog/tags/bulk-delete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids }),
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to bulk delete tags");
    },
    onSuccess: (_, ids) => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog/tags"] });
      setSelectedTags(new Set());
      toast({ title: "Success", description: `${ids.length} tags deleted` });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete some tags",
        variant: "destructive"
      });
    },
  });

  const mergeTagsMutation = useMutation({
    mutationFn: async ({ sourceTagId, targetTagId }: { sourceTagId: string; targetTagId: string }) => {
      const response = await fetch("/api/admin/blog/tags/merge", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceTagId, targetTagId }),
        credentials: "include",
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || "Failed to merge tags");
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/blog/tags"] });
      setShowMergeDialog(false);
      setMergeSourceTag("");
      setMergeTargetTag("");
      toast({ title: "Success", description: "Tags merged successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message || "Failed to merge tags", variant: "destructive" });
    },
  });

  const handleAddTag = () => {
    if (newTagName.trim()) {
      createTagMutation.mutate({ name: newTagName.trim(), color: newTagColor || undefined });
    }
  };

  const handleEdit = (tag: BlogTag) => {
    setEditingTag(tag);
    setEditForm({
      name: tag.name,
      slug: tag.slug,
      color: tag.color || "",
    });
  };

  const handleUpdateTag = () => {
    if (!editingTag || !editForm.name.trim()) return;

    const updates: { name?: string; slug?: string; color?: string | null } = {};
    if (editForm.name !== editingTag.name) updates.name = editForm.name;
    if (editForm.slug !== editingTag.slug) updates.slug = editForm.slug;
    if (editForm.color !== editingTag.color) {
      updates.color = editForm.color.trim() === "" ? null : editForm.color;
    }

    updateTagMutation.mutate({ id: editingTag.id, data: updates });
  };

  const handleDelete = (id: string, name: string) => {
    setDeleteConfirmId(id);
    setDeleteConfirmName(name);
  };

  const handleReload = () => {
    refetch();
    toast({ title: "Refreshed", description: "Tags list has been reloaded" });
  };

  const toggleTagSelection = (id: string) => {
    const newSet = new Set(selectedTags);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedTags(newSet);
  };

  const selectAllTags = () => {
    if (selectedTags.size === filteredTags.length) {
      setSelectedTags(new Set());
    } else {
      setSelectedTags(new Set(filteredTags.map(t => t.id)));
    }
  };

  const handleMergeTags = () => {
    if (!mergeSourceTag || !mergeTargetTag) {
      toast({ title: "Error", description: "Please select both source and target tags", variant: "destructive" });
      return;
    }

    if (mergeSourceTag === mergeTargetTag) {
      toast({ title: "Error", description: "Source and target tags cannot be the same", variant: "destructive" });
      return;
    }

    mergeTagsMutation.mutate({ sourceTagId: mergeSourceTag, targetTagId: mergeTargetTag });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-muted-foreground">Loading tags...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-7xl mx-auto p-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold">Blog Tags</h1>
          <p className="text-muted-foreground mt-2">
            Manage tags for blog posts
          </p>
        </div>

        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-medium text-muted-foreground">Total Tags</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{tags.length}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-medium text-muted-foreground">Published</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-green-600">
                  {tags.filter(t => t.usageCount > 0).length}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-medium text-muted-foreground">Unused</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-orange-600">
                  {tags.filter(t => t.usageCount === 0).length}
                </div>
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Tag className="h-5 w-5" />
                Add New Tag
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex gap-3 flex-wrap">
                <div className="flex-1 min-w-[200px]">
                  <Input
                    data-testid="input-tag-name"
                    value={newTagName}
                    onChange={(e) => setNewTagName(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleAddTag()}
                    placeholder="Enter tag name (e.g., AI, Laravel Boost, PHP)"
                  />
                </div>
                <div className="w-32">
                  <div className="flex gap-2">
                    <Input
                      data-testid="input-tag-color"
                      type="color"
                      value={newTagColor || "#3B82F6"}
                      onChange={(e) => setNewTagColor(e.target.value)}
                      className="w-12 h-10 p-1 cursor-pointer"
                      title="Pick a color"
                    />
                    <Input
                      data-testid="input-tag-color-text"
                      value={newTagColor}
                      onChange={(e) => setNewTagColor(e.target.value)}
                      placeholder="#3B82F6"
                      className="flex-1"
                    />
                  </div>
                </div>
                <Button
                  data-testid="button-create-tag"
                  onClick={handleAddTag}
                  disabled={!newTagName.trim() || createTagMutation.isPending}
                >
                  <Plus className="mr-2 h-4 w-4" />
                  Create
                </Button>
                <Button 
                  data-testid="button-reload-tags"
                  variant="outline"
                  onClick={handleReload}
                >
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Reload
                </Button>
                <Button
                  data-testid="button-merge-tags"
                  variant="outline"
                  onClick={() => setShowMergeDialog(true)}
                >
                  <Merge className="h-4 w-4 mr-2" />
                  Merge Tags
                </Button>
              </div>
            </CardContent>
          </Card>

          <div className="flex gap-4 flex-wrap">
            <div className="flex-1 min-w-[250px]">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
                <Input
                  data-testid="input-search-tags"
                  placeholder="Search..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger data-testid="select-filter-status" className="w-[180px]">
                <SelectValue placeholder="Filters" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="published">Published</SelectItem>
                <SelectItem value="unused">Unused</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {selectedTags.size > 0 && (
            <div className="flex items-center gap-4 p-4 bg-muted rounded-lg">
              <span className="text-sm font-medium">{selectedTags.size} selected</span>
              <Button
                size="sm"
                variant="destructive"
                onClick={() => bulkDeleteMutation.mutate(Array.from(selectedTags))}
              >
                <Trash2 className="mr-2 h-4 w-4" />
                Delete Selected
              </Button>
            </div>
          )}

          <Card>
            <CardContent className="p-0">
              <div className="border-b">
                <div className="grid grid-cols-12 gap-4 p-4 font-medium text-sm bg-muted/50">
                  <div className="col-span-1">
                    <Checkbox
                      checked={selectedTags.size === filteredTags.length && filteredTags.length > 0}
                      onCheckedChange={selectAllTags}
                    />
                  </div>
                  <div className="col-span-1">ID</div>
                  <div className="col-span-4">NAME</div>
                  <div className="col-span-3">CREATED AT</div>
                  <div className="col-span-2">STATUS</div>
                  <div className="col-span-1">OPERATIONS</div>
                </div>
              </div>

              {filteredTags.length === 0 ? (
                <div className="p-12 text-center">
                  <p className="text-muted-foreground">
                    {searchQuery || filterStatus !== "all"
                      ? "No tags match your filters"
                      : "No tags yet. Create your first tag above."}
                  </p>
                </div>
              ) : (
                <div>
                  {filteredTags.map((tag) => (
                    <div
                      key={tag.id}
                      data-testid={`row-tag-${tag.id}`}
                      className="grid grid-cols-12 gap-4 p-4 border-b hover:bg-muted/30 transition-colors items-center"
                    >
                      <div className="col-span-1">
                        <Checkbox
                          data-testid={`checkbox-tag-${tag.id}`}
                          checked={selectedTags.has(tag.id)}
                          onCheckedChange={() => toggleTagSelection(tag.id)}
                        />
                      </div>
                      <div className="col-span-1 text-sm text-muted-foreground">
                        {parseInt(tag.id.replace(/\D/g, '').slice(-2)) || tag.id.slice(-2)}
                      </div>
                      <div className="col-span-4">
                        <div className="flex items-center gap-2">
                          {tag.color ? (
                            <div
                              className="h-4 w-4 rounded border"
                              style={{ backgroundColor: tag.color }}
                              title={tag.color}
                            />
                          ) : (
                            <Tag className="h-4 w-4 text-muted-foreground" />
                          )}
                          <span className="font-medium text-primary" data-testid={`text-tag-name-${tag.id}`}>
                            {tag.name}
                          </span>
                          {tag.usageCount > 0 && (
                            <span className="text-xs text-muted-foreground">
                              ({tag.usageCount})
                            </span>
                          )}
                        </div>
                      </div>
                      <div className="col-span-3 text-sm text-muted-foreground">
                        {format(new Date(tag.createdAt), "yyyy-MM-dd")}
                      </div>
                      <div className="col-span-2">
                        <Badge
                          variant={tag.usageCount > 0 ? "default" : "secondary"}
                          className={tag.usageCount > 0 ? "bg-green-500" : ""}
                        >
                          {tag.usageCount > 0 ? "Published" : "Unused"}
                        </Badge>
                      </div>
                      <div className="col-span-1">
                        <div className="flex items-center gap-2">
                          <Button
                            data-testid={`button-edit-tag-${tag.id}`}
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEdit(tag)}
                            className="h-8 w-8 p-0 hover:bg-primary/10"
                          >
                            <Pencil className="h-4 w-4 text-blue-600" />
                          </Button>
                          <Button
                            data-testid={`button-delete-tag-${tag.id}`}
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDelete(tag.id, tag.name)}
                            className="h-8 w-8 p-0 hover:bg-destructive/10"
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {filteredTags.length > 0 && (
                <div className="p-4 text-sm text-muted-foreground border-t">
                  Show from 1 to {filteredTags.length} in {filteredTags.length} records
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        <Dialog open={editingTag !== null} onOpenChange={(open) => !open && setEditingTag(null)}>
          <DialogContent className="sm:max-w-[500px]">
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <Pencil className="h-5 w-5" />
                Edit Tag
              </DialogTitle>
              <DialogDescription>
                Update tag name, slug, and color
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="edit-name">Tag Name *</Label>
                <Input
                  id="edit-name"
                  data-testid="input-edit-tag-name"
                  value={editForm.name}
                  onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                  placeholder="Enter tag name"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="edit-slug">Slug</Label>
                <Input
                  id="edit-slug"
                  data-testid="input-edit-tag-slug"
                  value={editForm.slug}
                  onChange={(e) => setEditForm({ ...editForm, slug: e.target.value })}
                  placeholder="auto-generated-from-name"
                />
                <p className="text-xs text-muted-foreground">
                  URL: /blog/tag/{editForm.slug || editForm.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")}
                </p>
              </div>
              <div className="space-y-2">
                <Label htmlFor="edit-color">Color</Label>
                <div className="flex gap-2">
                  <Input
                    id="edit-color"
                    data-testid="input-edit-tag-color-picker"
                    type="color"
                    value={editForm.color || "#3B82F6"}
                    onChange={(e) => setEditForm({ ...editForm, color: e.target.value })}
                    className="w-16 h-10 p-1 cursor-pointer"
                  />
                  <Input
                    data-testid="input-edit-tag-color-text"
                    value={editForm.color}
                    onChange={(e) => setEditForm({ ...editForm, color: e.target.value })}
                    placeholder="#3B82F6"
                    className="flex-1"
                  />
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button
                variant="outline"
                onClick={() => setEditingTag(null)}
                data-testid="button-cancel-edit"
              >
                Cancel
              </Button>
              <Button
                onClick={handleUpdateTag}
                disabled={!editForm.name.trim() || updateTagMutation.isPending}
                data-testid="button-save-edit"
              >
                {updateTagMutation.isPending ? "Saving..." : "Save Changes"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <AlertDialog open={deleteConfirmId !== null} onOpenChange={() => setDeleteConfirmId(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete Tag?</AlertDialogTitle>
              <AlertDialogDescription>
                Are you sure you want to delete "{deleteConfirmName}"? This action cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={() => setDeleteConfirmId(null)}>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => deleteConfirmId && deleteTagMutation.mutate(deleteConfirmId)}
                className="bg-destructive hover:bg-destructive/90"
                data-testid="button-confirm-delete"
              >
                Delete
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        <Dialog open={showMergeDialog} onOpenChange={setShowMergeDialog}>
          <DialogContent className="sm:max-w-[500px]">
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <Merge className="h-5 w-5" />
                Merge Tags
              </DialogTitle>
              <DialogDescription>
                Merge two tags by moving all posts from the source tag to the target tag. The source tag will be deleted.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="source-tag">Source Tag (will be deleted) *</Label>
                <Select value={mergeSourceTag} onValueChange={setMergeSourceTag}>
                  <SelectTrigger id="source-tag" data-testid="select-merge-source">
                    <SelectValue placeholder="Select tag to merge from" />
                  </SelectTrigger>
                  <SelectContent>
                    {tags.filter(t => t.id !== mergeTargetTag).map((tag) => (
                      <SelectItem key={tag.id} value={tag.id}>
                        {tag.name} ({tag.usageCount} {tag.usageCount === 1 ? 'post' : 'posts'})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="target-tag">Target Tag (will receive all posts) *</Label>
                <Select value={mergeTargetTag} onValueChange={setMergeTargetTag}>
                  <SelectTrigger id="target-tag" data-testid="select-merge-target">
                    <SelectValue placeholder="Select tag to merge into" />
                  </SelectTrigger>
                  <SelectContent>
                    {tags.filter(t => t.id !== mergeSourceTag).map((tag) => (
                      <SelectItem key={tag.id} value={tag.id}>
                        {tag.name} ({tag.usageCount} {tag.usageCount === 1 ? 'post' : 'posts'})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              {mergeSourceTag && mergeTargetTag && (
                <div className="p-4 bg-blue-50 dark:bg-blue-950/20 rounded-md">
                  <p className="text-sm text-blue-600 dark:text-blue-400">
                    <strong>Preview:</strong> All posts tagged with "{tags.find(t => t.id === mergeSourceTag)?.name}" will be moved to "{tags.find(t => t.id === mergeTargetTag)?.name}". The "{tags.find(t => t.id === mergeSourceTag)?.name}" tag will be permanently deleted.
                  </p>
                </div>
              )}
            </div>
            <DialogFooter>
              <Button
                variant="outline"
                onClick={() => {
                  setShowMergeDialog(false);
                  setMergeSourceTag("");
                  setMergeTargetTag("");
                }}
                data-testid="button-cancel-merge"
              >
                Cancel
              </Button>
              <Button
                onClick={handleMergeTags}
                disabled={!mergeSourceTag || !mergeTargetTag || mergeTagsMutation.isPending}
                data-testid="button-confirm-merge"
              >
                {mergeTagsMutation.isPending ? "Merging..." : "Merge Tags"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

