import { LogOut } from "lucide-react";
import { useLocation } from "wouter";
import { useQueryClient } from "@tanstack/react-query";
import {
  SidebarFooter as BaseSidebarFooter,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  useSidebar,
} from "@/components/ui/sidebar";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Separator } from "@/components/ui/separator";
import { NavItem } from "./NavItem";
import { isPathActive } from "@/config/navigation";
import type { NavItem as NavItemType } from "@/config/navigation";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";

interface SidebarFooterProps {
  footerItems?: NavItemType[];
}

export function SidebarFooter({ footerItems = [] }: SidebarFooterProps) {
  const [location, setLocation] = useLocation();
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const { state } = useSidebar();
  const isCollapsed = state === "collapsed";

  const handleLogout = async () => {
    try {
      const response = await fetch("/api/auth/logout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });

      if (response.ok) {
        queryClient.setQueryData(["/api/auth/user"], null);
        await queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
        setLocation("/login");

        toast({
          title: "Logged out successfully",
          description: "See you next time!",
        });
      }
    } catch (error) {
      toast({
        title: "Logout failed",
        description: "Please try again",
        variant: "destructive",
      });
    }
  };

  const logoutButton = (
    <SidebarMenuButton
      onClick={handleLogout}
      data-testid="button-logout"
      className={cn(
        "group h-10 transition-all duration-200 text-muted-foreground hover:bg-destructive/10 hover:text-destructive",
        isCollapsed ? "w-10 justify-center px-0" : "px-3"
      )}
    >
      <div className="flex items-center gap-3">
        <LogOut className="w-5 h-5 flex-shrink-0" />
        {!isCollapsed && (
          <span className="text-sm font-medium">Logout</span>
        )}
      </div>
    </SidebarMenuButton>
  );

  return (
    <BaseSidebarFooter className="mt-auto border-t border-border p-2">
      {footerItems.length > 0 && (
        <>
          <SidebarMenu className="space-y-1 px-2 mb-2">
            {footerItems.map((item) => {
              const isActive = isPathActive(item.url, location);
              return <NavItem key={item.title} item={item} isActive={isActive} />;
            })}
          </SidebarMenu>
          <Separator className="my-2" />
        </>
      )}

      <SidebarMenu className="px-2">
        <SidebarMenuItem>
          {isCollapsed ? (
            <Tooltip>
              <TooltipTrigger asChild>
                {logoutButton}
              </TooltipTrigger>
              <TooltipContent side="right" className="font-medium">
                Logout
              </TooltipContent>
            </Tooltip>
          ) : (
            logoutButton
          )}
        </SidebarMenuItem>
      </SidebarMenu>
    </BaseSidebarFooter>
  );
}

client/src/components/sidebar/Collapsibl.content:
import { useState } from "react";
import { Link, useLocation } from "wouter";
import {
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubItem,
  SidebarMenuSubButton,
  useSidebar,
} from "@/components/ui/sidebar";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import type { NavItem } from "@/config/navigation";
import { isPathActive, isPathWithin } from "@/config/navigation";

interface CollapsibleNavGroupProps {
  item: NavItem;
}

export function CollapsibleNavGroup({ item }: CollapsibleNavGroupProps) {
  const [location, setLocation] = useLocation();
  const [isOpen, setIsOpen] = useState(() => isPathWithin(item.url, location));
  const [popoverOpen, setPopoverOpen] = useState(false);
  const { state } = useSidebar();
  const isWithinSection = item.children?.some(child => isPathActive(child.url, location)) || false;
  const isCollapsed = state === "collapsed";

  if (!item.children || item.children.length === 0) {
    return null;
  }

  const handleNavigation = (url: string) => {
    setPopoverOpen(false);
    setLocation(url);
  };

  if (isCollapsed) {
    return (
      <SidebarMenuItem>
        <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
          <Tooltip>
            <TooltipTrigger asChild>
              <PopoverTrigger asChild>
                <SidebarMenuButton
                  data-testid={`nav-${item.title.toLowerCase().replace(/\s+/g, '-')}`}
                  className={cn(
                    "group h-10 w-10 justify-center px-0 transition-all duration-200",
                    isWithinSection 
                      ? "bg-primary/10 border border-primary/20" 
                      : "hover:bg-accent"
                  )}
                >
                  <item.icon className={cn(
                    "w-5 h-5 flex-shrink-0 transition-colors",
                    isWithinSection ? "text-primary" : "text-muted-foreground group-hover:text-foreground"
                  )} />
                </SidebarMenuButton>
              </PopoverTrigger>
            </TooltipTrigger>
            <TooltipContent side="right" className="font-medium">
              {item.title}
            </TooltipContent>
          </Tooltip>
          <PopoverContent 
            side="right" 
            align="start" 
            sideOffset={8}
            className="w-48 p-2"
            data-testid={`popover-${item.title.toLowerCase().replace(/\s+/g, '-')}`}
          >
            <div className="space-y-1">
              {item.children.map((subItem) => {
                const isSubActive = isPathActive(subItem.url, location);
                return (
                  <button
                    key={subItem.title}
                    onClick={() => handleNavigation(subItem.url)}
                    data-testid={`nav-${item.title.toLowerCase()}-${subItem.title.toLowerCase().replace(/\s+/g, '-')}`}
                    className={cn(
                      "w-full flex items-center gap-2.5 px-3 py-2 rounded-md text-sm transition-colors",
                      isSubActive 
                        ? "bg-primary/10 text-primary font-medium" 
                        : "text-muted-foreground hover:bg-accent hover:text-foreground"
                    )}
                  >
                    <subItem.icon className="w-4 h-4 flex-shrink-0" />
                    <span className="truncate">{subItem.title}</span>
                  </button>
                );
              })}
            </div>
          </PopoverContent>
        </Popover>
      </SidebarMenuItem>
    );
  }

  return (
    <Collapsible open={isOpen} onOpenChange={setIsOpen} className="group/collapsible">
      <SidebarMenuItem>
        <CollapsibleTrigger asChild>
          <SidebarMenuButton
            data-testid={`nav-${item.title.toLowerCase().replace(/\s+/g, '-')}`}
            className={cn(
              "group h-10 px-3 transition-all duration-200",
              isWithinSection 
                ? "bg-primary/10 border border-primary/20" 
                : "hover:bg-accent"
            )}
          >
            <div className="flex items-center gap-3 w-full">
              <item.icon className={cn(
                "w-5 h-5 flex-shrink-0 transition-colors",
                isWithinSection ? "text-primary" : "text-muted-foreground group-hover:text-foreground"
              )} />
              <span className={cn(
                "text-sm font-medium truncate flex-1 transition-colors",
                isWithinSection ? "text-foreground" : "text-muted-foreground group-hover:text-foreground"
              )}>
                {item.title}
              </span>
              <ChevronRight className={cn(
                "w-4 h-4 text-muted-foreground transition-transform duration-200",
                isOpen && "rotate-90"
              )} />
            </div>
          </SidebarMenuButton>
        </CollapsibleTrigger>
        <CollapsibleContent className="transition-all duration-200">
          <SidebarMenuSub className="ml-4 mt-1 space-y-0.5 border-l border-border pl-3">
            {item.children.map((subItem) => {
              const isSubActive = isPathActive(subItem.url, location);
              return (
                <SidebarMenuSubItem key={subItem.title}>
                  <SidebarMenuSubButton
                    asChild
                    isActive={isSubActive}
