    } else {
      console.log(`Subscription plan already exists: ${plan.name}`);
    }
  }

  console.log("Subscription plans seeded successfully!");
}

seedSubscriptionPlans()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error("Error seeding subscription plans:", error);
    process.exit(1);
  });

