import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Plus, Users, BookOpen, Edit, Trash2, Search } from "lucide-react";
import type { SchoolClass, SchoolUser } from "@shared/schema";

export default function ClassesPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingClass, setEditingClass] = useState<SchoolClass | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    level: "",
    section: "",
    capacity: "",
    classTeacherId: "",
    description: "",
  });

  const { data: classes, isLoading, error, refetch } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const { data: teachers } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "teacher" }],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/classes", {
        ...data,
        level: data.level ? parseInt(data.level) : null,
        capacity: data.capacity ? parseInt(data.capacity) : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/classes"] });
      toast({ title: "Class created successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to create class", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: typeof formData }) => {
      return apiRequest("PATCH", `/api/school/classes/${id}`, {
        ...data,
        level: data.level ? parseInt(data.level) : null,
        capacity: data.capacity ? parseInt(data.capacity) : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/classes"] });
      toast({ title: "Class updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update class", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/classes/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/classes"] });
      toast({ title: "Class deleted successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete class", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({ name: "", level: "", section: "", capacity: "", classTeacherId: "", description: "" });
    setEditingClass(null);
  };

  const handleEdit = (classItem: SchoolClass) => {
    setEditingClass(classItem);
    setFormData({
      name: classItem.name,
      level: classItem.level?.toString() || "",
      section: classItem.section || "",
      capacity: classItem.capacity?.toString() || "",
      classTeacherId: classItem.classTeacherId || "",
      description: classItem.description || "",
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingClass) {
      updateMutation.mutate({ id: editingClass.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const filteredClasses = classes?.filter((c) =>
    c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.section?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Classes"
          description="Manage your school classes and sections"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Academic", href: "/school/classes" },
            { label: "Classes" }
          ]}
        />
        <TableSkeleton rows={5} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Classes"
          description="Manage your school classes and sections"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Academic", href: "/school/classes" },
            { label: "Classes" }
          ]}
        />
        <ErrorState 
          message="Failed to load classes. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Classes"
        description="Manage your school classes and sections"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Academic", href: "/school/classes" },
          { label: "Classes" }
        ]}
        actions={
          <Button onClick={() => setIsDialogOpen(true)} data-testid="button-add-class">
            <Plus className="h-4 w-4 mr-2" />
            <span className="hidden sm:inline">Add Class</span>
            <span className="sm:hidden">Add</span>
          </Button>
        }
      />

      <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
          <DialogContent className="max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingClass ? "Edit Class" : "Add New Class"}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="name">Class Name</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., JSS 1, SS 2"
                    required
                    data-testid="input-class-name"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="section">Section</Label>
                  <Input
                    id="section"
                    value={formData.section}
                    onChange={(e) => setFormData({ ...formData, section: e.target.value })}
                    placeholder="e.g., A, B, Science"
                    data-testid="input-class-section"
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="level">Level (Numeric)</Label>
                  <Input
                    id="level"
                    type="number"
                    value={formData.level}
                    onChange={(e) => setFormData({ ...formData, level: e.target.value })}
                    placeholder="e.g., 1, 2, 3"
                    data-testid="input-class-level"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="capacity">Capacity</Label>
                  <Input
                    id="capacity"
                    type="number"
                    value={formData.capacity}
                    onChange={(e) => setFormData({ ...formData, capacity: e.target.value })}
                    placeholder="Maximum students"
                    data-testid="input-class-capacity"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="classTeacher">Class Teacher</Label>
                <Select
                  value={formData.classTeacherId}
                  onValueChange={(value) => setFormData({ ...formData, classTeacherId: value })}
                >
                  <SelectTrigger data-testid="select-class-teacher">
                    <SelectValue placeholder="Select a teacher" />
                  </SelectTrigger>
                  <SelectContent>
                    {teachers?.map((teacher) => (
                      <SelectItem key={teacher.id} value={teacher.id}>
                        {teacher.firstName} {teacher.lastName}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Input
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Optional description"
                  data-testid="input-class-description"
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                  Cancel
                </Button>
                <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending} data-testid="button-save-class">
                  {editingClass ? "Update" : "Create"} Class
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <CardTitle className="flex items-center gap-2">
              <BookOpen className="h-5 w-5" />
              All Classes ({classes?.length || 0})
            </CardTitle>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search classes..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 w-64"
                data-testid="input-search-classes"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {filteredClasses && filteredClasses.length > 0 ? (
            <ScrollArea className="w-full">
              <div className="min-w-[600px]">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Class Name</TableHead>
                      <TableHead className="hidden sm:table-cell">Section</TableHead>
                      <TableHead className="hidden md:table-cell">Level</TableHead>
                      <TableHead className="hidden md:table-cell">Capacity</TableHead>
                      <TableHead className="hidden sm:table-cell">Students</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredClasses.map((classItem) => (
                      <TableRow key={classItem.id} data-testid={`row-class-${classItem.id}`}>
                        <TableCell className="font-medium">
                          <div>{classItem.name}</div>
                          <div className="text-xs text-muted-foreground sm:hidden">
                            {classItem.section && `Section ${classItem.section}`}
                          </div>
                        </TableCell>
                        <TableCell className="hidden sm:table-cell">{classItem.section || "-"}</TableCell>
                        <TableCell className="hidden md:table-cell">{classItem.level || "-"}</TableCell>
                        <TableCell className="hidden md:table-cell">{classItem.capacity || "-"}</TableCell>
                        <TableCell className="hidden sm:table-cell">
                          <div className="flex items-center gap-1">
                            <Users className="h-4 w-4 text-muted-foreground" />
                            <span>0</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge variant={classItem.isActive ? "default" : "secondary"}>
                            {classItem.isActive ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleEdit(classItem)}
                              data-testid={`button-edit-class-${classItem.id}`}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => deleteMutation.mutate(classItem.id)}
                              data-testid={`button-delete-class-${classItem.id}`}
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
          ) : (
            <EmptyState
              icon={BookOpen}
              title="No classes found"
              description={searchQuery ? "No classes match your search. Try a different search term." : "Create your first class to organize your students and curriculum."}
              action={searchQuery ? undefined : { label: "Add Class", onClick: () => setIsDialogOpen(true) }}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/timetable.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Plus, Clock, Calendar, Edit, Trash2, AlertCircle } from "lucide-react";
import type { SchoolClass, SchoolSubject, SchoolUser, TimetablePeriod, TimetableEntry } from "@shared/schema";

const DAYS_OF_WEEK = [
  { value: 1, label: "Monday" },
  { value: 2, label: "Tuesday" },
  { value: 3, label: "Wednesday" },
  { value: 4, label: "Thursday" },
  { value: 5, label: "Friday" },
];

export default function TimetablePage() {
  const { toast } = useToast();
  const [selectedClass, setSelectedClass] = useState<string>("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<TimetableEntry | null>(null);

  const [formData, setFormData] = useState({
    periodId: "",
    subjectId: "",
    teacherId: "",
    dayOfWeek: "1",
    room: "",
  });

  const { data: classes, isLoading: classesLoading, error: classesError, refetch: refetchClasses } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: teachers } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "teacher" }],
  });

  const { data: periods } = useQuery<TimetablePeriod[]>({
    queryKey: ["/api/school/timetable-periods"],
  });

  const { data: entries, isLoading, error: entriesError, refetch: refetchEntries } = useQuery<TimetableEntry[]>({
    queryKey: ["/api/school/timetable", { classId: selectedClass }],
    enabled: !!selectedClass,
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/timetable", {
        ...data,
        classId: selectedClass,
        dayOfWeek: parseInt(data.dayOfWeek),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/timetable"] });
      toast({ title: "Timetable entry added successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to add entry", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: typeof formData }) => {
      return apiRequest("PATCH", `/api/school/timetable/${id}`, {
        ...data,
        dayOfWeek: parseInt(data.dayOfWeek),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/timetable"] });
      toast({ title: "Timetable entry updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update entry", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/timetable/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/timetable"] });
      toast({ title: "Timetable entry deleted" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete entry", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({ periodId: "", subjectId: "", teacherId: "", dayOfWeek: "1", room: "" });
    setEditingEntry(null);
  };

  const handleEdit = (entry: TimetableEntry) => {
    setEditingEntry(entry);
    setFormData({
      periodId: entry.periodId,
      subjectId: entry.subjectId || "",
      teacherId: entry.teacherId || "",
      dayOfWeek: entry.dayOfWeek.toString(),
      room: entry.room || "",
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingEntry) {
      updateMutation.mutate({ id: editingEntry.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const getEntriesForDayAndPeriod = (day: number, periodId: string) => {
    return entries?.find((e) => e.dayOfWeek === day && e.periodId === periodId);
  };

  const getSubjectName = (id: string) => subjects?.find((s) => s.id === id)?.name || "";
  const getTeacherName = (id: string) => {
    const teacher = teachers?.find((t) => t.id === id);
    return teacher ? `${teacher.firstName} ${teacher.lastName}` : "";
  };
  const getPeriodName = (id: string) => periods?.find((p) => p.id === id)?.name || "";

  const sortedPeriods = periods?.slice().sort((a, b) => a.orderIndex - b.orderIndex);

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Timetable"
        description="Manage class schedules and timetables"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Academics", href: "/school/timetable" },
          { label: "Timetable" }
        ]}
      />

      <Card>
        <CardHeader className="flex flex-row items-center justify-between gap-2">
          <CardTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            Select Class
          </CardTitle>
          {selectedClass && (
            <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
              <DialogTrigger asChild>
                <Button data-testid="button-add-timetable-entry">
                  <Plus className="h-4 w-4 mr-2" />
                  Add Entry
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>{editingEntry ? "Edit Timetable Entry" : "Add Timetable Entry"}</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label>Day</Label>
                      <Select
                        value={formData.dayOfWeek}
                        onValueChange={(value) => setFormData({ ...formData, dayOfWeek: value })}
                      >
                        <SelectTrigger data-testid="select-timetable-day">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {DAYS_OF_WEEK.map((day) => (
                            <SelectItem key={day.value} value={day.value.toString()}>
                              {day.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label>Period</Label>
                      <Select
                        value={formData.periodId}
                        onValueChange={(value) => setFormData({ ...formData, periodId: value })}
                      >
                        <SelectTrigger data-testid="select-timetable-period">
                          <SelectValue placeholder="Select period" />
                        </SelectTrigger>
                        <SelectContent>
                          {sortedPeriods?.map((period) => (
                            <SelectItem key={period.id} value={period.id}>
                              {period.name} ({period.startTime} - {period.endTime})
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label>Subject</Label>
                    <Select
                      value={formData.subjectId}
                      onValueChange={(value) => setFormData({ ...formData, subjectId: value })}
                    >
                      <SelectTrigger data-testid="select-timetable-subject">
                        <SelectValue placeholder="Select subject" />
                      </SelectTrigger>
                      <SelectContent>
                        {subjects?.map((subject) => (
                          <SelectItem key={subject.id} value={subject.id}>
                            {subject.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>Teacher</Label>
                    <Select
                      value={formData.teacherId}
                      onValueChange={(value) => setFormData({ ...formData, teacherId: value })}
                    >
                      <SelectTrigger data-testid="select-timetable-teacher">
                        <SelectValue placeholder="Select teacher" />
                      </SelectTrigger>
                      <SelectContent>
                        {teachers?.map((teacher) => (
                          <SelectItem key={teacher.id} value={teacher.id}>
                            {teacher.firstName} {teacher.lastName}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="flex justify-end gap-2">
                    <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                      Cancel
                    </Button>
                    <Button type="submit" data-testid="button-save-timetable-entry">
                      {editingEntry ? "Update" : "Add"} Entry
                    </Button>
                  </div>
                </form>
              </DialogContent>
            </Dialog>
          )}
        </CardHeader>
        <CardContent>
          <Select value={selectedClass} onValueChange={setSelectedClass}>
            <SelectTrigger className="w-64" data-testid="select-timetable-class">
              <SelectValue placeholder="Select a class to view timetable" />
            </SelectTrigger>
            <SelectContent>
              {classes?.map((classItem) => (
                <SelectItem key={classItem.id} value={classItem.id}>
                  {classItem.name} {classItem.section ? `(${classItem.section})` : ""}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {selectedClass && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Clock className="h-5 w-5" />
              Weekly Schedule - {classes?.find((c) => c.id === selectedClass)?.name}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <TableSkeleton rows={6} columns={6} />
            ) : entriesError ? (
              <ErrorState
                title="Failed to load timetable"
                message="There was an error loading the timetable entries."
                onRetry={() => refetchEntries()}
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full border-collapse">
                  <thead>
                    <tr>
                      <th className="border p-2 bg-muted text-left min-w-[100px]">Period</th>
                      {DAYS_OF_WEEK.map((day) => (
                        <th key={day.value} className="border p-2 bg-muted text-center min-w-[150px]">
                          {day.label}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {sortedPeriods?.map((period) => (
                      <tr key={period.id}>
                        <td className="border p-2 bg-muted/50">
                          <div className="font-medium">{period.name}</div>
                          <div className="text-xs text-muted-foreground">
                            {period.startTime} - {period.endTime}
                          </div>
                          {period.isBreak && (
                            <Badge variant="secondary" className="mt-1 text-xs">Break</Badge>
                          )}
                        </td>
                        {DAYS_OF_WEEK.map((day) => {
                          const entry = getEntriesForDayAndPeriod(day.value, period.id);
                          return (
                            <td key={day.value} className="border p-2">
                              {period.isBreak ? (
                                <div className="text-center text-muted-foreground italic">
                                  Break
                                </div>
                              ) : entry ? (
                                <div className="space-y-1 group relative">
                                  <div className="font-medium text-sm">
                                    {getSubjectName(entry.subjectId || "")}
                                  </div>
                                  <div className="text-xs text-muted-foreground">
                                    {getTeacherName(entry.teacherId || "")}
                                  </div>
                                  {entry.room && (
                                    <Badge variant="outline" className="text-xs">{entry.room}</Badge>
                                  )}
                                  <div className="absolute top-0 right-0 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-6 w-6"
                                      onClick={() => handleEdit(entry)}
                                    >
                                      <Edit className="h-3 w-3" />
                                    </Button>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-6 w-6"
                                      onClick={() => deleteMutation.mutate(entry.id)}
                                    >
                                      <Trash2 className="h-3 w-3 text-destructive" />
                                    </Button>
                                  </div>
                                </div>
                              ) : (
                                <div className="text-center text-muted-foreground text-sm">
                                  -
                                </div>
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {!selectedClass && (
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">Select a Class</h3>
              <p className="text-muted-foreground">Choose a class above to view or edit its timetable.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/pages/school/dashboard.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Link } from "wouter";
import { PageHeader } from "@/components/page-header";
import { DashboardSkeleton, CardSkeleton } from "@/components/loading-skeleton";
import { ErrorState } from "@/components/empty-state";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Users,
  GraduationCap,
  BookOpen,
  Calendar,
  DollarSign,
  Bell,
  Clock,
  TrendingUp,
  UserCheck,
  FileText,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Timer,
  Megaphone,
  PlusCircle,
  ArrowRight,
  CalendarDays,
  Pin,
} from "lucide-react";

interface DashboardStats {
  totalStudents: number;
  totalTeachers: number;
  totalParents: number;
  totalClasses: number;
  totalSubjects: number;
  currentTerm: {
    id: string;
    name: string;
    sessionYear: string;
    startDate: string;
    endDate: string;
  } | null;
  attendance: {
    rate: number;
    today: {
      present: number;
      absent: number;
      late: number;
      total: number;
    };
  };
  fees: {
    collected: number;
    pending: number;
    collectionRate: number;
    overdueCount: number;
  };
  recentAnnouncements: Array<{
    id: string;
    title: string;
    type: string;
    createdAt: string;
    isPinned: boolean;
  }>;
}

export default function SchoolDashboard() {
  const { data: stats, isLoading, error, refetch } = useQuery<DashboardStats>({
    queryKey: ["/api/school/dashboard/stats"],
  });

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
      minimumFractionDigits: 0,
    }).format(amount / 100);
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  };

  const getTimeAgo = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffHours < 1) return "Just now";
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? "s" : ""} ago`;
    if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? "s" : ""} ago`;
    return formatDate(dateStr);
  };

  const getDaysRemaining = () => {
    if (!stats?.currentTerm?.endDate) return null;
    const end = new Date(stats.currentTerm.endDate);
    const now = new Date();
    const diffTime = end.getTime() - now.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  const getAnnouncementBadgeVariant = (type: string) => {
    switch (type) {
      case "urgent":
        return "destructive";
      case "event":
        return "default";
      case "academic":
        return "secondary";
      default:
        return "outline";
    }
  };

  const statCards = [
    {
      title: "Total Students",
      value: stats?.totalStudents || 0,
      icon: GraduationCap,
      color: "text-blue-600 dark:text-blue-400",
      bgColor: "bg-blue-100 dark:bg-blue-900/30",
      link: "/school/students",
    },
    {
      title: "Total Teachers",
      value: stats?.totalTeachers || 0,
      icon: Users,
      color: "text-green-600 dark:text-green-400",
      bgColor: "bg-green-100 dark:bg-green-900/30",
      link: "/school/teachers",
    },
    {
      title: "Classes",
      value: stats?.totalClasses || 0,
      icon: BookOpen,
      color: "text-purple-600 dark:text-purple-400",
      bgColor: "bg-purple-100 dark:bg-purple-900/30",
      link: "/school/classes",
    },
    {
      title: "Subjects",
      value: stats?.totalSubjects || 0,
      icon: FileText,
      color: "text-orange-600 dark:text-orange-400",
      bgColor: "bg-orange-100 dark:bg-orange-900/30",
      link: "/school/subjects",
    },
  ];

  const quickActions = [
    { label: "Mark Attendance", icon: UserCheck, link: "/school/attendance", color: "bg-blue-600 dark:bg-blue-700" },
    { label: "Enter Grades", icon: TrendingUp, link: "/school/grades", color: "bg-green-600 dark:bg-green-700" },
    { label: "Record Payment", icon: DollarSign, link: "/school/fees", color: "bg-purple-600 dark:bg-purple-700" },
    { label: "New Announcement", icon: Megaphone, link: "/school/announcements", color: "bg-orange-600 dark:bg-orange-700" },
  ];

  if (isLoading) {
    return (
      <div className="p-6 space-y-6">
        <DashboardSkeleton />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 space-y-6">
        <ErrorState
          title="Failed to load dashboard"
          message="We couldn't fetch your dashboard data. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  const daysRemaining = getDaysRemaining();

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">School Dashboard</h1>
          <p className="text-muted-foreground">Welcome back! Here's an overview of your school.</p>
        </div>
        {stats?.currentTerm && (
          <div className="flex items-center gap-3">
            <Badge variant="outline" className="flex items-center gap-1 px-3 py-1.5">
              <CalendarDays className="h-3.5 w-3.5" />
              <span>{stats.currentTerm.name} {stats.currentTerm.sessionYear}</span>
            </Badge>
            {daysRemaining !== null && (
              <Badge variant={daysRemaining < 14 ? "destructive" : "secondary"} className="flex items-center gap-1 px-3 py-1.5">
                <Timer className="h-3.5 w-3.5" />
                <span>{daysRemaining} days remaining</span>
              </Badge>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {statCards.map((stat) => (
          <Link key={stat.title} href={stat.link}>
            <Card className="hover-elevate cursor-pointer h-full" data-testid={`card-stat-${stat.title.toLowerCase().replace(/\s+/g, '-')}`}>
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">{stat.title}</p>
                    <p className="text-3xl font-bold mt-1">{stat.value}</p>
                  </div>
                  <div className={`p-3 rounded-full ${stat.bgColor}`}>
                    <stat.icon className={`h-6 w-6 ${stat.color}`} />
                  </div>
                </div>
              </CardContent>
            </Card>
          </Link>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-lg">
                <TrendingUp className="h-5 w-5" />
                Quick Actions
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {quickActions.map((action) => (
                  <Link key={action.label} href={action.link}>
                    <Button
                      variant="outline"
                      className="w-full h-20 flex flex-col items-center justify-center gap-2"
                      data-testid={`button-${action.label.toLowerCase().replace(/\s+/g, '-')}`}
                    >
                      <div className={`p-2 rounded-full ${action.color}`}>
                        <action.icon className="h-4 w-4 text-white" />
                      </div>
                      <span className="text-xs font-medium">{action.label}</span>
                    </Button>
                  </Link>
                ))}
              </div>
            </CardContent>
          </Card>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <UserCheck className="h-5 w-5" />
                  Today's Attendance
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-3xl font-bold">{stats?.attendance?.rate || 0}%</span>
                  <Badge variant={stats?.attendance?.rate && stats.attendance.rate >= 80 ? "default" : "destructive"}>
                    {stats?.attendance?.rate && stats.attendance.rate >= 80 ? "Good" : "Needs Attention"}
                  </Badge>
                </div>
                <Progress value={stats?.attendance?.rate || 0} className="h-2" />
                <div className="grid grid-cols-3 gap-2 pt-2">
                  <div className="text-center p-2 bg-green-50 dark:bg-green-900/20 rounded-lg">
                    <CheckCircle2 className="h-4 w-4 mx-auto text-green-600 dark:text-green-400 mb-1" />
                    <p className="text-lg font-semibold">{stats?.attendance?.today?.present || 0}</p>
                    <p className="text-xs text-muted-foreground">Present</p>
                  </div>
                  <div className="text-center p-2 bg-red-50 dark:bg-red-900/20 rounded-lg">
                    <XCircle className="h-4 w-4 mx-auto text-red-600 dark:text-red-400 mb-1" />
                    <p className="text-lg font-semibold">{stats?.attendance?.today?.absent || 0}</p>
                    <p className="text-xs text-muted-foreground">Absent</p>
                  </div>
                  <div className="text-center p-2 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg">
                    <Clock className="h-4 w-4 mx-auto text-yellow-600 dark:text-yellow-400 mb-1" />
                    <p className="text-lg font-semibold">{stats?.attendance?.today?.late || 0}</p>
                    <p className="text-xs text-muted-foreground">Late</p>
                  </div>
                </div>
                <Link href="/school/attendance">
                  <Button variant="ghost" size="sm" className="w-full mt-2" data-testid="button-view-attendance">
                    View Attendance <ArrowRight className="h-4 w-4 ml-1" />
                  </Button>
                </Link>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <DollarSign className="h-5 w-5" />
                  Fee Collection
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-3xl font-bold">{stats?.fees?.collectionRate || 0}%</span>
                  <Badge variant={stats?.fees?.collectionRate && stats.fees.collectionRate >= 70 ? "default" : "secondary"}>
                    {formatCurrency(stats?.fees?.collected || 0)}
                  </Badge>
                </div>
                <Progress value={stats?.fees?.collectionRate || 0} className="h-2" />
                <div className="grid grid-cols-2 gap-3 pt-2">
                  <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
                    <p className="text-xs text-muted-foreground mb-1">Collected</p>
                    <p className="text-sm font-semibold text-green-700 dark:text-green-400">
                      {formatCurrency(stats?.fees?.collected || 0)}
                    </p>
                  </div>
                  <div className="p-3 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg">
                    <p className="text-xs text-muted-foreground mb-1">Pending</p>
                    <p className="text-sm font-semibold text-yellow-700 dark:text-yellow-400">
                      {formatCurrency(stats?.fees?.pending || 0)}
                    </p>
                  </div>
                </div>
                {stats?.fees?.overdueCount && stats.fees.overdueCount > 0 ? (
                  <div className="flex items-center gap-2 p-2 bg-red-50 dark:bg-red-900/20 rounded-lg">
                    <AlertTriangle className="h-4 w-4 text-red-600 dark:text-red-400" />
                    <span className="text-sm text-red-700 dark:text-red-400">
                      {stats.fees.overdueCount} overdue payment{stats.fees.overdueCount > 1 ? "s" : ""}
                    </span>
                  </div>
                ) : null}
                <Link href="/school/fees">
                  <Button variant="ghost" size="sm" className="w-full mt-2" data-testid="button-view-fees">
                    Manage Fees <ArrowRight className="h-4 w-4 ml-1" />
                  </Button>
                </Link>
              </CardContent>
            </Card>
          </div>
        </div>

        <div className="space-y-6">
          <Card>
            <CardHeader className="pb-3 flex flex-row items-center justify-between gap-2">
              <CardTitle className="flex items-center gap-2 text-lg">
                <Bell className="h-5 w-5" />
                Recent Announcements
              </CardTitle>
              <Link href="/school/announcements">
                <Button variant="ghost" size="sm" data-testid="button-view-all-announcements">
                  <PlusCircle className="h-4 w-4" />
                </Button>
              </Link>
            </CardHeader>
            <CardContent>
              {stats?.recentAnnouncements && stats.recentAnnouncements.length > 0 ? (
                <div className="space-y-3">
                  {stats.recentAnnouncements.map((announcement) => (
                    <div key={announcement.id} className="p-3 border rounded-lg">
                      <div className="flex items-start justify-between gap-2 mb-1">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          {announcement.isPinned && (
                            <Pin className="h-3 w-3 text-primary flex-shrink-0" />
                          )}
                          <h4 className="font-medium text-sm truncate">{announcement.title}</h4>
                        </div>
                        <Badge variant={getAnnouncementBadgeVariant(announcement.type)} className="text-xs flex-shrink-0">
                          {announcement.type}
                        </Badge>
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {getTimeAgo(announcement.createdAt)}
                      </p>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-6 text-muted-foreground">
                  <Megaphone className="h-10 w-10 mx-auto mb-2 opacity-20" />
                  <p className="text-sm">No announcements yet</p>
                  <Link href="/school/announcements">
                    <Button variant="ghost" size="sm" className="mt-2">
                      Create First Announcement
                    </Button>
                  </Link>
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-lg">
                <Calendar className="h-5 w-5" />
                Term Overview
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {stats?.currentTerm ? (
                <>
                  <div className="p-3 bg-muted/50 rounded-lg">
                    <p className="text-xs text-muted-foreground mb-1">Current Term</p>
                    <p className="font-medium">{stats.currentTerm.name}</p>
                    <p className="text-sm text-muted-foreground">{stats.currentTerm.sessionYear}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="p-3 border rounded-lg">
                      <p className="text-xs text-muted-foreground mb-1">Start Date</p>
                      <p className="text-sm font-medium">{formatDate(stats.currentTerm.startDate)}</p>
                    </div>
                    <div className="p-3 border rounded-lg">
                      <p className="text-xs text-muted-foreground mb-1">End Date</p>
                      <p className="text-sm font-medium">{formatDate(stats.currentTerm.endDate)}</p>
                    </div>
                  </div>
                  <Link href="/school/terms">
                    <Button variant="ghost" size="sm" className="w-full" data-testid="button-manage-terms">
                      Manage Terms <ArrowRight className="h-4 w-4 ml-1" />
                    </Button>
                  </Link>
                </>
              ) : (
                <div className="text-center py-6 text-muted-foreground">
                  <Calendar className="h-10 w-10 mx-auto mb-2 opacity-20" />
                  <p className="text-sm">No current term set</p>
                  <Link href="/school/terms">
                    <Button variant="ghost" size="sm" className="mt-2">
                      Set Up Term
                    </Button>
                  </Link>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

