import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Users, Edit, Trash2, Search, UserPlus, Link, Unlink, GraduationCap } from "lucide-react";
import type { SchoolUser, ParentStudentLink } from "@shared/schema";

interface ParentWithStudents extends SchoolUser {
  linkedStudents?: Array<SchoolUser & { relationship: string }>;
}

export default function ParentsPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isLinkDialogOpen, setIsLinkDialogOpen] = useState(false);
  const [editingParent, setEditingParent] = useState<SchoolUser | null>(null);
  const [linkingParent, setLinkingParent] = useState<SchoolUser | null>(null);
  const [searchQuery, setSearchQuery] = useState("");

  const [formData, setFormData] = useState({
    email: "",
    password: "",
    firstName: "",
    lastName: "",
    middleName: "",
    gender: "",
    phone: "",
    address: "",
    occupation: "",
    relationship: "",
  });

  const [linkFormData, setLinkFormData] = useState({
    studentId: "",
    relationship: "parent",
  });

  const { data: parents, isLoading, error, refetch } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "parent" }],
  });

  const { data: students } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "student" }],
  });

  const { data: parentsWithLinks } = useQuery<ParentWithStudents[]>({
    queryKey: ["/api/school/parents-with-students"],
    enabled: !!parents && parents.length > 0,
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/users", {
        ...data,
        role: "parent",
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/school/parents-with-students"] });
      toast({ title: "Parent added successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to add parent", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      return apiRequest("PATCH", `/api/school/users/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/school/parents-with-students"] });
      toast({ title: "Parent updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update parent", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/users/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      queryClient.invalidateQueries({ queryKey: ["/api/school/parents-with-students"] });
      toast({ title: "Parent removed successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to remove parent", description: error.message, variant: "destructive" });
    },
  });

  const linkStudentMutation = useMutation({
    mutationFn: async (data: { parentId: string; studentId: string; relationship: string }) => {
      return apiRequest("POST", "/api/school/parent-student-link", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/parents-with-students"] });
      toast({ title: "Student linked successfully" });
      setLinkFormData({ studentId: "", relationship: "parent" });
      setIsLinkDialogOpen(false);
      setLinkingParent(null);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to link student", description: error.message, variant: "destructive" });
    },
  });

  const unlinkStudentMutation = useMutation({
    mutationFn: async (data: { parentId: string; studentId: string }) => {
      return apiRequest("DELETE", `/api/school/parent-student-link/${data.parentId}/${data.studentId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/parents-with-students"] });
      toast({ title: "Student unlinked successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to unlink student", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      middleName: "",
      gender: "",
      phone: "",
      address: "",
      occupation: "",
      relationship: "",
    });
    setEditingParent(null);
  };

  const handleEdit = (parent: SchoolUser) => {
    setEditingParent(parent);
    setFormData({
      email: parent.email,
      password: "",
      firstName: parent.firstName,
      lastName: parent.lastName,
      middleName: parent.middleName || "",
      gender: parent.gender || "",
      phone: parent.phone || "",
      address: parent.address || "",
      occupation: parent.occupation || "",
      relationship: parent.relationship || "",
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingParent) {
      const { password, ...updateData } = formData;
      updateMutation.mutate({ id: editingParent.id, data: updateData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleLinkStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (linkingParent && linkFormData.studentId) {
      linkStudentMutation.mutate({
        parentId: linkingParent.id,
        studentId: linkFormData.studentId,
        relationship: linkFormData.relationship,
      });
    }
  };

  const openLinkDialog = (parent: SchoolUser) => {
    setLinkingParent(parent);
    setLinkFormData({ studentId: "", relationship: "parent" });
    setIsLinkDialogOpen(true);
  };

  const getLinkedStudents = (parentId: string) => {
    const parent = parentsWithLinks?.find(p => p.id === parentId);
    return parent?.linkedStudents || [];
  };

  const getAvailableStudents = (parentId: string) => {
    const linkedStudentIds = getLinkedStudents(parentId).map(s => s.id);
    return students?.filter(s => !linkedStudentIds.includes(s.id)) || [];
  };

  const filteredParents = parents?.filter((p) =>
    p.firstName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.lastName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.phone?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Parents / Guardians"
          description="Manage parent accounts and link them to students"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Users", href: "/school/parents" },
            { label: "Parents" }
          ]}
        />
        <TableSkeleton rows={6} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Parents / Guardians"
          description="Manage parent accounts and link them to students"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Users", href: "/school/parents" },
            { label: "Parents" }
          ]}
        />
        <ErrorState 
          message="Failed to load parents. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Parents / Guardians"
        description="Manage parent accounts and link them to students"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Users", href: "/school/parents" },
          { label: "Parents" }
        ]}
        actions={
          <Button data-testid="button-add-parent" onClick={() => setIsDialogOpen(true)}>
            <UserPlus className="h-4 w-4 mr-2" />
            <span className="hidden sm:inline">Add Parent</span>
            <span className="sm:hidden">Add</span>
          </Button>
        }
      />

      <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingParent ? "Edit Parent" : "Add New Parent"}</DialogTitle>
              <DialogDescription>
                {editingParent ? "Update parent information" : "Create a new parent account"}
              </DialogDescription>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="firstName">First Name</Label>
                  <Input
                    id="firstName"
                    value={formData.firstName}
                    onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                    required
                    data-testid="input-parent-firstname"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="middleName">Middle Name</Label>
                  <Input
                    id="middleName"
                    value={formData.middleName}
                    onChange={(e) => setFormData({ ...formData, middleName: e.target.value })}
                    data-testid="input-parent-middlename"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="lastName">Last Name</Label>
                  <Input
                    id="lastName"
                    value={formData.lastName}
                    onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                    required
                    data-testid="input-parent-lastname"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    required
                    data-testid="input-parent-email"
                  />
                </div>
                {!editingParent && (
                  <div className="space-y-2">
                    <Label htmlFor="password">Password</Label>
                    <Input
                      id="password"
                      type="password"
                      value={formData.password}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      required={!editingParent}
                      data-testid="input-parent-password"
                    />
                  </div>
                )}
              </div>
              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label>Gender</Label>
                  <Select
                    value={formData.gender}
                    onValueChange={(value) => setFormData({ ...formData, gender: value })}
                  >
                    <SelectTrigger data-testid="select-parent-gender">
                      <SelectValue placeholder="Select gender" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="male">Male</SelectItem>
                      <SelectItem value="female">Female</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Relationship</Label>
                  <Select
                    value={formData.relationship}
                    onValueChange={(value) => setFormData({ ...formData, relationship: value })}
                  >
                    <SelectTrigger data-testid="select-parent-relationship">
                      <SelectValue placeholder="Select relationship" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="father">Father</SelectItem>
                      <SelectItem value="mother">Mother</SelectItem>
                      <SelectItem value="guardian">Guardian</SelectItem>
                      <SelectItem value="other">Other</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="occupation">Occupation</Label>
                  <Input
                    id="occupation"
                    value={formData.occupation}
                    onChange={(e) => setFormData({ ...formData, occupation: e.target.value })}
                    data-testid="input-parent-occupation"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="phone">Phone</Label>
                  <Input
                    id="phone"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    data-testid="input-parent-phone"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="address">Address</Label>
                  <Input
                    id="address"
                    value={formData.address}
                    onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                    data-testid="input-parent-address"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                  Cancel
                </Button>
                <Button type="submit" data-testid="button-save-parent">
                  {editingParent ? "Update" : "Add"} Parent
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>

      <Dialog open={isLinkDialogOpen} onOpenChange={(open) => { setIsLinkDialogOpen(open); if (!open) setLinkingParent(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Link Student to {linkingParent?.firstName} {linkingParent?.lastName}</DialogTitle>
            <DialogDescription>
              Select a student to link to this parent account
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleLinkStudent} className="space-y-4">
            <div className="space-y-2">
              <Label>Select Student</Label>
              <Select
                value={linkFormData.studentId}
                onValueChange={(value) => setLinkFormData({ ...linkFormData, studentId: value })}
              >
                <SelectTrigger data-testid="select-link-student">
                  <SelectValue placeholder="Select a student" />
                </SelectTrigger>
                <SelectContent>
                  {linkingParent && getAvailableStudents(linkingParent.id).map((student) => (
                    <SelectItem key={student.id} value={student.id}>
                      {student.firstName} {student.lastName} {student.admissionNumber ? `(${student.admissionNumber})` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Relationship</Label>
              <Select
                value={linkFormData.relationship}
                onValueChange={(value) => setLinkFormData({ ...linkFormData, relationship: value })}
              >
                <SelectTrigger data-testid="select-link-relationship">
                  <SelectValue placeholder="Select relationship" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="father">Father</SelectItem>
                  <SelectItem value="mother">Mother</SelectItem>
                  <SelectItem value="guardian">Guardian</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={() => setIsLinkDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={!linkFormData.studentId} data-testid="button-confirm-link">
                <Link className="h-4 w-4 mr-2" />
                Link Student
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <CardTitle className="flex items-center gap-2">
              <Users className="h-5 w-5" />
              All Parents ({parents?.length || 0})
            </CardTitle>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search parents..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 w-64"
                data-testid="input-search-parents"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {filteredParents && filteredParents.length > 0 ? (
            <Accordion type="single" collapsible className="space-y-2">
              {filteredParents.map((parent) => {
                const linkedStudents = getLinkedStudents(parent.id);
                return (
                  <AccordionItem key={parent.id} value={parent.id} className="border rounded-lg px-4" data-testid={`row-parent-${parent.id}`}>
                    <AccordionTrigger className="hover:no-underline">
                      <div className="flex items-center justify-between w-full pr-4">
                        <div className="flex items-center gap-4">
                          <div>
                            <span className="font-medium">
                              {parent.firstName} {parent.middleName ? `${parent.middleName} ` : ""}{parent.lastName}
                            </span>
                            <p className="text-sm text-muted-foreground">{parent.email}</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-4">
                          <Badge variant="outline" className="capitalize">
                            {parent.relationship || "Parent"}
                          </Badge>
                          <Badge variant={linkedStudents.length > 0 ? "default" : "secondary"}>
                            {linkedStudents.length} {linkedStudents.length === 1 ? "child" : "children"}
                          </Badge>
                          <Badge variant={parent.isActive ? "default" : "secondary"}>
                            {parent.isActive ? "Active" : "Inactive"}
                          </Badge>
                        </div>
                      </div>
                    </AccordionTrigger>
                    <AccordionContent className="pt-4 pb-2">
                      <div className="space-y-4">
                        <div className="grid grid-cols-4 gap-4 text-sm">
                          <div>
                            <span className="text-muted-foreground">Phone:</span>
                            <p className="font-medium">{parent.phone || "-"}</p>
                          </div>
                          <div>
                            <span className="text-muted-foreground">Occupation:</span>
                            <p className="font-medium">{parent.occupation || "-"}</p>
                          </div>
                          <div>
                            <span className="text-muted-foreground">Address:</span>
                            <p className="font-medium">{parent.address || "-"}</p>
                          </div>
                          <div>
                            <span className="text-muted-foreground">Gender:</span>
                            <p className="font-medium capitalize">{parent.gender || "-"}</p>
                          </div>
                        </div>

                        <div className="border-t pt-4">
                          <div className="flex items-center justify-between mb-3">
                            <h4 className="font-medium flex items-center gap-2">
                              <GraduationCap className="h-4 w-4" />
                              Linked Students
                            </h4>
                            <Button size="sm" variant="outline" onClick={() => openLinkDialog(parent)} data-testid={`button-link-student-${parent.id}`}>
                              <Link className="h-4 w-4 mr-2" />
                              Link Student
                            </Button>
                          </div>
                          {linkedStudents.length > 0 ? (
                            <Table>
                              <TableHeader>
                                <TableRow>
                                  <TableHead>Name</TableHead>
                                  <TableHead>Admission No.</TableHead>
                                  <TableHead>Relationship</TableHead>
                                  <TableHead className="text-right">Action</TableHead>
                                </TableRow>
                              </TableHeader>
                              <TableBody>
                                {linkedStudents.map((student) => (
                                  <TableRow key={student.id}>
                                    <TableCell>{student.firstName} {student.lastName}</TableCell>
                                    <TableCell>{student.admissionNumber || "-"}</TableCell>
                                    <TableCell className="capitalize">{student.relationship}</TableCell>
                                    <TableCell className="text-right">
                                      <Button
                                        size="sm"
                                        variant="ghost"
                                        onClick={() => unlinkStudentMutation.mutate({ parentId: parent.id, studentId: student.id })}
                                        data-testid={`button-unlink-${student.id}`}
                                      >
                                        <Unlink className="h-4 w-4 text-destructive" />
                                      </Button>
                                    </TableCell>
                                  </TableRow>
                                ))}
                              </TableBody>
                            </Table>
                          ) : (
                            <p className="text-sm text-muted-foreground text-center py-4">
                              No students linked yet. Click "Link Student" to connect this parent to their children.
                            </p>
                          )}
                        </div>

                        <div className="flex justify-end gap-2 pt-2 border-t">
                          <Button variant="outline" size="sm" onClick={() => handleEdit(parent)} data-testid={`button-edit-parent-${parent.id}`}>
                            <Edit className="h-4 w-4 mr-2" />
                            Edit
                          </Button>
                          <Button variant="outline" size="sm" onClick={() => deleteMutation.mutate(parent.id)} data-testid={`button-delete-parent-${parent.id}`}>
                            <Trash2 className="h-4 w-4 mr-2 text-destructive" />
                            Delete
                          </Button>
                        </div>
                      </div>
                    </AccordionContent>
                  </AccordionItem>
                );
              })}
            </Accordion>
          ) : (
            <EmptyState
              icon={Users}
              title="No parents found"
              description="Add your first parent to get started."
              action={{
                label: "Add Parent",
                onClick: () => setIsDialogOpen(true)
              }}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/grades.tsx.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { TrendingUp, Save, Users, BookOpen, FileText, Calculator } from "lucide-react";
import type { SchoolClass, SchoolSubject, SchoolUser, AssessmentType, StudentGrade, AcademicTerm } from "@shared/schema";

interface GradeEntry {
  studentId: string;
  score: number;
}

export default function GradesPage() {
  const { toast } = useToast();
  const [selectedTerm, setSelectedTerm] = useState<string>("");
  const [selectedClass, setSelectedClass] = useState<string>("");
  const [selectedSubject, setSelectedSubject] = useState<string>("");
  const [selectedAssessment, setSelectedAssessment] = useState<string>("");
  const [gradesData, setGradesData] = useState<Record<string, number>>({});

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: assessmentTypes } = useQuery<AssessmentType[]>({
    queryKey: ["/api/school/assessment-types"],
  });

  const { data: students, isLoading: studentsLoading } = useQuery<SchoolUser[]>({
    queryKey: [`/api/school/classes/${selectedClass}/students`],
    enabled: !!selectedClass,
  });

  const { data: existingGrades, refetch: refetchGrades } = useQuery<StudentGrade[]>({
    queryKey: ["/api/school/grades", { classId: selectedClass, subjectId: selectedSubject, termId: selectedTerm }],
    enabled: !!selectedClass && !!selectedSubject && !!selectedTerm,
  });

  useEffect(() => {
    if (terms && terms.length > 0 && !selectedTerm) {
      const currentTerm = terms.find(t => t.isCurrent);
      if (currentTerm) {
        setSelectedTerm(currentTerm.id);
      }
    }
  }, [terms, selectedTerm]);

  useEffect(() => {
    if (existingGrades && existingGrades.length > 0 && selectedAssessment) {
      const initialGrades: Record<string, number> = {};
      existingGrades
        .filter(g => g.assessmentTypeId === selectedAssessment)
        .forEach(g => {
          initialGrades[g.studentId] = g.score;
        });
      setGradesData(initialGrades);
    } else {
      setGradesData({});
    }
  }, [existingGrades, selectedAssessment]);

  const saveMutation = useMutation({
    mutationFn: async (entries: GradeEntry[]) => {
      return apiRequest("POST", "/api/school/grades/bulk", {
        classId: selectedClass,
        subjectId: selectedSubject,
        termId: selectedTerm,
        assessmentTypeId: selectedAssessment,
        entries,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/grades"] });
      toast({ title: "Grades saved successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to save grades", description: error.message, variant: "destructive" });
    },
  });

  const calculateResultsMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("POST", "/api/school/results/calculate", {
        classId: selectedClass,
        termId: selectedTerm,
      });
    },
    onSuccess: () => {
      toast({ title: "Term results calculated successfully", description: "Student positions and averages have been updated." });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to calculate results", description: error.message, variant: "destructive" });
    },
  });

  const handleScoreChange = (studentId: string, score: string) => {
    const numScore = parseInt(score) || 0;
    setGradesData((prev) => ({ ...prev, [studentId]: numScore }));
  };

  const handleSave = () => {
    const entries = Object.entries(gradesData)
      .filter(([_, score]) => score > 0)
      .map(([studentId, score]) => ({
        studentId,
        score,
      }));
    if (entries.length === 0) {
      toast({ title: "No grades to save", variant: "destructive" });
      return;
    }
    saveMutation.mutate(entries);
  };

  const handleCalculateResults = () => {
    if (!selectedClass || !selectedTerm) {
      toast({ title: "Please select a class and term", variant: "destructive" });
      return;
    }
    calculateResultsMutation.mutate();
  };

  const selectedAssessmentType = assessmentTypes?.find((a) => a.id === selectedAssessment);
  const selectedTermData = terms?.find(t => t.id === selectedTerm);

  const getGradeColor = (score: number, maxScore: number) => {
    const percentage = (score / maxScore) * 100;
    if (percentage >= 70) return "text-green-600 dark:text-green-400";
    if (percentage >= 50) return "text-yellow-600 dark:text-yellow-400";
    return "text-red-600 dark:text-red-400";
  };

  const getGradeLetter = (score: number, maxScore: number) => {
    const percentage = (score / maxScore) * 100;
    if (percentage >= 70) return "A";
    if (percentage >= 60) return "B";
    if (percentage >= 50) return "C";
    if (percentage >= 40) return "D";
    return "F";
  };

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Grades"
        description="Enter and manage student grades"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Academics", href: "/school/grades" },
          { label: "Grades" }
        ]}
        actions={
          selectedClass && selectedTerm ? (
            <Button 
              onClick={handleCalculateResults} 
              disabled={calculateResultsMutation.isPending}
              variant="outline"
              data-testid="button-calculate-results"
            >
              <Calculator className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">Calculate Term Results</span>
              <span className="sm:hidden">Calculate</span>
            </Button>
          ) : undefined
        }
      />

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Select Term, Class, Subject & Assessment
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Term</label>
              <Select value={selectedTerm} onValueChange={setSelectedTerm}>
                <SelectTrigger data-testid="select-grade-term">
                  <SelectValue placeholder="Select a term" />
                </SelectTrigger>
                <SelectContent>
                  {terms?.map((term) => (
                    <SelectItem key={term.id} value={term.id}>
                      {term.name} {term.isCurrent && "(Current)"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Class</label>
              <Select value={selectedClass} onValueChange={setSelectedClass}>
                <SelectTrigger data-testid="select-grade-class">
                  <SelectValue placeholder="Select a class" />
                </SelectTrigger>
                <SelectContent>
                  {classes?.map((classItem) => (
                    <SelectItem key={classItem.id} value={classItem.id}>
                      {classItem.name} {classItem.section ? `(${classItem.section})` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Subject</label>
              <Select value={selectedSubject} onValueChange={setSelectedSubject}>
                <SelectTrigger data-testid="select-grade-subject">
                  <SelectValue placeholder="Select a subject" />
                </SelectTrigger>
                <SelectContent>
                  {subjects?.map((subject) => (
                    <SelectItem key={subject.id} value={subject.id}>
                      {subject.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Assessment Type</label>
              <Select value={selectedAssessment} onValueChange={setSelectedAssessment}>
                <SelectTrigger data-testid="select-grade-assessment">
                  <SelectValue placeholder="Select assessment" />
                </SelectTrigger>
                <SelectContent>
                  {assessmentTypes?.map((type) => (
                    <SelectItem key={type.id} value={type.id}>
                      {type.name} ({type.weight}% - Max: {type.maxScore})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {selectedTerm && selectedClass && selectedSubject && selectedAssessment && (
        <Card>
          <CardHeader className="flex flex-row items-center justify-between gap-2">
            <div>
              <CardTitle className="flex items-center gap-2">
                <TrendingUp className="h-5 w-5" />
                Enter Grades
              </CardTitle>
              <div className="text-sm text-muted-foreground mt-1 space-y-1">
                {selectedTermData && (
                  <p>Term: {selectedTermData.name}</p>
                )}
                {selectedAssessmentType && (
                  <p>Max Score: {selectedAssessmentType.maxScore} | Weight: {selectedAssessmentType.weight}%</p>
                )}
              </div>
            </div>
            <Button onClick={handleSave} disabled={saveMutation.isPending} data-testid="button-save-grades">
              <Save className="h-4 w-4 mr-2" />
              Save Grades
            </Button>
          </CardHeader>
          <CardContent>
            {studentsLoading ? (
              <div className="space-y-2">
                {[1, 2, 3, 4, 5].map((i) => (
                  <Skeleton key={i} className="h-12" />
                ))}
              </div>
            ) : students && students.length > 0 ? (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Student Name</TableHead>
                    <TableHead>Admission No.</TableHead>
                    <TableHead>Score</TableHead>
                    <TableHead>Grade</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {students.map((student) => {
                    const score = gradesData[student.id] || 0;
                    const maxScore = selectedAssessmentType?.maxScore || 100;
                    return (
                      <TableRow key={student.id} data-testid={`row-grade-${student.id}`}>
                        <TableCell className="font-medium">
                          {student.firstName} {student.lastName}
                        </TableCell>
                        <TableCell>{student.admissionNumber || "-"}</TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <Input
                              type="number"
                              min="0"
                              max={maxScore}
                              value={gradesData[student.id] ?? ""}
                              onChange={(e) => handleScoreChange(student.id, e.target.value)}
                              className="w-20"
                              placeholder="0"
                              data-testid={`input-score-${student.id}`}
                            />
                            <span className="text-sm text-muted-foreground">/ {maxScore}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          {score > 0 && (
                            <span className={`font-bold ${getGradeColor(score, maxScore)}`}>
                              {getGradeLetter(score, maxScore)}
                            </span>
                          )}
                        </TableCell>
                        <TableCell>
                          {score > 0 ? (
                            <Badge variant="outline" className={getGradeColor(score, maxScore)}>
                              {Math.round((score / maxScore) * 100)}%
                            </Badge>
                          ) : (
                            <Badge variant="secondary">Not graded</Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            ) : (
              <div className="text-center py-12">
                <Users className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                <h3 className="text-lg font-medium">No students in this class</h3>
                <p className="text-muted-foreground">Add students to this class to enter grades.</p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {(!selectedTerm || !selectedClass || !selectedSubject || !selectedAssessment) && (
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <BookOpen className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">Select Term, Class, Subject & Assessment</h3>
              <p className="text-muted-foreground">Choose all filters above to start entering grades.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/pages/school/students.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { GraduationCap, Edit, Trash2, Search, UserPlus } from "lucide-react";
import type { SchoolUser, SchoolClass } from "@shared/schema";

export default function StudentsPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<SchoolUser | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterClass, setFilterClass] = useState<string>("all");

  const [formData, setFormData] = useState({
    email: "",
    password: "",
    firstName: "",
    lastName: "",
    middleName: "",
    gender: "",
    dateOfBirth: "",
    phone: "",
    address: "",
    admissionNumber: "",
    classId: "",
  });

  const { data: students, isLoading, error, refetch } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "student" }],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/users", {
        ...data,
        role: "student",
        dateOfBirth: data.dateOfBirth ? new Date(data.dateOfBirth).toISOString() : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Student added successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to add student", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      return apiRequest("PATCH", `/api/school/users/${id}`, {
        ...data,
        dateOfBirth: data.dateOfBirth ? new Date(data.dateOfBirth).toISOString() : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Student updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update student", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/users/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Student removed successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to remove student", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      middleName: "",
      gender: "",
      dateOfBirth: "",
      phone: "",
      address: "",
      admissionNumber: "",
      classId: "",
    });
    setEditingStudent(null);
  };

  const handleEdit = (student: SchoolUser) => {
    setEditingStudent(student);
    setFormData({
      email: student.email,
      password: "",
      firstName: student.firstName,
      lastName: student.lastName,
      middleName: student.middleName || "",
      gender: student.gender || "",
      dateOfBirth: student.dateOfBirth
        ? new Date(student.dateOfBirth).toISOString().split("T")[0]
        : "",
      phone: student.phone || "",
      address: student.address || "",
      admissionNumber: student.admissionNumber || "",
      classId: student.classId || "",
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      const { password, ...updateData } = formData;
      updateMutation.mutate({ id: editingStudent.id, data: updateData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const getClassName = (classId: string | null) => {
    if (!classId) return "Not Assigned";
    const classItem = classes?.find((c) => c.id === classId);
    return classItem ? `${classItem.name} ${classItem.section || ""}`.trim() : "Unknown";
  };

  const filteredStudents = students?.filter((s) => {
    const matchesSearch =
      s.firstName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.lastName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.admissionNumber?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.email.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesClass = filterClass === "all" || s.classId === filterClass;
    return matchesSearch && matchesClass;
  });

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Students"
          description="Manage student registrations and profiles"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "People", href: "/school/students" },
            { label: "Students" }
          ]}
        />
        <TableSkeleton rows={5} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Students"
          description="Manage student registrations and profiles"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "People", href: "/school/students" },
            { label: "Students" }
          ]}
        />
        <ErrorState 
          message="Failed to load students. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Students"
        description="Manage student registrations and profiles"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "People", href: "/school/students" },
          { label: "Students" }
        ]}
        actions={
          <Button onClick={() => setIsDialogOpen(true)} data-testid="button-add-student">
            <UserPlus className="h-4 w-4 mr-2" />
            <span className="hidden sm:inline">Add Student</span>
            <span className="sm:hidden">Add</span>
          </Button>
        }
      />

      <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingStudent ? "Edit Student" : "Add New Student"}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="firstName">First Name</Label>
                <Input
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                  required
                  data-testid="input-student-firstname"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="middleName">Middle Name</Label>
                <Input
                  id="middleName"
                  value={formData.middleName}
                  onChange={(e) => setFormData({ ...formData, middleName: e.target.value })}
                  data-testid="input-student-middlename"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="lastName">Last Name</Label>
                <Input
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                  required
                  data-testid="input-student-lastname"
                />
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                  data-testid="input-student-email"
                />
              </div>
              {!editingStudent && (
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <Input
                    id="password"
                    type="password"
                    value={formData.password}
                    onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                    required={!editingStudent}
                    data-testid="input-student-password"
                  />
                </div>
              )}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="admissionNumber">Admission Number</Label>
                <Input
                  id="admissionNumber"
                  value={formData.admissionNumber}
                  onChange={(e) => setFormData({ ...formData, admissionNumber: e.target.value })}
                  data-testid="input-student-admission"
                />
              </div>
              <div className="space-y-2">
                <Label>Class</Label>
                <Select
                  value={formData.classId}
                  onValueChange={(value) => setFormData({ ...formData, classId: value })}
                >
                  <SelectTrigger data-testid="select-student-class">
                    <SelectValue placeholder="Select class" />
                  </SelectTrigger>
                  <SelectContent>
                    {classes?.map((classItem) => (
                      <SelectItem key={classItem.id} value={classItem.id}>
                        {classItem.name} {classItem.section || ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Gender</Label>
                <Select
                  value={formData.gender}
                  onValueChange={(value) => setFormData({ ...formData, gender: value })}
                >
                  <SelectTrigger data-testid="select-student-gender">
                    <SelectValue placeholder="Select gender" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="male">Male</SelectItem>
                    <SelectItem value="female">Female</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="dateOfBirth">Date of Birth</Label>
                <Input
                  id="dateOfBirth"
                  type="date"
                  value={formData.dateOfBirth}
                  onChange={(e) => setFormData({ ...formData, dateOfBirth: e.target.value })}
                  data-testid="input-student-dob"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="phone">Phone</Label>
                <Input
                  id="phone"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  data-testid="input-student-phone"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="address">Address</Label>
              <Input
                id="address"
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                data-testid="input-student-address"
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                Cancel
              </Button>
              <Button type="submit" data-testid="button-save-student">
                {editingStudent ? "Update" : "Add"} Student
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <CardTitle className="flex items-center gap-2">
              <GraduationCap className="h-5 w-5" />
              All Students ({students?.length || 0})
            </CardTitle>
            <div className="flex items-center gap-4">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search students..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9 w-64"
                  data-testid="input-search-students"
                />
              </div>
              <Select value={filterClass} onValueChange={setFilterClass}>
                <SelectTrigger className="w-40" data-testid="select-filter-class">
                  <SelectValue placeholder="Filter by class" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Classes</SelectItem>
                  {classes?.map((classItem) => (
                    <SelectItem key={classItem.id} value={classItem.id}>
                      {classItem.name} {classItem.section || ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {filteredStudents && filteredStudents.length > 0 ? (
            <ScrollArea className="w-full">
              <div className="min-w-[700px]">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead className="hidden sm:table-cell">Admission No.</TableHead>
                      <TableHead className="hidden md:table-cell">Email</TableHead>
                      <TableHead>Class</TableHead>
                      <TableHead className="hidden lg:table-cell">Gender</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredStudents.map((student) => (
                      <TableRow key={student.id} data-testid={`row-student-${student.id}`}>
                        <TableCell className="font-medium">
                          <div>
                            {student.firstName} {student.middleName ? `${student.middleName} ` : ""}{student.lastName}
                          </div>
                          <div className="text-xs text-muted-foreground md:hidden">{student.email}</div>
                        </TableCell>
                        <TableCell className="hidden sm:table-cell">{student.admissionNumber || "-"}</TableCell>
                        <TableCell className="hidden md:table-cell">{student.email}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{getClassName(student.classId)}</Badge>
                        </TableCell>
                        <TableCell className="hidden lg:table-cell capitalize">{student.gender || "-"}</TableCell>
                        <TableCell>
                          <Badge variant={student.isActive ? "default" : "secondary"}>
                            {student.isActive ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button variant="ghost" size="icon" onClick={() => handleEdit(student)} data-testid={`button-edit-student-${student.id}`}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(student.id)} data-testid={`button-delete-student-${student.id}`}>
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
          ) : (
            <EmptyState
              icon={GraduationCap}
              title="No students found"
              description={searchQuery || filterClass !== "all" ? "No students match your search or filter. Try different criteria." : "Add your first student to start managing student records."}
              action={searchQuery || filterClass !== "all" ? undefined : { label: "Add Student", onClick: () => setIsDialogOpen(true) }}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

