import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Plus, DollarSign, CreditCard, Receipt, Search, Edit, Trash2, Bell, Send, AlertCircle, Loader2 } from "lucide-react";
import type { FeeType, FeePayment, SchoolUser } from "@shared/schema";

interface OverduePayment {
  student: SchoolUser;
  parent?: SchoolUser;
  balance: number;
  termId: string;
}

export default function FeesPage() {
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState("fee-types");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isPaymentDialogOpen, setIsPaymentDialogOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [editingFeeType, setEditingFeeType] = useState<FeeType | null>(null);

  const [feeFormData, setFeeFormData] = useState({
    name: "",
    code: "",
    amount: "",
    description: "",
    frequency: "termly",
    isRecurring: true,
  });

  const [paymentFormData, setPaymentFormData] = useState({
    studentId: "",
    feeTypeId: "",
    amount: "",
    paymentMethod: "cash",
    paymentReference: "",
    notes: "",
  });

  const { data: feeTypes, isLoading: feeTypesLoading } = useQuery<FeeType[]>({
    queryKey: ["/api/school/fee-types"],
  });

  const { data: payments, isLoading: paymentsLoading } = useQuery<FeePayment[]>({
    queryKey: ["/api/school/payments"],
  });

  const { data: students } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "student" }],
  });

  const { data: overduePayments, isLoading: overdueLoading, refetch: refetchOverdue } = useQuery<OverduePayment[]>({
    queryKey: ["/api/school/fees/overdue"],
  });

  const createFeeTypeMutation = useMutation({
    mutationFn: async (data: typeof feeFormData) => {
      return apiRequest("POST", "/api/school/fee-types", {
        ...data,
        amount: parseInt(data.amount) * 100, // Convert to kobo
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/fee-types"] });
      toast({ title: "Fee type created successfully" });
      resetFeeForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to create fee type", description: error.message, variant: "destructive" });
    },
  });

  const updateFeeTypeMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: typeof feeFormData }) => {
      return apiRequest("PATCH", `/api/school/fee-types/${id}`, {
        ...data,
        amount: parseInt(data.amount) * 100,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/fee-types"] });
      toast({ title: "Fee type updated successfully" });
      resetFeeForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update fee type", description: error.message, variant: "destructive" });
    },
  });

  const deleteFeeTypeMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/fee-types/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/fee-types"] });
      toast({ title: "Fee type deleted successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete fee type", description: error.message, variant: "destructive" });
    },
  });

  const recordPaymentMutation = useMutation({
    mutationFn: async (data: typeof paymentFormData) => {
      return apiRequest("POST", "/api/school/payments", {
        ...data,
        amount: parseInt(data.amount) * 100,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/payments"] });
      toast({ title: "Payment recorded successfully" });
      resetPaymentForm();
      setIsPaymentDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to record payment", description: error.message, variant: "destructive" });
    },
  });

  const sendReminderMutation = useMutation({
    mutationFn: async (data: { studentId: string; parentId: string; amount: number; termId: string }) => {
      return apiRequest("POST", "/api/school/fees/send-reminder", data);
    },
    onSuccess: () => {
      toast({ title: "Fee reminder sent successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to send reminder", description: error.message, variant: "destructive" });
    },
  });

  const sendBulkRemindersMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("POST", "/api/school/fees/send-bulk-reminders", {});
    },
    onSuccess: (data: any) => {
      toast({ 
        title: "Bulk reminders sent", 
        description: `${data.totalSent} reminders sent, ${data.totalFailed} failed` 
      });
      refetchOverdue();
    },
    onError: (error: Error) => {
      toast({ title: "Failed to send bulk reminders", description: error.message, variant: "destructive" });
    },
  });

  const resetFeeForm = () => {
    setFeeFormData({ name: "", code: "", amount: "", description: "", frequency: "termly", isRecurring: true });
    setEditingFeeType(null);
  };

  const resetPaymentForm = () => {
    setPaymentFormData({ studentId: "", feeTypeId: "", amount: "", paymentMethod: "cash", paymentReference: "", notes: "" });
  };

  const handleEditFeeType = (feeType: FeeType) => {
    setEditingFeeType(feeType);
    setFeeFormData({
      name: feeType.name,
      code: feeType.code || "",
      amount: (feeType.amount / 100).toString(),
      description: feeType.description || "",
      frequency: feeType.frequency || "termly",
      isRecurring: feeType.isRecurring,
    });
    setIsDialogOpen(true);
  };

  const handleFeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingFeeType) {
      updateFeeTypeMutation.mutate({ id: editingFeeType.id, data: feeFormData });
    } else {
      createFeeTypeMutation.mutate(feeFormData);
    }
  };

  const handlePaymentSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    recordPaymentMutation.mutate(paymentFormData);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
    }).format(amount / 100);
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "completed":
        return <Badge className="bg-green-600">Completed</Badge>;
      case "pending":
        return <Badge variant="outline">Pending</Badge>;
      case "failed":
        return <Badge variant="destructive">Failed</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">Fees & Payments</h1>
          <p className="text-muted-foreground">Manage school fees and record payments</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Total Fee Types</p>
                <p className="text-2xl font-bold">{feeTypes?.length || 0}</p>
              </div>
              <DollarSign className="h-8 w-8 text-blue-600" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Total Payments</p>
                <p className="text-2xl font-bold">{payments?.length || 0}</p>
              </div>
              <CreditCard className="h-8 w-8 text-green-600" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Revenue This Term</p>
                <p className="text-2xl font-bold">
                  {formatCurrency(
                    payments?.filter((p) => p.status === "completed").reduce((sum, p) => sum + p.amount, 0) || 0
                  )}
                </p>
              </div>
              <Receipt className="h-8 w-8 text-purple-600" />
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="fee-types" data-testid="tab-fee-types">Fee Types</TabsTrigger>
          <TabsTrigger value="payments" data-testid="tab-payments">Payments</TabsTrigger>
          <TabsTrigger value="reminders" data-testid="tab-reminders">Reminders</TabsTrigger>
        </TabsList>

        <TabsContent value="fee-types" className="mt-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2">
              <CardTitle>Fee Types</CardTitle>
              <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetFeeForm(); }}>
                <DialogTrigger asChild>
                  <Button data-testid="button-add-fee-type">
                    <Plus className="h-4 w-4 mr-2" />
                    Add Fee Type
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>{editingFeeType ? "Edit Fee Type" : "Add Fee Type"}</DialogTitle>
                  </DialogHeader>
                  <form onSubmit={handleFeeSubmit} className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label htmlFor="feeName">Fee Name</Label>
                        <Input
                          id="feeName"
                          value={feeFormData.name}
                          onChange={(e) => setFeeFormData({ ...feeFormData, name: e.target.value })}
                          placeholder="e.g., Tuition Fee"
                          required
                          data-testid="input-fee-name"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="feeCode">Code</Label>
                        <Input
                          id="feeCode"
                          value={feeFormData.code}
                          onChange={(e) => setFeeFormData({ ...feeFormData, code: e.target.value.toUpperCase() })}
                          placeholder="e.g., TUI"
                          data-testid="input-fee-code"
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label htmlFor="feeAmount">Amount (NGN)</Label>
                        <Input
                          id="feeAmount"
                          type="number"
                          value={feeFormData.amount}
                          onChange={(e) => setFeeFormData({ ...feeFormData, amount: e.target.value })}
                          placeholder="50000"
                          required
                          data-testid="input-fee-amount"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="feeFrequency">Frequency</Label>
                        <Select
                          value={feeFormData.frequency}
                          onValueChange={(value) => setFeeFormData({ ...feeFormData, frequency: value })}
                        >
                          <SelectTrigger data-testid="select-fee-frequency">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="termly">Termly</SelectItem>
                            <SelectItem value="yearly">Yearly</SelectItem>
                            <SelectItem value="one-time">One-time</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="feeDescription">Description</Label>
                      <Input
                        id="feeDescription"
                        value={feeFormData.description}
                        onChange={(e) => setFeeFormData({ ...feeFormData, description: e.target.value })}
                        placeholder="Optional description"
                        data-testid="input-fee-description"
                      />
                    </div>
                    <div className="flex justify-end gap-2">
                      <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetFeeForm(); }}>
                        Cancel
                      </Button>
                      <Button type="submit" data-testid="button-save-fee-type">
                        {editingFeeType ? "Update" : "Create"} Fee Type
                      </Button>
                    </div>
                  </form>
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              {feeTypesLoading ? (
                <Skeleton className="h-64" />
              ) : feeTypes && feeTypes.length > 0 ? (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Fee Name</TableHead>
                      <TableHead>Code</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>Frequency</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {feeTypes.map((fee) => (
                      <TableRow key={fee.id} data-testid={`row-fee-${fee.id}`}>
                        <TableCell className="font-medium">{fee.name}</TableCell>
                        <TableCell><Badge variant="outline">{fee.code || "-"}</Badge></TableCell>
                        <TableCell>{formatCurrency(fee.amount)}</TableCell>
                        <TableCell className="capitalize">{fee.frequency || "-"}</TableCell>
                        <TableCell>
                          <Badge variant={fee.isActive ? "default" : "secondary"}>
                            {fee.isActive ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-2">
                            <Button variant="ghost" size="icon" onClick={() => handleEditFeeType(fee)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => deleteFeeTypeMutation.mutate(fee.id)}>
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              ) : (
                <div className="text-center py-12">
                  <DollarSign className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="text-lg font-medium">No fee types found</h3>
                  <p className="text-muted-foreground">Create your first fee type to get started.</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="payments" className="mt-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2">
              <CardTitle>Payment Records</CardTitle>
              <Dialog open={isPaymentDialogOpen} onOpenChange={(open) => { setIsPaymentDialogOpen(open); if (!open) resetPaymentForm(); }}>
                <DialogTrigger asChild>
                  <Button data-testid="button-record-payment">
                    <Plus className="h-4 w-4 mr-2" />
                    Record Payment
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>Record Payment</DialogTitle>
                  </DialogHeader>
                  <form onSubmit={handlePaymentSubmit} className="space-y-4">
                    <div className="space-y-2">
                      <Label>Student</Label>
                      <Select
                        value={paymentFormData.studentId}
                        onValueChange={(value) => setPaymentFormData({ ...paymentFormData, studentId: value })}
                      >
                        <SelectTrigger data-testid="select-payment-student">
                          <SelectValue placeholder="Select student" />
                        </SelectTrigger>
                        <SelectContent>
                          {students?.map((student) => (
                            <SelectItem key={student.id} value={student.id}>
                              {student.firstName} {student.lastName} ({student.admissionNumber})
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label>Fee Type</Label>
                        <Select
                          value={paymentFormData.feeTypeId}
                          onValueChange={(value) => setPaymentFormData({ ...paymentFormData, feeTypeId: value })}
                        >
                          <SelectTrigger data-testid="select-payment-fee-type">
                            <SelectValue placeholder="Select fee type" />
                          </SelectTrigger>
                          <SelectContent>
                            {feeTypes?.map((fee) => (
                              <SelectItem key={fee.id} value={fee.id}>
                                {fee.name} ({formatCurrency(fee.amount)})
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-2">
                        <Label>Amount (NGN)</Label>
                        <Input
                          type="number"
                          value={paymentFormData.amount}
                          onChange={(e) => setPaymentFormData({ ...paymentFormData, amount: e.target.value })}
                          placeholder="50000"
                          required
                          data-testid="input-payment-amount"
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label>Payment Method</Label>
                        <Select
                          value={paymentFormData.paymentMethod}
                          onValueChange={(value) => setPaymentFormData({ ...paymentFormData, paymentMethod: value })}
                        >
                          <SelectTrigger data-testid="select-payment-method">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="cash">Cash</SelectItem>
                            <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
                            <SelectItem value="card">Card</SelectItem>
                            <SelectItem value="online">Online</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-2">
                        <Label>Reference</Label>
                        <Input
                          value={paymentFormData.paymentReference}
                          onChange={(e) => setPaymentFormData({ ...paymentFormData, paymentReference: e.target.value })}
                          placeholder="Transaction reference"
                          data-testid="input-payment-reference"
                        />
                      </div>
                    </div>
                    <div className="flex justify-end gap-2">
                      <Button type="button" variant="outline" onClick={() => { setIsPaymentDialogOpen(false); resetPaymentForm(); }}>
                        Cancel
                      </Button>
                      <Button type="submit" data-testid="button-save-payment">
                        Record Payment
                      </Button>
                    </div>
                  </form>
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              <div className="mb-4">
                <div className="relative max-w-sm">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder="Search payments..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-9"
                    data-testid="input-search-payments"
                  />
                </div>
              </div>
              {paymentsLoading ? (
                <Skeleton className="h-64" />
              ) : payments && payments.length > 0 ? (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Receipt #</TableHead>
                      <TableHead>Student</TableHead>
                      <TableHead>Fee Type</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>Method</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Date</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {payments.map((payment) => (
                      <TableRow key={payment.id} data-testid={`row-payment-${payment.id}`}>
                        <TableCell className="font-mono">{payment.receiptNumber || payment.id.slice(0, 8)}</TableCell>
                        <TableCell>{payment.studentId}</TableCell>
                        <TableCell>{payment.feeTypeId}</TableCell>
                        <TableCell className="font-medium">{formatCurrency(payment.amount)}</TableCell>
                        <TableCell className="capitalize">{payment.paymentMethod.replace("_", " ")}</TableCell>
                        <TableCell>{getStatusBadge(payment.status)}</TableCell>
                        <TableCell>{new Date(payment.createdAt!).toLocaleDateString()}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              ) : (
                <div className="text-center py-12">
                  <Receipt className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="text-lg font-medium">No payments recorded</h3>
                  <p className="text-muted-foreground">Record your first payment to get started.</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="reminders" className="mt-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between gap-2">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <Bell className="h-5 w-5" />
                  Outstanding Balances & Reminders
                </CardTitle>
                <p className="text-sm text-muted-foreground mt-1">
                  View students with outstanding fees and send payment reminders
                </p>
              </div>
              <Button
                onClick={() => sendBulkRemindersMutation.mutate()}
                disabled={sendBulkRemindersMutation.isPending || !overduePayments?.length}
                data-testid="button-send-bulk-reminders"
              >
                {sendBulkRemindersMutation.isPending ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Send className="h-4 w-4 mr-2" />
                )}
                Send All Reminders
              </Button>
            </CardHeader>
            <CardContent>
              {overdueLoading ? (
                <Skeleton className="h-64" />
              ) : overduePayments && overduePayments.length > 0 ? (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Admission No.</TableHead>
                      <TableHead>Parent</TableHead>
                      <TableHead>Outstanding Balance</TableHead>
                      <TableHead>Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {overduePayments.map((item) => (
                      <TableRow key={item.student.id} data-testid={`row-overdue-${item.student.id}`}>
                        <TableCell className="font-medium">
                          {item.student.firstName} {item.student.lastName}
                        </TableCell>
                        <TableCell className="font-mono">
                          {item.student.admissionNumber || "-"}
                        </TableCell>
                        <TableCell>
                          {item.parent ? (
                            `${item.parent.firstName} ${item.parent.lastName}`
                          ) : (
                            <span className="text-muted-foreground">No parent linked</span>
                          )}
                        </TableCell>
                        <TableCell className="font-medium text-red-600">
                          {formatCurrency(item.balance)}
                        </TableCell>
                        <TableCell>
                          {item.parent ? (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => sendReminderMutation.mutate({
                                studentId: item.student.id,
                                parentId: item.parent!.id,
                                amount: item.balance,
                                termId: item.termId,
                              })}
                              disabled={sendReminderMutation.isPending}
                              data-testid={`button-send-reminder-${item.student.id}`}
                            >
                              {sendReminderMutation.isPending ? (
                                <Loader2 className="h-4 w-4 mr-1 animate-spin" />
                              ) : (
                                <Bell className="h-4 w-4 mr-1" />
                              )}
                              Send Reminder
                            </Button>
                          ) : (
                            <Badge variant="secondary">No parent</Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              ) : (
                <div className="text-center py-12">
                  <DollarSign className="h-12 w-12 mx-auto text-green-500 mb-4" />
                  <h3 className="text-lg font-medium">No Outstanding Balances</h3>
                  <p className="text-muted-foreground">All students are up to date with their payments.</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

client/src/pages/school/terms.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Plus, Calendar, Edit, Trash2, Check } from "lucide-react";
import type { AcademicTerm } from "@shared/schema";

export default function TermsPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingTerm, setEditingTerm] = useState<AcademicTerm | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    sessionYear: "",
    startDate: "",
    endDate: "",
    isCurrent: false,
  });

  const { data: terms, isLoading, error, refetch } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/terms", {
        ...data,
        startDate: new Date(data.startDate).toISOString(),
        endDate: new Date(data.endDate).toISOString(),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/terms"] });
      toast({ title: "Academic term created successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to create term", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: typeof formData }) => {
      return apiRequest("PATCH", `/api/school/terms/${id}`, {
        ...data,
        startDate: new Date(data.startDate).toISOString(),
        endDate: new Date(data.endDate).toISOString(),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/terms"] });
      toast({ title: "Academic term updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update term", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/terms/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/terms"] });
      toast({ title: "Academic term deleted successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete term", description: error.message, variant: "destructive" });
    },
  });

  const setCurrentMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("POST", `/api/school/terms/${id}/set-current`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/terms"] });
      toast({ title: "Current term updated successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to set current term", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({ name: "", sessionYear: "", startDate: "", endDate: "", isCurrent: false });
    setEditingTerm(null);
  };

  const handleEdit = (term: AcademicTerm) => {
    setEditingTerm(term);
    setFormData({
      name: term.name,
      sessionYear: term.sessionYear,
      startDate: new Date(term.startDate).toISOString().split("T")[0],
      endDate: new Date(term.endDate).toISOString().split("T")[0],
      isCurrent: term.isCurrent,
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTerm) {
      updateMutation.mutate({ id: editingTerm.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const formatDate = (date: Date | string) => {
    return new Date(date).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Academic Terms"
          description="Manage academic sessions and terms"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Settings", href: "/school/terms" },
            { label: "Terms" }
          ]}
        />
        <TableSkeleton rows={5} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Academic Terms"
          description="Manage academic sessions and terms"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Settings", href: "/school/terms" },
            { label: "Terms" }
          ]}
        />
        <ErrorState 
          message="Failed to load academic terms. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Academic Terms"
        description="Manage academic sessions and terms"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Settings", href: "/school/terms" },
          { label: "Terms" }
        ]}
        actions={
          <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
            <DialogTrigger asChild>
              <Button data-testid="button-add-term">
                <Plus className="h-4 w-4 mr-2" />
                <span className="hidden sm:inline">Add Term</span>
                <span className="sm:hidden">Add</span>
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>{editingTerm ? "Edit Term" : "Add New Academic Term"}</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="name">Term Name</Label>
                    <Input
                      id="name"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      placeholder="e.g., First Term"
                      required
                      data-testid="input-term-name"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="sessionYear">Session Year</Label>
                    <Input
                      id="sessionYear"
                      value={formData.sessionYear}
                      onChange={(e) => setFormData({ ...formData, sessionYear: e.target.value })}
                      placeholder="e.g., 2024/2025"
                      required
                      data-testid="input-term-session"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="startDate">Start Date</Label>
                    <Input
                      id="startDate"
                      type="date"
                      value={formData.startDate}
                      onChange={(e) => setFormData({ ...formData, startDate: e.target.value })}
                      required
                      data-testid="input-term-start"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="endDate">End Date</Label>
                    <Input
                      id="endDate"
                      type="date"
                      value={formData.endDate}
                      onChange={(e) => setFormData({ ...formData, endDate: e.target.value })}
                      required
                      data-testid="input-term-end"
                    />
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <Switch
                    id="isCurrent"
                    checked={formData.isCurrent}
                    onCheckedChange={(checked) => setFormData({ ...formData, isCurrent: checked })}
                    data-testid="switch-term-current"
                  />
                  <Label htmlFor="isCurrent">Set as current term</Label>
                </div>
                <div className="flex justify-end gap-2">
                  <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                    Cancel
                  </Button>
                  <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending} data-testid="button-save-term">
                    {editingTerm ? "Update" : "Create"} Term
                  </Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        }
      />

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            All Terms ({terms?.length || 0})
          </CardTitle>
        </CardHeader>
        <CardContent>
          {terms && terms.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Term Name</TableHead>
                  <TableHead>Session Year</TableHead>
                  <TableHead>Start Date</TableHead>
                  <TableHead>End Date</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {terms.map((term) => (
                  <TableRow key={term.id} data-testid={`row-term-${term.id}`}>
                    <TableCell className="font-medium">{term.name}</TableCell>
                    <TableCell>{term.sessionYear}</TableCell>
                    <TableCell>{formatDate(term.startDate)}</TableCell>
                    <TableCell>{formatDate(term.endDate)}</TableCell>
                    <TableCell>
                      {term.isCurrent ? (
                        <Badge className="bg-green-600">Current</Badge>
                      ) : (
                        <Badge variant="outline">Inactive</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        {!term.isCurrent && (
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setCurrentMutation.mutate(term.id)}
                            title="Set as current term"
                            data-testid={`button-set-current-${term.id}`}
                          >
                            <Check className="h-4 w-4 text-green-600" />
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleEdit(term)}
                          data-testid={`button-edit-term-${term.id}`}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => deleteMutation.mutate(term.id)}
                          data-testid={`button-delete-term-${term.id}`}
                        >
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <EmptyState
              icon={Calendar}
              title="No academic terms found"
              description="Create your first academic term to get started."
              action={{
                label: "Add Term",
                onClick: () => setIsDialogOpen(true)
              }}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/announcements.ts.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { CardSkeleton } from "@/components/loading-skeleton";
import { Plus, Bell, Megaphone, Pin, Edit, Trash2, Eye, Calendar, Users } from "lucide-react";
import type { SchoolAnnouncement, SchoolClass } from "@shared/schema";

interface CurrentUser {
  user: {
    id: string;
    role: string;
  };
}

export default function AnnouncementsPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingAnnouncement, setEditingAnnouncement] = useState<SchoolAnnouncement | null>(null);

  const [formData, setFormData] = useState({
    title: "",
    content: "",
    type: "general",
    targetAudience: "all",
    targetClassIds: [] as string[],
    isPinned: false,
    isPublished: true,
  });

  const { data: currentUser } = useQuery<CurrentUser>({
    queryKey: ["/api/school/auth/me"],
  });

  const { data: announcements, isLoading, error, refetch } = useQuery<SchoolAnnouncement[]>({
    queryKey: ["/api/school/announcements"],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const isAdmin = currentUser?.user?.role === "admin" || currentUser?.user?.role === "school_admin";

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/announcements", {
        ...data,
        targetClassIds: data.targetAudience === "classes" ? data.targetClassIds : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/announcements"] });
      toast({ title: "Announcement created successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to create announcement", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: typeof formData }) => {
      return apiRequest("PATCH", `/api/school/announcements/${id}`, {
        ...data,
        targetClassIds: data.targetAudience === "classes" ? data.targetClassIds : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/announcements"] });
      toast({ title: "Announcement updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update announcement", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/announcements/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/announcements"] });
      toast({ title: "Announcement deleted" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete announcement", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({ title: "", content: "", type: "general", targetAudience: "all", targetClassIds: [], isPinned: false, isPublished: true });
    setEditingAnnouncement(null);
  };

  const handleEdit = (announcement: SchoolAnnouncement) => {
    setEditingAnnouncement(announcement);
    setFormData({
      title: announcement.title,
      content: announcement.content,
      type: announcement.type,
      targetAudience: announcement.targetClassIds && announcement.targetClassIds.length > 0 ? "classes" : announcement.targetAudience,
      targetClassIds: announcement.targetClassIds || [],
      isPinned: announcement.isPinned,
      isPublished: announcement.isPublished,
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.targetAudience === "classes" && formData.targetClassIds.length === 0) {
      toast({ title: "Please select at least one class", variant: "destructive" });
      return;
    }
    if (editingAnnouncement) {
      updateMutation.mutate({ id: editingAnnouncement.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleClassToggle = (classId: string) => {
    setFormData((prev) => ({
      ...prev,
      targetClassIds: prev.targetClassIds.includes(classId)
        ? prev.targetClassIds.filter((id) => id !== classId)
        : [...prev.targetClassIds, classId],
    }));
  };

  const getTypeBadge = (type: string) => {
    switch (type) {
      case "urgent":
        return <Badge variant="destructive">Urgent</Badge>;
      case "event":
        return <Badge className="bg-purple-600">Event</Badge>;
      case "holiday":
        return <Badge className="bg-green-600">Holiday</Badge>;
      default:
        return <Badge variant="secondary">General</Badge>;
    }
  };

  const getAudienceBadge = (announcement: SchoolAnnouncement) => {
    if (announcement.targetClassIds && announcement.targetClassIds.length > 0) {
      const classNames = announcement.targetClassIds
        .map((id) => classes?.find((c) => c.id === id)?.name)
        .filter(Boolean)
        .slice(0, 2)
        .join(", ");
      const remaining = announcement.targetClassIds.length - 2;
      return (
        <Badge variant="outline" className="flex items-center gap-1">
          <Users className="h-3 w-3" />
          {classNames}{remaining > 0 && ` +${remaining}`}
        </Badge>
      );
    }
    switch (announcement.targetAudience) {
      case "students":
        return <Badge variant="outline">Students</Badge>;
      case "teachers":
        return <Badge variant="outline">Teachers</Badge>;
      case "parents":
        return <Badge variant="outline">Parents</Badge>;
      default:
        return <Badge variant="outline">All</Badge>;
    }
  };

  const pinnedAnnouncements = announcements?.filter((a) => a.isPinned && a.isPublished) || [];
  const regularAnnouncements = announcements?.filter((a) => !a.isPinned) || [];

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Announcements"
          description={isAdmin ? "Create and manage school announcements" : "View school announcements"}
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Announcements" }
          ]}
        />
        <div className="grid gap-4 md:grid-cols-2">
          <CardSkeleton count={4} />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Announcements"
          description={isAdmin ? "Create and manage school announcements" : "View school announcements"}
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Announcements" }
          ]}
        />
        <ErrorState 
          message="Failed to load announcements. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Announcements"
        description={isAdmin ? "Create and manage school announcements" : "View school announcements"}
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Announcements" }
        ]}
        actions={
          isAdmin ? (
            <Button data-testid="button-add-announcement" onClick={() => setIsDialogOpen(true)}>
              <Plus className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">New Announcement</span>
              <span className="sm:hidden">New</span>
            </Button>
          ) : undefined
        }
      />

      {isAdmin && (
        <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle>{editingAnnouncement ? "Edit Announcement" : "Create Announcement"}</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="title">Title</Label>
                  <Input
                    id="title"
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    placeholder="Announcement title"
                    required
                    data-testid="input-announcement-title"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="content">Content</Label>
                  <Textarea
                    id="content"
                    value={formData.content}
                    onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                    placeholder="Write your announcement..."
                    rows={5}
                    required
                    data-testid="textarea-announcement-content"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>Type</Label>
                    <Select
                      value={formData.type}
                      onValueChange={(value) => setFormData({ ...formData, type: value })}
                    >
                      <SelectTrigger data-testid="select-announcement-type">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="general">General</SelectItem>
                        <SelectItem value="urgent">Urgent</SelectItem>
                        <SelectItem value="event">Event</SelectItem>
                        <SelectItem value="holiday">Holiday</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>Target Audience</Label>
                    <Select
                      value={formData.targetAudience}
                      onValueChange={(value) => setFormData({ ...formData, targetAudience: value, targetClassIds: [] })}
                    >
                      <SelectTrigger data-testid="select-announcement-audience">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="all">All</SelectItem>
                        <SelectItem value="students">Students Only</SelectItem>
                        <SelectItem value="teachers">Teachers Only</SelectItem>
                        <SelectItem value="parents">Parents Only</SelectItem>
                        <SelectItem value="classes">Specific Classes</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                {formData.targetAudience === "classes" && (
                  <div className="space-y-2">
                    <Label>Select Classes</Label>
                    <div className="border rounded-md p-3 max-h-40 overflow-y-auto space-y-2">
                      {classes && classes.length > 0 ? (
                        classes.map((cls) => (
                          <div key={cls.id} className="flex items-center space-x-2">
                            <Checkbox
                              id={`class-${cls.id}`}
                              checked={formData.targetClassIds.includes(cls.id)}
                              onCheckedChange={() => handleClassToggle(cls.id)}
                              data-testid={`checkbox-class-${cls.id}`}
                            />
                            <Label htmlFor={`class-${cls.id}`} className="text-sm font-normal cursor-pointer">
                              {cls.name}{cls.section && ` (${cls.section})`}
                            </Label>
                          </div>
                        ))
                      ) : (
                        <p className="text-sm text-muted-foreground">No classes available</p>
                      )}
                    </div>
                    {formData.targetClassIds.length > 0 && (
                      <p className="text-sm text-muted-foreground">
                        {formData.targetClassIds.length} class{formData.targetClassIds.length !== 1 && "es"} selected
                      </p>
                    )}
                  </div>
                )}
                <div className="flex items-center gap-6">
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="isPinned"
                      checked={formData.isPinned}
                      onCheckedChange={(checked) => setFormData({ ...formData, isPinned: checked })}
                      data-testid="switch-announcement-pinned"
                    />
                    <Label htmlFor="isPinned">Pin announcement</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Switch
                      id="isPublished"
                      checked={formData.isPublished}
                      onCheckedChange={(checked) => setFormData({ ...formData, isPublished: checked })}
                      data-testid="switch-announcement-published"
                    />
                    <Label htmlFor="isPublished">Publish immediately</Label>
                  </div>
                </div>
                <div className="flex justify-end gap-2">
                  <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                    Cancel
                  </Button>
                  <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending} data-testid="button-save-announcement">
                    {editingAnnouncement ? "Update" : "Create"} Announcement
                  </Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        )}

      {isAdmin && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center justify-between gap-2">
                <div>
                  <p className="text-sm text-muted-foreground">Total Announcements</p>
                  <p className="text-2xl font-bold">{announcements?.length || 0}</p>
                </div>
                <Megaphone className="h-8 w-8 text-blue-600" />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center justify-between gap-2">
                <div>
                  <p className="text-sm text-muted-foreground">Pinned</p>
                  <p className="text-2xl font-bold">{pinnedAnnouncements.length}</p>
                </div>
                <Pin className="h-8 w-8 text-orange-600" />
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center justify-between gap-2">
                <div>
                  <p className="text-sm text-muted-foreground">Published</p>
                  <p className="text-2xl font-bold">{announcements?.filter((a) => a.isPublished).length || 0}</p>
                </div>
                <Eye className="h-8 w-8 text-green-600" />
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {isLoading ? (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-32" />
          ))}
        </div>
      ) : (
        <div className="space-y-6">
          {pinnedAnnouncements.length > 0 && (
            <div>
              <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Pin className="h-5 w-5 text-orange-600" />
                Pinned Announcements
              </h2>
              <div className="space-y-4">
                {pinnedAnnouncements.map((announcement) => (
                  <Card key={announcement.id} className="border-l-4 border-l-orange-500" data-testid={`card-announcement-${announcement.id}`}>
                    <CardHeader className="flex flex-row items-start justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 flex-wrap mb-2">
                          <CardTitle className="text-lg">{announcement.title}</CardTitle>
                          {getTypeBadge(announcement.type)}
                          {getAudienceBadge(announcement)}
                          {!announcement.isPublished && <Badge variant="outline">Draft</Badge>}
                        </div>
                        <p className="text-sm text-muted-foreground flex items-center gap-2 flex-wrap">
                          <span className="flex items-center gap-1">
                            <Calendar className="h-4 w-4" />
                            {new Date(announcement.createdAt!).toLocaleDateString()}
                          </span>
                          {announcement.viewCount > 0 && (
                            <span className="flex items-center gap-1">
                              <Eye className="h-4 w-4" />
                              {announcement.viewCount} views
                            </span>
                          )}
                        </p>
                      </div>
                      {isAdmin && (
                        <div className="flex items-center gap-2">
                          <Button variant="ghost" size="icon" onClick={() => handleEdit(announcement)} data-testid={`button-edit-${announcement.id}`}>
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(announcement.id)} data-testid={`button-delete-${announcement.id}`}>
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      )}
                    </CardHeader>
                    <CardContent>
                      <p className="text-muted-foreground whitespace-pre-wrap">{announcement.content}</p>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          )}

          <div>
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Bell className="h-5 w-5" />
              {isAdmin ? "All Announcements" : "Recent Announcements"}
            </h2>
            {regularAnnouncements.length > 0 ? (
              <div className="space-y-4">
                {regularAnnouncements.map((announcement) => (
                  <Card key={announcement.id} data-testid={`card-announcement-${announcement.id}`}>
                    <CardHeader className="flex flex-row items-start justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 flex-wrap mb-2">
                          <CardTitle className="text-lg">{announcement.title}</CardTitle>
                          {getTypeBadge(announcement.type)}
                          {getAudienceBadge(announcement)}
                          {!announcement.isPublished && <Badge variant="outline">Draft</Badge>}
                        </div>
                        <p className="text-sm text-muted-foreground flex items-center gap-2 flex-wrap">
                          <span className="flex items-center gap-1">
                            <Calendar className="h-4 w-4" />
                            {new Date(announcement.createdAt!).toLocaleDateString()}
                          </span>
                          {announcement.viewCount > 0 && (
                            <span className="flex items-center gap-1">
                              <Eye className="h-4 w-4" />
                              {announcement.viewCount} views
                            </span>
                          )}
                        </p>
                      </div>
                      {isAdmin && (
                        <div className="flex items-center gap-2">
                          <Button variant="ghost" size="icon" onClick={() => handleEdit(announcement)} data-testid={`button-edit-${announcement.id}`}>
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(announcement.id)} data-testid={`button-delete-${announcement.id}`}>
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      )}
                    </CardHeader>
                    <CardContent>
                      <p className="text-muted-foreground whitespace-pre-wrap">{announcement.content}</p>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <Card>
                <CardContent className="py-12">
                  <div className="text-center">
                    <Megaphone className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                    <h3 className="text-lg font-medium">No announcements yet</h3>
                    <p className="text-muted-foreground">
                      {isAdmin 
                        ? "Create your first announcement to notify students, teachers, and parents."
                        : "Check back later for school announcements."
                      }
                    </p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

client/src/pages/school/login.tsx.content:
import { useState, useEffect } from "react";
import { useLocation, useSearch } from "wouter";
import { useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { GraduationCap, Loader2, Eye, EyeOff, Building2 } from "lucide-react";

interface SchoolInfo {
  id: string;
  name: string;
  subdomain: string;
  logoUrl: string | null;
  primaryColor: string | null;
}

interface LoginResponse {
  user: {
    id: string;
    email: string;
    firstName: string;
    lastName: string;
    role: string;
  };
  school: SchoolInfo;
}

export default function SchoolLoginPage() {
  const [, setLocation] = useLocation();
  const searchString = useSearch();
  const { toast } = useToast();
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

  // Get subdomain from query parameter (for testing mode)
  const urlParams = new URLSearchParams(searchString);
  const testSubdomain = urlParams.get('subdomain');
  const isTestMode = testSubdomain && !window.location.hostname.includes('studentdrive.com');

  const loginMutation = useMutation({
    mutationFn: async (data: typeof formData): Promise<LoginResponse> => {
      // Include subdomain in login request for testing mode
      const loginData = isTestMode 
        ? { ...data, subdomain: testSubdomain }
        : data;

      const response = await fetch("/api/school/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(loginData),
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || "Login failed");
      }
      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Login successful",
        description: `Welcome back, ${data.user.firstName}!`,
      });

      // Preserve subdomain in URL for testing mode
      const subdomainParam = isTestMode && testSubdomain ? `?subdomain=${testSubdomain}` : '';

      // Redirect based on role - session is managed server-side
      if (data.user.role === "parent") {
        setLocation(`/school/parent-dashboard${subdomainParam}`);
      } else {
        setLocation(`/school/dashboard${subdomainParam}`);
      }
    },
    onError: (error: Error) => {
      toast({
        title: "Login failed",
        description: error.message || "Invalid email or password",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    loginMutation.mutate(formData);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary/5 via-background to-primary/10 p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="space-y-4 text-center">
          <div className="mx-auto w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
            <GraduationCap className="h-8 w-8 text-primary" />
          </div>
          <div>
            <CardTitle className="text-2xl">School Portal Login</CardTitle>
            <CardDescription>
              Sign in to access your school portal
            </CardDescription>
            {isTestMode && testSubdomain && (
              <div className="mt-3 inline-flex items-center gap-2 px-3 py-1.5 bg-muted rounded-full text-sm">
                <Building2 className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Portal:</span>
                <span className="font-medium text-primary">{testSubdomain}</span>
              </div>
            )}
          </div>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="your.email@school.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
                disabled={loginMutation.isPending}
                data-testid="input-school-login-email"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Password</Label>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="Enter your password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  required
                  disabled={loginMutation.isPending}
                  data-testid="input-school-login-password"
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="absolute right-0 top-0 h-full px-3 hover:bg-transparent"
                  onClick={() => setShowPassword(!showPassword)}
                  data-testid="button-toggle-password"
                >
                  {showPassword ? (
                    <EyeOff className="h-4 w-4 text-muted-foreground" />
                  ) : (
                    <Eye className="h-4 w-4 text-muted-foreground" />
                  )}
                </Button>
              </div>
            </div>
            <Button
              type="submit"
              className="w-full"
              disabled={loginMutation.isPending}
              data-testid="button-school-login-submit"
            >
              {loginMutation.isPending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Signing in...
                </>
              ) : (
                "Sign In"
              )}
            </Button>
          </form>
          <div className="mt-6 space-y-3 text-center text-sm">
            <p className="text-muted-foreground">
              Contact your school administrator if you have trouble logging in.
            </p>
            <div className="border-t pt-3">
              <p className="text-muted-foreground">
                Want to register your school?{" "}
                <a 
                  href="/school/register" 
                  className="text-primary hover:underline font-medium"
                  data-testid="link-register-school"
                >
                  Start your free trial
                </a>
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/resources.tsx.content:
import { useState, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { CardSkeleton } from "@/components/loading-skeleton";
import {
  Plus,
  FileText,
  Download,
  Search,
  Edit,
  Trash2,
  File,
  Image,
  Video,
  FileSpreadsheet,
  Presentation,
  Upload,
  Link,
  Eye,
  Globe,
  Lock,
} from "lucide-react";
import type { SchoolMaterial, SchoolSubject, SchoolClass } from "@shared/schema";

interface CurrentUser {
  user: {
    id: string;
    firstName: string;
    lastName: string;
    role: string;
    classId?: string;
  };
  school: {
    id: string;
    name: string;
  };
}

export default function ResourcesPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterSubject, setFilterSubject] = useState<string>("all");
  const [editingMaterial, setEditingMaterial] = useState<SchoolMaterial | null>(null);
  const [uploadMode, setUploadMode] = useState<"file" | "url">("file");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    fileUrl: "",
    fileType: "pdf",
    subjectId: "",
    classId: "",
    isPublic: true,
  });

  const { data: currentUser } = useQuery<CurrentUser>({
    queryKey: ["/api/school/me"],
  });

  const canManageResources = currentUser?.user?.role === "school_admin" || currentUser?.user?.role === "teacher";
  const isStudent = currentUser?.user?.role === "school_student";
  const userClassId = currentUser?.user?.classId;

  const { data: materials, isLoading, error, refetch } = useQuery<SchoolMaterial[]>({
    queryKey: ["/api/school/materials"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/materials", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/materials"] });
      toast({ title: "Resource added successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to add resource", description: error.message, variant: "destructive" });
    },
  });

  const uploadMutation = useMutation({
    mutationFn: async (formDataToSend: FormData) => {
      const response = await fetch("/api/school/materials/upload", {
        method: "POST",
        body: formDataToSend,
        credentials: "include",
      });
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || "Upload failed");
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/materials"] });
      toast({ title: "Resource uploaded successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to upload resource", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      return apiRequest("PATCH", `/api/school/materials/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/materials"] });
      toast({ title: "Resource updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update resource", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/materials/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/materials"] });
      toast({ title: "Resource deleted" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to delete resource", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({ title: "", description: "", fileUrl: "", fileType: "pdf", subjectId: "", classId: "", isPublic: true });
    setEditingMaterial(null);
    setSelectedFile(null);
    setUploadMode("file");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleEdit = (material: SchoolMaterial) => {
    setEditingMaterial(material);
    setFormData({
      title: material.title,
      description: material.description || "",
      fileUrl: material.fileUrl,
      fileType: material.fileType || "pdf",
      subjectId: material.subjectId || "",
      classId: material.classId || "",
      isPublic: material.isPublic,
    });
    setUploadMode("url");
    setIsDialogOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      if (!formData.title) {
        setFormData(prev => ({ ...prev, title: file.name.replace(/\.[^/.]+$/, "") }));
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUploading(true);

    try {
      if (editingMaterial) {
        updateMutation.mutate({ id: editingMaterial.id, data: formData });
      } else if (uploadMode === "file" && selectedFile) {
        const formDataToSend = new FormData();
        formDataToSend.append("file", selectedFile);
        formDataToSend.append("title", formData.title);
        formDataToSend.append("description", formData.description);
        if (formData.subjectId) formDataToSend.append("subjectId", formData.subjectId);
        if (formData.classId) formDataToSend.append("classId", formData.classId);
        formDataToSend.append("isPublic", String(formData.isPublic));
        uploadMutation.mutate(formDataToSend);
      } else if (uploadMode === "url" && formData.fileUrl) {
        createMutation.mutate(formData);
      } else {
        toast({ title: "Please select a file or enter a URL", variant: "destructive" });
      }
    } finally {
      setIsUploading(false);
    }
  };

  const handleDownload = async (material: SchoolMaterial) => {
    try {
      await apiRequest("POST", `/api/school/materials/${material.id}/download`);
    } catch (error) {
      console.error("Failed to track download:", error);
    }
    window.open(material.fileUrl, "_blank");
  };

  const getFileIcon = (fileType: string | null) => {
    switch (fileType) {
      case "pdf":
        return <FileText className="h-8 w-8 text-red-600" />;
      case "doc":
      case "docx":
        return <File className="h-8 w-8 text-blue-600" />;
      case "xls":
      case "xlsx":
        return <FileSpreadsheet className="h-8 w-8 text-green-600" />;
      case "ppt":
      case "pptx":
        return <Presentation className="h-8 w-8 text-orange-600" />;
      case "video":
        return <Video className="h-8 w-8 text-purple-600" />;
      case "image":
        return <Image className="h-8 w-8 text-pink-600" />;
      default:
        return <File className="h-8 w-8 text-gray-600" />;
    }
  };

  const formatFileSize = (bytes: number | null) => {
    if (!bytes) return "";
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const getSubjectName = (id: string | null) => {
    if (!id) return "General";
    return subjects?.find((s) => s.id === id)?.name || "Unknown";
  };

  const getClassName = (id: string | null) => {
    if (!id) return null;
    return classes?.find((c) => c.id === id)?.name || null;
  };

  const filteredMaterials = materials?.filter((m) => {
    const matchesSearch = m.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      m.description?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesSubject = filterSubject === "all" || m.subjectId === filterSubject;
    const matchesClass = !isStudent || !m.classId || m.classId === userClassId;
    return matchesSearch && matchesSubject && matchesClass;
  });

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Resources"
          description={canManageResources 
            ? "Manage school learning materials and documents" 
            : "Browse and download school learning materials"}
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Resources" }
          ]}
        />
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          <CardSkeleton count={6} />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Resources"
          description={canManageResources 
            ? "Manage school learning materials and documents" 
            : "Browse and download school learning materials"}
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "Resources" }
          ]}
        />
        <ErrorState 
          message="Failed to load resources. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Resources"
        description={canManageResources 
          ? "Manage school learning materials and documents" 
          : "Browse and download school learning materials"}
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "Resources" }
        ]}
        actions={
          canManageResources ? (
            <Button data-testid="button-add-resource" onClick={() => setIsDialogOpen(true)}>
              <Plus className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">Add Resource</span>
              <span className="sm:hidden">Add</span>
            </Button>
          ) : undefined
        }
      />

      {canManageResources && (
        <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
          <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingMaterial ? "Edit Resource" : "Add Resource"}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              {!editingMaterial && (
                <Tabs value={uploadMode} onValueChange={(v) => setUploadMode(v as "file" | "url")}>
                  <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="file" className="flex items-center gap-2">
                      <Upload className="h-4 w-4" />
                      Upload File
                    </TabsTrigger>
                    <TabsTrigger value="url" className="flex items-center gap-2">
                      <Link className="h-4 w-4" />
                      External URL
                    </TabsTrigger>
                  </TabsList>
                  <TabsContent value="file" className="mt-4">
                    <div className="space-y-2">
                      <Label htmlFor="file">Select File</Label>
                      <Input
                        id="file"
                        type="file"
                        ref={fileInputRef}
                        onChange={handleFileChange}
                        accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.jpg,.jpeg,.png,.gif,.mp4,.mp3,.zip"
                        data-testid="input-resource-file"
                      />
                      {selectedFile && (
                        <p className="text-sm text-muted-foreground">
                          Selected: {selectedFile.name} ({formatFileSize(selectedFile.size)})
                        </p>
                      )}
                    </div>
                  </TabsContent>
                  <TabsContent value="url" className="mt-4">
                    <div className="space-y-2">
                      <Label htmlFor="fileUrl">File URL</Label>
                      <Input
                        id="fileUrl"
                        value={formData.fileUrl}
                        onChange={(e) => setFormData({ ...formData, fileUrl: e.target.value })}
                        placeholder="https://example.com/file.pdf"
                        data-testid="input-resource-url"
                      />
                    </div>
                  </TabsContent>
                </Tabs>
              )}

              {editingMaterial && (
                <div className="space-y-2">
                  <Label htmlFor="fileUrl">File URL</Label>
                  <Input
                    id="fileUrl"
                    value={formData.fileUrl}
                    onChange={(e) => setFormData({ ...formData, fileUrl: e.target.value })}
                    placeholder="https://example.com/file.pdf"
                    required
                    data-testid="input-resource-url"
                  />
                </div>
              )}

              <div className="space-y-2">
                <Label htmlFor="title">Title</Label>
                <Input
                  id="title"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  placeholder="Resource title"
                  required
                  data-testid="input-resource-title"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Brief description of the resource"
                  rows={3}
                  data-testid="textarea-resource-description"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Subject</Label>
                  <Select
                    value={formData.subjectId}
                    onValueChange={(value) => setFormData({ ...formData, subjectId: value })}
                  >
                    <SelectTrigger data-testid="select-resource-subject">
                      <SelectValue placeholder="Select subject" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="">General</SelectItem>
                      {subjects?.map((subject) => (
                        <SelectItem key={subject.id} value={subject.id}>
                          {subject.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Class</Label>
                  <Select
                    value={formData.classId}
                    onValueChange={(value) => setFormData({ ...formData, classId: value })}
                  >
                    <SelectTrigger data-testid="select-resource-class">
                      <SelectValue placeholder="All classes" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="">All Classes</SelectItem>
                      {classes?.map((cls) => (
                        <SelectItem key={cls.id} value={cls.id}>
                          {cls.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {uploadMode === "url" && !editingMaterial && (
                <div className="space-y-2">
                  <Label>File Type</Label>
                  <Select
                    value={formData.fileType}
                    onValueChange={(value) => setFormData({ ...formData, fileType: value })}
                  >
                    <SelectTrigger data-testid="select-resource-type">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="pdf">PDF</SelectItem>
                      <SelectItem value="doc">Word Document</SelectItem>
                      <SelectItem value="xls">Excel Spreadsheet</SelectItem>
                      <SelectItem value="ppt">PowerPoint</SelectItem>
                      <SelectItem value="video">Video</SelectItem>
                      <SelectItem value="image">Image</SelectItem>
                      <SelectItem value="other">Other</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              )}

              <div className="flex items-center justify-between py-2">
                <div className="space-y-0.5">
                  <Label htmlFor="isPublic">Visibility</Label>
                  <p className="text-sm text-muted-foreground">
                    {formData.isPublic ? "Visible to all in school" : "Only visible to selected class"}
                  </p>
                </div>
                <Switch
                  id="isPublic"
                  checked={formData.isPublic}
                  onCheckedChange={(checked) => setFormData({ ...formData, isPublic: checked })}
                  data-testid="switch-resource-public"
                />
              </div>

              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                  Cancel
                </Button>
                <Button 
                  type="submit" 
                  disabled={isUploading || uploadMutation.isPending || createMutation.isPending}
                  data-testid="button-save-resource"
                >
                  {isUploading || uploadMutation.isPending || createMutation.isPending ? "Saving..." : (editingMaterial ? "Update" : "Save")} Resource
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      )}

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              All Resources ({materials?.length || 0})
            </CardTitle>
            <div className="flex items-center gap-4 flex-wrap">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search resources..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9 w-64"
                  data-testid="input-search-resources"
                />
              </div>
              <Select value={filterSubject} onValueChange={setFilterSubject}>
                <SelectTrigger className="w-40" data-testid="select-filter-subject">
                  <SelectValue placeholder="Filter by subject" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Subjects</SelectItem>
                  {subjects?.map((subject) => (
                    <SelectItem key={subject.id} value={subject.id}>
                      {subject.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[1, 2, 3, 4, 5, 6].map((i) => (
                <Skeleton key={i} className="h-40" />
              ))}
            </div>
          ) : filteredMaterials && filteredMaterials.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredMaterials.map((material) => (
                <Card key={material.id} className="hover-elevate" data-testid={`card-resource-${material.id}`}>
                  <CardContent className="p-4">
                    <div className="flex items-start gap-4">
                      <div className="p-3 bg-muted rounded-lg">
                        {getFileIcon(material.fileType)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <h3 className="font-medium truncate">{material.title}</h3>
                        {material.description && (
                          <p className="text-sm text-muted-foreground line-clamp-2 mt-1">
                            {material.description}
                          </p>
                        )}
                        <div className="flex items-center gap-2 mt-2 flex-wrap">
                          <Badge variant="outline" className="text-xs">
                            {getSubjectName(material.subjectId)}
                          </Badge>
                          {getClassName(material.classId) && (
                            <Badge variant="secondary" className="text-xs">
                              {getClassName(material.classId)}
                            </Badge>
                          )}
                          {material.isPublic ? (
                            <Globe className="h-3 w-3 text-muted-foreground" />
                          ) : (
                            <Lock className="h-3 w-3 text-muted-foreground" />
                          )}
                        </div>
                        <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                          {material.fileSize && (
                            <span>{formatFileSize(material.fileSize)}</span>
                          )}
                          {material.viewCount > 0 && (
                            <span className="flex items-center gap-1">
                              <Eye className="h-3 w-3" />
                              {material.viewCount}
                            </span>
                          )}
                          {material.downloadCount > 0 && (
                            <span className="flex items-center gap-1">
                              <Download className="h-3 w-3" />
                              {material.downloadCount}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center justify-between mt-4">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDownload(material)}
                        className="text-primary"
                        data-testid={`button-download-${material.id}`}
                      >
                        <Download className="h-4 w-4 mr-1" />
                        Download
                      </Button>
                      {canManageResources && (
                        <div className="flex items-center gap-1">
                          <Button variant="ghost" size="icon" onClick={() => handleEdit(material)} data-testid={`button-edit-${material.id}`}>
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(material.id)} data-testid={`button-delete-${material.id}`}>
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <div className="text-center py-12">
              <FileText className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No resources found</h3>
              <p className="text-muted-foreground">
                {canManageResources 
                  ? "Upload your first resource to get started." 
                  : "No learning materials have been shared yet. Check back later."}
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/teachers.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { PageHeader } from "@/components/page-header";
import { EmptyState, ErrorState } from "@/components/empty-state";
import { TableSkeleton } from "@/components/loading-skeleton";
import { Users, Edit, Trash2, Search, UserPlus } from "lucide-react";
import type { SchoolUser } from "@shared/schema";

export default function TeachersPage() {
  const { toast } = useToast();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingTeacher, setEditingTeacher] = useState<SchoolUser | null>(null);
  const [searchQuery, setSearchQuery] = useState("");

  const [formData, setFormData] = useState({
    email: "",
    password: "",
    firstName: "",
    lastName: "",
    middleName: "",
    gender: "",
    phone: "",
    address: "",
    employeeId: "",
    qualification: "",
    specialization: "",
    dateOfEmployment: "",
  });

  const { data: teachers, isLoading, error, refetch } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "teacher" }],
  });

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest("POST", "/api/school/users", {
        ...data,
        role: "teacher",
        dateOfEmployment: data.dateOfEmployment ? new Date(data.dateOfEmployment).toISOString() : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Teacher added successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to add teacher", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<typeof formData> }) => {
      return apiRequest("PATCH", `/api/school/users/${id}`, {
        ...data,
        dateOfEmployment: data.dateOfEmployment ? new Date(data.dateOfEmployment).toISOString() : null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Teacher updated successfully" });
      resetForm();
      setIsDialogOpen(false);
    },
    onError: (error: Error) => {
      toast({ title: "Failed to update teacher", description: error.message, variant: "destructive" });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/school/users/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/school/users"] });
      toast({ title: "Teacher removed successfully" });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to remove teacher", description: error.message, variant: "destructive" });
    },
  });

  const resetForm = () => {
    setFormData({
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      middleName: "",
      gender: "",
      phone: "",
      address: "",
      employeeId: "",
      qualification: "",
      specialization: "",
      dateOfEmployment: "",
    });
    setEditingTeacher(null);
  };

  const handleEdit = (teacher: SchoolUser) => {
    setEditingTeacher(teacher);
    setFormData({
      email: teacher.email,
      password: "",
      firstName: teacher.firstName,
      lastName: teacher.lastName,
      middleName: teacher.middleName || "",
      gender: teacher.gender || "",
      phone: teacher.phone || "",
      address: teacher.address || "",
      employeeId: teacher.employeeId || "",
      qualification: teacher.qualification || "",
      specialization: teacher.specialization || "",
      dateOfEmployment: teacher.dateOfEmployment
        ? new Date(teacher.dateOfEmployment).toISOString().split("T")[0]
        : "",
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTeacher) {
      const { password, ...updateData } = formData;
      updateMutation.mutate({ id: editingTeacher.id, data: updateData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const filteredTeachers = teachers?.filter((t) =>
    t.firstName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    t.lastName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    t.employeeId?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    t.email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Teachers"
          description="Manage teaching staff and assignments"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "People", href: "/school/teachers" },
            { label: "Teachers" }
          ]}
        />
        <TableSkeleton rows={5} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <PageHeader
          title="Teachers"
          description="Manage teaching staff and assignments"
          breadcrumbs={[
            { label: "Dashboard", href: "/school/dashboard" },
            { label: "People", href: "/school/teachers" },
            { label: "Teachers" }
          ]}
        />
        <ErrorState 
          message="Failed to load teachers. Please try again."
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-6">
      <PageHeader
        title="Teachers"
        description="Manage teaching staff and assignments"
        breadcrumbs={[
          { label: "Dashboard", href: "/school/dashboard" },
          { label: "People", href: "/school/teachers" },
          { label: "Teachers" }
        ]}
        actions={
          <Button onClick={() => setIsDialogOpen(true)} data-testid="button-add-teacher">
            <UserPlus className="h-4 w-4 mr-2" />
            <span className="hidden sm:inline">Add Teacher</span>
            <span className="sm:hidden">Add</span>
          </Button>
        }
      />

      <Dialog open={isDialogOpen} onOpenChange={(open) => { setIsDialogOpen(open); if (!open) resetForm(); }}>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingTeacher ? "Edit Teacher" : "Add New Teacher"}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="firstName">First Name</Label>
                  <Input
                    id="firstName"
                    value={formData.firstName}
                    onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                    required
                    data-testid="input-teacher-firstname"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="middleName">Middle Name</Label>
                  <Input
                    id="middleName"
                    value={formData.middleName}
                    onChange={(e) => setFormData({ ...formData, middleName: e.target.value })}
                    data-testid="input-teacher-middlename"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="lastName">Last Name</Label>
                  <Input
                    id="lastName"
                    value={formData.lastName}
                    onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                    required
                    data-testid="input-teacher-lastname"
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    required
                    data-testid="input-teacher-email"
                  />
                </div>
                {!editingTeacher && (
                  <div className="space-y-2">
                    <Label htmlFor="password">Password</Label>
                    <Input
                      id="password"
                      type="password"
                      value={formData.password}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      required={!editingTeacher}
                      data-testid="input-teacher-password"
                    />
                  </div>
                )}
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="employeeId">Employee ID</Label>
                  <Input
                    id="employeeId"
                    value={formData.employeeId}
                    onChange={(e) => setFormData({ ...formData, employeeId: e.target.value })}
                    data-testid="input-teacher-employeeid"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Gender</Label>
                  <Select
                    value={formData.gender}
                    onValueChange={(value) => setFormData({ ...formData, gender: value })}
                  >
                    <SelectTrigger data-testid="select-teacher-gender">
                      <SelectValue placeholder="Select gender" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="male">Male</SelectItem>
                      <SelectItem value="female">Female</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="dateOfEmployment">Date of Employment</Label>
                  <Input
                    id="dateOfEmployment"
                    type="date"
                    value={formData.dateOfEmployment}
                    onChange={(e) => setFormData({ ...formData, dateOfEmployment: e.target.value })}
                    data-testid="input-teacher-employment"
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="qualification">Qualification</Label>
                  <Input
                    id="qualification"
                    value={formData.qualification}
                    onChange={(e) => setFormData({ ...formData, qualification: e.target.value })}
                    placeholder="e.g., B.Ed, M.Sc"
                    data-testid="input-teacher-qualification"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="specialization">Specialization</Label>
                  <Input
                    id="specialization"
                    value={formData.specialization}
                    onChange={(e) => setFormData({ ...formData, specialization: e.target.value })}
                    placeholder="e.g., Mathematics, English"
                    data-testid="input-teacher-specialization"
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="phone">Phone</Label>
                  <Input
                    id="phone"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    data-testid="input-teacher-phone"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="address">Address</Label>
                  <Input
                    id="address"
                    value={formData.address}
                    onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                    data-testid="input-teacher-address"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => { setIsDialogOpen(false); resetForm(); }}>
                  Cancel
                </Button>
                <Button type="submit" data-testid="button-save-teacher">
                  {editingTeacher ? "Update" : "Add"} Teacher
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <CardTitle className="flex items-center gap-2">
              <Users className="h-5 w-5" />
              All Teachers ({teachers?.length || 0})
            </CardTitle>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search teachers..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 w-64"
                data-testid="input-search-teachers"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {filteredTeachers && filteredTeachers.length > 0 ? (
            <ScrollArea className="w-full">
              <div className="min-w-[700px]">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead className="hidden sm:table-cell">Employee ID</TableHead>
                      <TableHead className="hidden md:table-cell">Email</TableHead>
                      <TableHead className="hidden lg:table-cell">Qualification</TableHead>
                      <TableHead className="hidden lg:table-cell">Specialization</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredTeachers.map((teacher) => (
                      <TableRow key={teacher.id} data-testid={`row-teacher-${teacher.id}`}>
                        <TableCell className="font-medium">
                          <div>
                            {teacher.firstName} {teacher.middleName ? `${teacher.middleName} ` : ""}{teacher.lastName}
                          </div>
                          <div className="text-xs text-muted-foreground md:hidden">{teacher.email}</div>
                        </TableCell>
                        <TableCell className="hidden sm:table-cell">{teacher.employeeId || "-"}</TableCell>
                        <TableCell className="hidden md:table-cell">{teacher.email}</TableCell>
                        <TableCell className="hidden lg:table-cell">{teacher.qualification || "-"}</TableCell>
                        <TableCell className="hidden lg:table-cell">{teacher.specialization || "-"}</TableCell>
                        <TableCell>
                          <Badge variant={teacher.isActive ? "default" : "secondary"}>
                            {teacher.isActive ? "Active" : "Inactive"}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button variant="ghost" size="icon" onClick={() => handleEdit(teacher)} data-testid={`button-edit-teacher-${teacher.id}`}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => deleteMutation.mutate(teacher.id)} data-testid={`button-delete-teacher-${teacher.id}`}>
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
          ) : (
            <EmptyState
              icon={Users}
              title="No teachers found"
              description={searchQuery ? "No teachers match your search. Try a different search term." : "Add your first teacher to get started with managing your teaching staff."}
              action={searchQuery ? undefined : { label: "Add Teacher", onClick: () => setIsDialogOpen(true) }}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

