import { useState, useEffect, useRef } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { 
  FileSpreadsheet, 
  Download, 
  Printer, 
  GraduationCap, 
  Users,
  Calendar,
  Award,
  TrendingUp
} from "lucide-react";
import type { SchoolClass, AcademicTerm, TermResult, SchoolSubject, SchoolUser } from "@shared/schema";

interface StudentReportData {
  student: SchoolUser;
  results: TermResult[];
  totalScore: number;
  averageScore: number;
  overallGrade: string;
  position: number;
  totalStudents: number;
}

export default function ReportCardsPage() {
  const { toast } = useToast();
  const reportRef = useRef<HTMLDivElement>(null);
  const [selectedTerm, setSelectedTerm] = useState<string>("");
  const [selectedClass, setSelectedClass] = useState<string>("");
  const [selectedStudent, setSelectedStudent] = useState<string>("");

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: students, isLoading: studentsLoading } = useQuery<SchoolUser[]>({
    queryKey: [`/api/school/classes/${selectedClass}/students`],
    enabled: !!selectedClass,
  });

  const { data: classResults, isLoading: resultsLoading } = useQuery<TermResult[]>({
    queryKey: [`/api/school/classes/${selectedClass}/results`, { termId: selectedTerm }],
    enabled: !!selectedClass && !!selectedTerm,
  });

  const { data: studentResults } = useQuery<TermResult[]>({
    queryKey: [`/api/school/students/${selectedStudent}/results`, { termId: selectedTerm }],
    enabled: !!selectedStudent && !!selectedTerm,
  });

  useEffect(() => {
    if (terms && terms.length > 0 && !selectedTerm) {
      const currentTerm = terms.find(t => t.isCurrent);
      if (currentTerm) {
        setSelectedTerm(currentTerm.id);
      }
    }
  }, [terms, selectedTerm]);

  useEffect(() => {
    setSelectedStudent("");
  }, [selectedClass]);

  const getSubjectName = (subjectId: string) => {
    const subject = subjects?.find(s => s.id === subjectId);
    return subject?.name || "Unknown";
  };

  const getGradeColor = (grade: string) => {
    switch (grade) {
      case "A": return "text-green-600 dark:text-green-400";
      case "B": return "text-blue-600 dark:text-blue-400";
      case "C": return "text-yellow-600 dark:text-yellow-400";
      case "D": return "text-orange-600 dark:text-orange-400";
      default: return "text-red-600 dark:text-red-400";
    }
  };

  const getGradeRemark = (grade: string) => {
    switch (grade) {
      case "A": return "Excellent";
      case "B": return "Very Good";
      case "C": return "Good";
      case "D": return "Fair";
      default: return "Needs Improvement";
    }
  };

  const calculateStudentStats = () => {
    if (!studentResults || studentResults.length === 0) return null;

    const totalScore = studentResults.reduce((sum, r) => sum + r.totalScore, 0);
    const averageScore = Math.round(totalScore / studentResults.length);

    let overallGrade = "F";
    if (averageScore >= 70) overallGrade = "A";
    else if (averageScore >= 60) overallGrade = "B";
    else if (averageScore >= 50) overallGrade = "C";
    else if (averageScore >= 40) overallGrade = "D";

    const studentPosition = calculatePosition();

    return {
      totalScore,
      averageScore,
      overallGrade,
      position: studentPosition,
      totalStudents: students?.length || 0,
    };
  };

  const calculatePosition = () => {
    if (!classResults || !students || !selectedStudent) return 0;

    const studentAverages: { studentId: string; average: number }[] = [];

    students.forEach(student => {
      const studentResults = classResults.filter(r => r.studentId === student.id);
      if (studentResults.length > 0) {
        const total = studentResults.reduce((sum, r) => sum + r.totalScore, 0);
        const average = total / studentResults.length;
        studentAverages.push({ studentId: student.id, average });
      }
    });

    studentAverages.sort((a, b) => b.average - a.average);
    const position = studentAverages.findIndex(s => s.studentId === selectedStudent) + 1;
    return position || 0;
  };

  const handlePrint = () => {
    if (reportRef.current) {
      const printContent = reportRef.current.innerHTML;
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(`
          <!DOCTYPE html>
          <html>
          <head>
            <title>Report Card - ${selectedStudentData?.firstName} ${selectedStudentData?.lastName}</title>
            <style>
              body { 
                font-family: Arial, sans-serif; 
                padding: 20px;
                max-width: 800px;
                margin: 0 auto;
              }
              table { 
                width: 100%; 
                border-collapse: collapse; 
                margin: 20px 0;
              }
              th, td { 
                border: 1px solid #ddd; 
                padding: 12px; 
                text-align: left; 
              }
              th { 
                background-color: #f5f5f5; 
                font-weight: bold;
              }
              .header { 
                text-align: center; 
                margin-bottom: 30px;
                border-bottom: 2px solid #333;
                padding-bottom: 20px;
              }
              .header h1 { 
                margin: 0 0 10px 0;
                color: #333;
              }
              .student-info { 
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 10px;
                margin: 20px 0;
                padding: 15px;
                background: #f9f9f9;
                border-radius: 8px;
              }
              .summary { 
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 15px;
                margin: 20px 0;
              }
              .summary-item {
                text-align: center;
                padding: 15px;
                background: #f5f5f5;
                border-radius: 8px;
              }
              .summary-item .label { 
                font-size: 12px; 
                color: #666;
                margin-bottom: 5px;
              }
              .summary-item .value { 
                font-size: 24px; 
                font-weight: bold;
              }
              .grade-a { color: #16a34a; }
              .grade-b { color: #2563eb; }
              .grade-c { color: #ca8a04; }
              .grade-d { color: #ea580c; }
              .grade-f { color: #dc2626; }
              .footer {
                margin-top: 40px;
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 40px;
              }
              .signature-line {
                border-top: 1px solid #333;
                padding-top: 10px;
                text-align: center;
              }
              @media print {
                body { padding: 0; }
                .no-print { display: none; }
              }
            </style>
          </head>
          <body>
            ${printContent}
          </body>
          </html>
        `);
        printWindow.document.close();
        printWindow.print();
      }
    }
  };

  const handleDownloadPDF = () => {
    toast({ 
      title: "Generating PDF...", 
      description: "Your report card PDF will be downloaded shortly." 
    });
    handlePrint();
  };

  const selectedStudentData = students?.find(s => s.id === selectedStudent);
  const selectedTermData = terms?.find(t => t.id === selectedTerm);
  const selectedClassData = classes?.find(c => c.id === selectedClass);
  const studentStats = calculateStudentStats();

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">Report Cards</h1>
          <p className="text-muted-foreground">Generate and export student report cards</p>
        </div>
        {selectedStudent && studentResults && studentResults.length > 0 && (
          <div className="flex gap-2">
            <Button variant="outline" onClick={handlePrint} data-testid="button-print-report">
              <Printer className="h-4 w-4 mr-2" />
              Print
            </Button>
            <Button onClick={handleDownloadPDF} data-testid="button-download-pdf">
              <Download className="h-4 w-4 mr-2" />
              Download PDF
            </Button>
          </div>
        )}
      </div>

      <Card data-testid="card-report-filters">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileSpreadsheet className="h-5 w-5" />
            Select Term, Class & Student
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Term</label>
              <Select value={selectedTerm} onValueChange={setSelectedTerm}>
                <SelectTrigger data-testid="select-report-term">
                  <SelectValue placeholder="Select a term" />
                </SelectTrigger>
                <SelectContent>
                  {terms?.map((term) => (
                    <SelectItem key={term.id} value={term.id}>
                      {term.name} {term.isCurrent && "(Current)"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Class</label>
              <Select value={selectedClass} onValueChange={setSelectedClass}>
                <SelectTrigger data-testid="select-report-class">
                  <SelectValue placeholder="Select a class" />
                </SelectTrigger>
                <SelectContent>
                  {classes?.map((classItem) => (
                    <SelectItem key={classItem.id} value={classItem.id}>
                      {classItem.name} {classItem.section ? `(${classItem.section})` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Student</label>
              <Select value={selectedStudent} onValueChange={setSelectedStudent} disabled={!selectedClass}>
                <SelectTrigger data-testid="select-report-student">
                  <SelectValue placeholder="Select a student" />
                </SelectTrigger>
                <SelectContent>
                  {students?.map((student) => (
                    <SelectItem key={student.id} value={student.id}>
                      {student.firstName} {student.lastName} ({student.admissionNumber || "N/A"})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {selectedStudent && selectedTerm && (
        <>
          {resultsLoading ? (
            <Card data-testid="card-report-loading">
              <CardContent className="pt-6">
                <div className="space-y-4">
                  {[1, 2, 3, 4].map((i) => (
                    <Skeleton key={i} className="h-16" data-testid={`skeleton-report-${i}`} />
                  ))}
                </div>
              </CardContent>
            </Card>
          ) : studentResults && studentResults.length > 0 ? (
            <Card data-testid="card-report-content">
              <CardContent className="pt-6">
                <div ref={reportRef} data-testid="div-report-card">
                  <div className="header text-center mb-6 pb-4 border-b-2">
                    <h1 className="text-2xl font-bold mb-2">STUDENT REPORT CARD</h1>
                    <p className="text-lg">{selectedTermData?.name}</p>
                  </div>

                  <div className="student-info grid grid-cols-2 gap-4 p-4 bg-muted/30 rounded-lg mb-6">
                    <div className="flex items-center gap-2">
                      <GraduationCap className="h-5 w-5 text-muted-foreground" />
                      <div>
                        <p className="text-sm text-muted-foreground">Student Name</p>
                        <p className="font-semibold">{selectedStudentData?.firstName} {selectedStudentData?.lastName}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Users className="h-5 w-5 text-muted-foreground" />
                      <div>
                        <p className="text-sm text-muted-foreground">Class</p>
                        <p className="font-semibold">{selectedClassData?.name} {selectedClassData?.section && `(${selectedClassData.section})`}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <FileSpreadsheet className="h-5 w-5 text-muted-foreground" />
                      <div>
                        <p className="text-sm text-muted-foreground">Admission No.</p>
                        <p className="font-semibold">{selectedStudentData?.admissionNumber || "N/A"}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Calendar className="h-5 w-5 text-muted-foreground" />
                      <div>
                        <p className="text-sm text-muted-foreground">Academic Term</p>
                        <p className="font-semibold">{selectedTermData?.name}</p>
                      </div>
                    </div>
                  </div>

                  {studentStats && (
                    <div className="summary grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                      <div className="summary-item text-center p-4 bg-muted/30 rounded-lg">
                        <p className="text-sm text-muted-foreground mb-1">Total Score</p>
                        <p className="text-2xl font-bold">{studentStats.totalScore}</p>
                      </div>
                      <div className="summary-item text-center p-4 bg-muted/30 rounded-lg">
                        <p className="text-sm text-muted-foreground mb-1">Average</p>
                        <p className="text-2xl font-bold">{studentStats.averageScore}%</p>
                      </div>
                      <div className="summary-item text-center p-4 bg-muted/30 rounded-lg">
                        <p className="text-sm text-muted-foreground mb-1">Grade</p>
                        <p className={`text-2xl font-bold ${getGradeColor(studentStats.overallGrade)}`}>
                          {studentStats.overallGrade}
                        </p>
                      </div>
                      <div className="summary-item text-center p-4 bg-muted/30 rounded-lg">
                        <p className="text-sm text-muted-foreground mb-1">Position</p>
                        <div className="flex items-center justify-center gap-1">
                          <Award className="h-5 w-5 text-yellow-500" />
                          <p className="text-2xl font-bold">{studentStats.position}/{studentStats.totalStudents}</p>
                        </div>
                      </div>
                    </div>
                  )}

                  <Table data-testid="table-report-results">
                    <TableHeader>
                      <TableRow>
                        <TableHead>Subject</TableHead>
                        <TableHead className="text-center">Score</TableHead>
                        <TableHead className="text-center">Grade</TableHead>
                        <TableHead className="text-center">Position</TableHead>
                        <TableHead className="text-center">Class Average</TableHead>
                        <TableHead>Remark</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {studentResults.map((result) => (
                        <TableRow key={result.id} data-testid={`row-report-${result.id}`}>
                          <TableCell className="font-medium">{getSubjectName(result.subjectId)}</TableCell>
                          <TableCell className="text-center">{result.totalScore}%</TableCell>
                          <TableCell className="text-center">
                            <Badge className={getGradeColor(result.grade || "F")}>
                              {result.grade || "-"}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-center">{result.position || "-"}</TableCell>
                          <TableCell className="text-center">
                            {result.classAverage ? `${Math.round(result.classAverage)}%` : "-"}
                          </TableCell>
                          <TableCell>{getGradeRemark(result.grade || "F")}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>

                  <Separator className="my-6" />

                  <div className="footer grid grid-cols-2 gap-8 mt-8">
                    <div>
                      <div className="border-t pt-2 text-center">
                        <p className="text-sm text-muted-foreground">Class Teacher's Signature</p>
                      </div>
                    </div>
                    <div>
                      <div className="border-t pt-2 text-center">
                        <p className="text-sm text-muted-foreground">Principal's Signature</p>
                      </div>
                    </div>
                  </div>

                  <div className="mt-6 p-4 bg-muted/30 rounded-lg">
                    <h4 className="font-semibold mb-2">Grading Scale</h4>
                    <div className="grid grid-cols-5 gap-2 text-sm">
                      <div><span className="text-green-600 font-bold">A</span>: 70-100% (Excellent)</div>
                      <div><span className="text-blue-600 font-bold">B</span>: 60-69% (Very Good)</div>
                      <div><span className="text-yellow-600 font-bold">C</span>: 50-59% (Good)</div>
                      <div><span className="text-orange-600 font-bold">D</span>: 40-49% (Fair)</div>
                      <div><span className="text-red-600 font-bold">F</span>: 0-39% (Fail)</div>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card data-testid="card-no-results">
              <CardContent className="py-12">
                <div className="text-center">
                  <TrendingUp className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="text-lg font-medium" data-testid="text-no-results-title">No Results Available</h3>
                  <p className="text-muted-foreground" data-testid="text-no-results-description">
                    This student has no term results yet. Please enter grades and calculate term results first.
                  </p>
                </div>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {(!selectedTerm || !selectedClass || !selectedStudent) && (
        <Card data-testid="card-select-filters">
          <CardContent className="py-12">
            <div className="text-center">
              <FileSpreadsheet className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium" data-testid="text-select-filters-title">Select Term, Class & Student</h3>
              <p className="text-muted-foreground" data-testid="text-select-filters-description">Choose all filters above to view and generate report card.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/pages/school/grades-results.t.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Calculator, TrendingUp, Users, Trophy, Medal, Award } from "lucide-react";
import type { SchoolClass, AcademicTerm, TermResult, SchoolSubject } from "@shared/schema";

interface EnrichedTermResult extends TermResult {
  studentName?: string;
  subjectName?: string;
  admissionNumber?: string;
}

interface StudentResultSummary {
  studentId: string;
  studentName: string;
  admissionNumber: string;
  totalScore: number;
  averageScore: number;
  subjectCount: number;
  overallGrade: string;
  position: number;
}

export default function GradesResultsPage() {
  const { toast } = useToast();
  const [selectedTerm, setSelectedTerm] = useState<string>("");
  const [selectedClass, setSelectedClass] = useState<string>("");

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: classes } = useQuery<SchoolClass[]>({
    queryKey: ["/api/school/classes"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: classResults, isLoading: resultsLoading, refetch: refetchResults } = useQuery<TermResult[]>({
    queryKey: [`/api/school/classes/${selectedClass}/results`, { termId: selectedTerm }],
    enabled: !!selectedClass && !!selectedTerm,
  });

  const { data: students } = useQuery<any[]>({
    queryKey: [`/api/school/classes/${selectedClass}/students`],
    enabled: !!selectedClass,
  });

  useEffect(() => {
    if (terms && terms.length > 0 && !selectedTerm) {
      const currentTerm = terms.find(t => t.isCurrent);
      if (currentTerm) {
        setSelectedTerm(currentTerm.id);
      }
    }
  }, [terms, selectedTerm]);

  const calculateMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("POST", "/api/school/results/calculate", {
        classId: selectedClass,
        termId: selectedTerm,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/school/classes/${selectedClass}/results`] });
      refetchResults();
      toast({ title: "Term results calculated successfully", description: "Student positions and averages have been updated." });
    },
    onError: (error: Error) => {
      toast({ title: "Failed to calculate results", description: error.message, variant: "destructive" });
    },
  });

  const getStudentName = (studentId: string) => {
    const student = students?.find(s => s.id === studentId);
    return student ? `${student.firstName} ${student.lastName}` : "Unknown";
  };

  const getAdmissionNumber = (studentId: string) => {
    const student = students?.find(s => s.id === studentId);
    return student?.admissionNumber || "-";
  };

  const getSubjectName = (subjectId: string) => {
    const subject = subjects?.find(s => s.id === subjectId);
    return subject?.name || "Unknown";
  };

  const getStudentSummaries = (): StudentResultSummary[] => {
    if (!classResults || !students) return [];

    const studentScores: Record<string, { total: number; count: number; scores: number[] }> = {};

    classResults.forEach(result => {
      if (!studentScores[result.studentId]) {
        studentScores[result.studentId] = { total: 0, count: 0, scores: [] };
      }
      studentScores[result.studentId].total += result.totalScore;
      studentScores[result.studentId].count += 1;
      studentScores[result.studentId].scores.push(result.totalScore);
    });

    const summaries: StudentResultSummary[] = Object.entries(studentScores).map(([studentId, data]) => {
      const average = Math.round(data.total / data.count);
      let grade = "F";
      if (average >= 70) grade = "A";
      else if (average >= 60) grade = "B";
      else if (average >= 50) grade = "C";
      else if (average >= 40) grade = "D";

      return {
        studentId,
        studentName: getStudentName(studentId),
        admissionNumber: getAdmissionNumber(studentId),
        totalScore: data.total,
        averageScore: average,
        subjectCount: data.count,
        overallGrade: grade,
        position: 0,
      };
    });

    summaries.sort((a, b) => b.averageScore - a.averageScore);
    summaries.forEach((summary, index) => {
      summary.position = index + 1;
    });

    return summaries;
  };

  const getGradeColor = (grade: string) => {
    switch (grade) {
      case "A": return "text-green-600 dark:text-green-400";
      case "B": return "text-blue-600 dark:text-blue-400";
      case "C": return "text-yellow-600 dark:text-yellow-400";
      case "D": return "text-orange-600 dark:text-orange-400";
      default: return "text-red-600 dark:text-red-400";
    }
  };

  const getPositionIcon = (position: number) => {
    if (position === 1) return <Trophy className="h-5 w-5 text-yellow-500" />;
    if (position === 2) return <Medal className="h-5 w-5 text-gray-400" />;
    if (position === 3) return <Award className="h-5 w-5 text-amber-600" />;
    return null;
  };

  const studentSummaries = getStudentSummaries();
  const selectedTermData = terms?.find(t => t.id === selectedTerm);
  const selectedClassData = classes?.find(c => c.id === selectedClass);

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">Term Results</h1>
          <p className="text-muted-foreground">View and calculate student term results and positions</p>
        </div>
        {selectedClass && selectedTerm && (
          <Button 
            onClick={() => calculateMutation.mutate()} 
            disabled={calculateMutation.isPending}
            data-testid="button-calculate-results"
          >
            <Calculator className="h-4 w-4 mr-2" />
            {calculateMutation.isPending ? "Calculating..." : "Calculate Results"}
          </Button>
        )}
      </div>

      <Card data-testid="card-results-filters">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <TrendingUp className="h-5 w-5" />
            Select Term and Class
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Term</label>
              <Select value={selectedTerm} onValueChange={setSelectedTerm}>
                <SelectTrigger data-testid="select-results-term">
                  <SelectValue placeholder="Select a term" />
                </SelectTrigger>
                <SelectContent>
                  {terms?.map((term) => (
                    <SelectItem key={term.id} value={term.id}>
                      {term.name} {term.isCurrent && "(Current)"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Class</label>
              <Select value={selectedClass} onValueChange={setSelectedClass}>
                <SelectTrigger data-testid="select-results-class">
                  <SelectValue placeholder="Select a class" />
                </SelectTrigger>
                <SelectContent>
                  {classes?.map((classItem) => (
                    <SelectItem key={classItem.id} value={classItem.id}>
                      {classItem.name} {classItem.section ? `(${classItem.section})` : ""}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {selectedTerm && selectedClass && (
        <>
          {resultsLoading ? (
            <Card data-testid="card-results-loading">
              <CardContent className="pt-6">
                <div className="space-y-2">
                  {[1, 2, 3, 4, 5].map((i) => (
                    <Skeleton key={i} className="h-12" data-testid={`skeleton-result-${i}`} />
                  ))}
                </div>
              </CardContent>
            </Card>
          ) : studentSummaries.length > 0 ? (
            <Card data-testid="card-class-results">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Users className="h-5 w-5" />
                  Class Results - {selectedClassData?.name} ({selectedTermData?.name})
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Table data-testid="table-class-results">
                  <TableHeader>
                    <TableRow>
                      <TableHead>Position</TableHead>
                      <TableHead>Student Name</TableHead>
                      <TableHead>Admission No.</TableHead>
                      <TableHead>Subjects</TableHead>
                      <TableHead>Total Score</TableHead>
                      <TableHead>Average</TableHead>
                      <TableHead>Grade</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {studentSummaries.map((summary) => (
                      <TableRow key={summary.studentId} data-testid={`row-result-${summary.studentId}`}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            {getPositionIcon(summary.position)}
                            <span className="font-bold">{summary.position}</span>
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">{summary.studentName}</TableCell>
                        <TableCell>{summary.admissionNumber}</TableCell>
                        <TableCell>{summary.subjectCount}</TableCell>
                        <TableCell>{summary.totalScore}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{summary.averageScore}%</Badge>
                        </TableCell>
                        <TableCell>
                          <span className={`font-bold ${getGradeColor(summary.overallGrade)}`}>
                            {summary.overallGrade}
                          </span>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          ) : (
            <Card data-testid="card-no-results">
              <CardContent className="py-12">
                <div className="text-center">
                  <Calculator className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="text-lg font-medium" data-testid="text-no-results-title">No Results Yet</h3>
                  <p className="text-muted-foreground mb-4" data-testid="text-no-results-description">
                    Enter grades for this class and term, then click "Calculate Results" to generate term results.
                  </p>
                  <Button onClick={() => calculateMutation.mutate()} disabled={calculateMutation.isPending} data-testid="button-calculate-results-empty">
                    <Calculator className="h-4 w-4 mr-2" />
                    Calculate Results Now
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          {classResults && classResults.length > 0 && (
            <Card data-testid="card-subject-results">
              <CardHeader>
                <CardTitle>Subject-wise Results</CardTitle>
              </CardHeader>
              <CardContent>
                <Table data-testid="table-subject-results">
                  <TableHeader>
                    <TableRow>
                      <TableHead>Student</TableHead>
                      <TableHead>Subject</TableHead>
                      <TableHead>Score</TableHead>
                      <TableHead>Grade</TableHead>
                      <TableHead>Position</TableHead>
                      <TableHead>Class Average</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {classResults.map((result) => (
                      <TableRow key={result.id} data-testid={`row-subject-result-${result.id}`}>
                        <TableCell className="font-medium">{getStudentName(result.studentId)}</TableCell>
                        <TableCell>{getSubjectName(result.subjectId)}</TableCell>
                        <TableCell>{result.totalScore}%</TableCell>
                        <TableCell>
                          <span className={`font-bold ${getGradeColor(result.grade || "F")}`}>
                            {result.grade || "-"}
                          </span>
                        </TableCell>
                        <TableCell>
                          {result.position ? (
                            <div className="flex items-center gap-1">
                              {getPositionIcon(result.position)}
                              <span>{result.position}</span>
                            </div>
                          ) : "-"}
                        </TableCell>
                        <TableCell>
                          {result.classAverage ? `${Math.round(result.classAverage)}%` : "-"}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {(!selectedTerm || !selectedClass) && (
        <Card data-testid="card-select-filters">
          <CardContent className="py-12">
            <div className="text-center">
              <TrendingUp className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium" data-testid="text-select-filters-title">Select Term and Class</h3>
              <p className="text-muted-foreground" data-testid="text-select-filters-description">Choose a term and class above to view term results.</p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/pages/school/parent-grades.ts.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  GraduationCap,
  TrendingUp,
  Calendar,
  BookOpen,
  Award,
  Trophy,
} from "lucide-react";
import type { AcademicTerm, TermResult } from "@shared/schema";

interface ChildInfo {
  id: string;
  firstName: string;
  lastName: string;
  admissionNumber: string;
  classId: string;
  className: string;
}

interface GradeSummary {
  subjectId: string;
  subjectName: string;
  averageScore: number;
  grade: string;
}

export default function ParentGradesPage() {
  const [selectedChild, setSelectedChild] = useState<string>("");
  const [selectedTerm, setSelectedTerm] = useState<string>("");

  const { data: children, isLoading: childrenLoading } = useQuery<ChildInfo[]>({
    queryKey: ["/api/school/parent/children"],
  });

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: gradesSummary, isLoading: gradesLoading } = useQuery<GradeSummary[]>({
    queryKey: [`/api/school/parent/children/${selectedChild}/grades`, { termId: selectedTerm }],
    enabled: !!selectedChild && !!selectedTerm,
  });

  const { data: termResults } = useQuery<TermResult[]>({
    queryKey: [`/api/school/students/${selectedChild}/results`, { termId: selectedTerm }],
    enabled: !!selectedChild && !!selectedTerm,
  });

  useEffect(() => {
    if (terms && terms.length > 0 && !selectedTerm) {
      const currentTerm = terms.find(t => t.isCurrent);
      if (currentTerm) {
        setSelectedTerm(currentTerm.id);
      }
    }
  }, [terms, selectedTerm]);

  useEffect(() => {
    if (children && children.length > 0 && !selectedChild) {
      setSelectedChild(children[0].id);
    }
  }, [children, selectedChild]);

  const selectedChildInfo = children?.find((c) => c.id === selectedChild);
  const selectedTermData = terms?.find(t => t.id === selectedTerm);

  const getGradeColor = (grade: string) => {
    switch (grade) {
      case "A": return "text-green-600 dark:text-green-400";
      case "B": return "text-blue-600 dark:text-blue-400";
      case "C": return "text-yellow-600 dark:text-yellow-400";
      case "D": return "text-orange-600 dark:text-orange-400";
      default: return "text-red-600 dark:text-red-400";
    }
  };

  const getGradeRemark = (grade: string) => {
    switch (grade) {
      case "A": return "Excellent";
      case "B": return "Very Good";
      case "C": return "Good";
      case "D": return "Fair";
      default: return "Needs Improvement";
    }
  };

  const calculateOverallStats = () => {
    if (!gradesSummary || gradesSummary.length === 0) return null;

    const totalScore = gradesSummary.reduce((sum, g) => sum + g.averageScore, 0);
    const averageScore = Math.round(totalScore / gradesSummary.length);

    let overallGrade = "F";
    if (averageScore >= 70) overallGrade = "A";
    else if (averageScore >= 60) overallGrade = "B";
    else if (averageScore >= 50) overallGrade = "C";
    else if (averageScore >= 40) overallGrade = "D";

    return {
      totalSubjects: gradesSummary.length,
      averageScore,
      overallGrade,
    };
  };

  const overallStats = calculateOverallStats();

  if (childrenLoading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-10 w-48" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-32" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">Academic Performance</h1>
          <p className="text-muted-foreground">View your child's grades and term results</p>
        </div>
        <div className="flex gap-3 flex-wrap">
          {children && children.length > 0 && (
            <Select value={selectedChild} onValueChange={setSelectedChild}>
              <SelectTrigger className="w-56" data-testid="select-parent-child">
                <SelectValue placeholder="Select your child" />
              </SelectTrigger>
              <SelectContent>
                {children.map((child) => (
                  <SelectItem key={child.id} value={child.id}>
                    {child.firstName} {child.lastName}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}
          <Select value={selectedTerm} onValueChange={setSelectedTerm}>
            <SelectTrigger className="w-48" data-testid="select-parent-term">
              <SelectValue placeholder="Select term" />
            </SelectTrigger>
            <SelectContent>
              {terms?.map((term) => (
                <SelectItem key={term.id} value={term.id}>
                  {term.name} {term.isCurrent && "(Current)"}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {!children || children.length === 0 ? (
        <Card data-testid="card-no-children">
          <CardContent className="py-12">
            <div className="text-center">
              <GraduationCap className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium" data-testid="text-no-children-title">No Children Linked</h3>
              <p className="text-muted-foreground" data-testid="text-no-children-description">
                Contact the school administration to link your child's account.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : !selectedChild ? (
        <Card data-testid="card-select-child">
          <CardContent className="py-12">
            <div className="text-center">
              <GraduationCap className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium" data-testid="text-select-child-title">Select a Child</h3>
              <p className="text-muted-foreground" data-testid="text-select-child-description">
                Choose your child from the dropdown above to view their grades.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <>
          {selectedChildInfo && (
            <Card className="bg-gradient-to-r from-blue-500 to-purple-600 text-white">
              <CardContent className="pt-6">
                <div className="flex items-center gap-4">
                  <div className="h-16 w-16 rounded-full bg-white/20 flex items-center justify-center">
                    <GraduationCap className="h-8 w-8" />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold">
                      {selectedChildInfo.firstName} {selectedChildInfo.lastName}
                    </h2>
                    <p className="opacity-90">
                      Class: {selectedChildInfo.className} | Admission No: {selectedChildInfo.admissionNumber}
                    </p>
                    <p className="opacity-80 text-sm mt-1">
                      <Calendar className="h-4 w-4 inline mr-1" />
                      {selectedTermData?.name}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {overallStats && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-muted-foreground">Subjects Taken</p>
                      <p className="text-2xl font-bold">{overallStats.totalSubjects}</p>
                    </div>
                    <BookOpen className="h-8 w-8 text-blue-600" />
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-muted-foreground">Overall Average</p>
                      <p className="text-2xl font-bold text-purple-600">{overallStats.averageScore}%</p>
                    </div>
                    <TrendingUp className="h-8 w-8 text-purple-600" />
                  </div>
                  <Progress value={overallStats.averageScore} className="mt-3" />
                </CardContent>
              </Card>

              <Card>
                <CardContent className="pt-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-muted-foreground">Overall Grade</p>
                      <p className={`text-2xl font-bold ${getGradeColor(overallStats.overallGrade)}`}>
                        {overallStats.overallGrade}
                      </p>
                    </div>
                    <Award className="h-8 w-8 text-yellow-500" />
                  </div>
                  <p className="text-sm text-muted-foreground mt-2">
                    {getGradeRemark(overallStats.overallGrade)}
                  </p>
                </CardContent>
              </Card>
            </div>
          )}

          {gradesLoading ? (
            <Card data-testid="card-grades-loading">
              <CardContent className="pt-6">
                <div className="space-y-4">
                  {[1, 2, 3, 4].map((i) => (
                    <Skeleton key={i} className="h-12" data-testid={`skeleton-grade-${i}`} />
                  ))}
                </div>
              </CardContent>
            </Card>
          ) : gradesSummary && gradesSummary.length > 0 ? (
            <Card data-testid="card-subject-performance">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <TrendingUp className="h-5 w-5" />
                  Subject Performance - {selectedTermData?.name}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Table data-testid="table-grades-summary">
                  <TableHeader>
                    <TableRow>
                      <TableHead>Subject</TableHead>
                      <TableHead>Score</TableHead>
                      <TableHead>Grade</TableHead>
                      <TableHead>Progress</TableHead>
                      <TableHead>Remark</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {gradesSummary.map((grade) => (
                      <TableRow key={grade.subjectId} data-testid={`row-grade-${grade.subjectId}`}>
                        <TableCell className="font-medium">
                          <div className="flex items-center gap-2">
                            <BookOpen className="h-4 w-4 text-muted-foreground" />
                            {grade.subjectName}
                          </div>
                        </TableCell>
                        <TableCell>{grade.averageScore}%</TableCell>
                        <TableCell>
                          <Badge className={getGradeColor(grade.grade)}>
                            {grade.grade}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <Progress value={grade.averageScore} className="w-24" />
                        </TableCell>
                        <TableCell className="text-muted-foreground">
                          {getGradeRemark(grade.grade)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          ) : (
            <Card data-testid="card-no-grades">
              <CardContent className="py-12">
                <div className="text-center">
                  <TrendingUp className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="text-lg font-medium" data-testid="text-no-grades-title">No Grades Available</h3>
                  <p className="text-muted-foreground" data-testid="text-no-grades-description">
                    No grades have been recorded for this term yet.
                  </p>
                </div>
              </CardContent>
            </Card>
          )}

          {termResults && termResults.length > 0 && (
            <Card data-testid="card-term-results">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Trophy className="h-5 w-5" />
                  Term Results & Positions
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Table data-testid="table-term-results">
                  <TableHeader>
                    <TableRow>
                      <TableHead>Subject</TableHead>
                      <TableHead>Total Score</TableHead>
                      <TableHead>Grade</TableHead>
                      <TableHead>Position</TableHead>
                      <TableHead>Class Average</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {termResults.map((result) => {
                      const subjectGrade = gradesSummary?.find(g => g.subjectId === result.subjectId);
                      return (
                        <TableRow key={result.id} data-testid={`row-result-${result.id}`}>
                          <TableCell className="font-medium">
                            {subjectGrade?.subjectName || "Subject"}
                          </TableCell>
                          <TableCell>{result.totalScore}%</TableCell>
                          <TableCell>
                            <Badge className={getGradeColor(result.grade || "F")}>
                              {result.grade || "-"}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            {result.position ? (
                              <div className="flex items-center gap-1">
                                {result.position <= 3 && (
                                  <Trophy className={`h-4 w-4 ${
                                    result.position === 1 ? "text-yellow-500" :
                                    result.position === 2 ? "text-gray-400" :
                                    "text-amber-600"
                                  }`} />
                                )}
                                <span className="font-medium">{result.position}</span>
                              </div>
                            ) : "-"}
                          </TableCell>
                          <TableCell>
                            {result.classAverage ? `${Math.round(result.classAverage)}%` : "-"}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardContent className="pt-6">
              <h4 className="font-semibold mb-3">Grading Scale</h4>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3 text-sm">
                <div className="flex items-center gap-2 p-2 bg-green-50 dark:bg-green-900/20 rounded-lg">
                  <span className="text-green-600 font-bold">A</span>
                  <span>70-100% (Excellent)</span>
                </div>
                <div className="flex items-center gap-2 p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                  <span className="text-blue-600 font-bold">B</span>
                  <span>60-69% (Very Good)</span>
                </div>
                <div className="flex items-center gap-2 p-2 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg">
                  <span className="text-yellow-600 font-bold">C</span>
                  <span>50-59% (Good)</span>
                </div>
                <div className="flex items-center gap-2 p-2 bg-orange-50 dark:bg-orange-900/20 rounded-lg">
                  <span className="text-orange-600 font-bold">D</span>
                  <span>40-49% (Fair)</span>
                </div>
                <div className="flex items-center gap-2 p-2 bg-red-50 dark:bg-red-900/20 rounded-lg">
                  <span className="text-red-600 font-bold">F</span>
                  <span>0-39% (Fail)</span>
                </div>
              </div>
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}

server/paystack.ts.content:
import { nanoid } from 'nanoid';

interface PaystackInitResponse {
  status: boolean;
  message: string;
  data: {
    authorization_url: string;
    access_code: string;
    reference: string;
  };
}

interface PaystackVerifyResponse {
  status: boolean;
  message: string;
  data: {
    id: number;
    status: string;
    reference: string;
    amount: number;
    gateway_response: string;
    paid_at: string;
    created_at: string;
    channel: string;
    currency: string;
    customer: {
      email: string;
      customer_code: string;
      first_name: string;
      last_name: string;
    };
    metadata: Record<string, any>;
  };
}

export interface PaystackPaymentData {
  email: string;
  amount: number;
  reference?: string;
  callback_url?: string;
  metadata?: {
    schoolId: string;
    studentId: string;
    feeTypeId: string;
    termId: string;
    paidById: string;
    expectedAmount?: number;
    custom_fields?: Array<{
      display_name: string;
      variable_name: string;
      value: string;
    }>;
  };
}

class PaystackService {
  private secretKey: string;
  private baseUrl = 'https://api.paystack.co';

  constructor() {
    this.secretKey = process.env.PAYSTACK_SECRET_KEY || '';
  }

  isConfigured(): boolean {
    return !!this.secretKey;
  }

  generateReference(): string {
    return `SD-${Date.now()}-${nanoid(8)}`;
  }

  async initializePayment(data: PaystackPaymentData): Promise<PaystackInitResponse> {
    if (!this.isConfigured()) {
      throw new Error('Paystack is not configured. Please add PAYSTACK_SECRET_KEY.');
    }

    const reference = data.reference || this.generateReference();

    const response = await fetch(`${this.baseUrl}/transaction/initialize`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email: data.email,
        amount: data.amount,
        reference,
        callback_url: data.callback_url,
        metadata: data.metadata,
      }),
    });

    const result = await response.json() as PaystackInitResponse;

    if (!response.ok || !result.status) {
      throw new Error(result.message || 'Failed to initialize payment');
    }

    return result;
  }

  async verifyPayment(reference: string): Promise<PaystackVerifyResponse> {
    if (!this.isConfigured()) {
      throw new Error('Paystack is not configured. Please add PAYSTACK_SECRET_KEY.');
    }

    const response = await fetch(`${this.baseUrl}/transaction/verify/${reference}`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Content-Type': 'application/json',
      },
    });

    const result = await response.json() as PaystackVerifyResponse;

    if (!response.ok) {
      throw new Error(result.message || 'Failed to verify payment');
    }

    return result;
  }

  validateWebhookSignature(signature: string, body: string): boolean {
    const crypto = require('crypto');
    const hash = crypto
      .createHmac('sha512', this.secretKey)
      .update(body)
      .digest('hex');
    return hash === signature;
  }
}

export const paystack = new PaystackService();

client/src/pages/school/parent-fees.tsx.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { 
  DollarSign, 
  CreditCard, 
  Receipt, 
  AlertCircle, 
  CheckCircle2, 
  Clock,
  ExternalLink,
  Loader2,
} from "lucide-react";
import type { FeeType, FeePayment, ClassFee, AcademicTerm } from "@shared/schema";

interface ChildInfo {
  id: string;
  firstName: string;
  lastName: string;
  admissionNumber: string;
  classId: string;
  className: string;
  email?: string;
}

interface OutstandingFee {
  feeType: FeeType;
  classFee: ClassFee;
  termId: string;
  amountDue: number;
  amountPaid: number;
  balance: number;
}

interface PaystackStatus {
  configured: boolean;
}

export default function ParentFeesPage() {
  const { toast } = useToast();
  const [selectedChild, setSelectedChild] = useState<string>("");
  const [activeTab, setActiveTab] = useState("outstanding");
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [selectedFee, setSelectedFee] = useState<OutstandingFee | null>(null);

  const { data: children, isLoading: childrenLoading } = useQuery<ChildInfo[]>({
    queryKey: ["/api/school/parent/children"],
  });

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: paystackStatus } = useQuery<PaystackStatus>({
    queryKey: ["/api/school/paystack/status"],
  });

  useEffect(() => {
    if (children && children.length > 0 && !selectedChild) {
      setSelectedChild(children[0].id);
    }
  }, [children, selectedChild]);

  const { data: outstandingFees, isLoading: feesLoading } = useQuery<OutstandingFee[]>({
    queryKey: [`/api/school/parent/children/${selectedChild}/outstanding-fees`],
    enabled: !!selectedChild,
  });

  const { data: payments, isLoading: paymentsLoading } = useQuery<FeePayment[]>({
    queryKey: [`/api/school/students/${selectedChild}/payments`],
    enabled: !!selectedChild,
  });

  const initializePaymentMutation = useMutation({
    mutationFn: async (data: { studentId: string; feeTypeId: string; termId: string; email: string }) => {
      return apiRequest("POST", "/api/school/paystack/initialize", data);
    },
    onSuccess: async (response) => {
      const data = await response.json();
      if (data.authorization_url) {
        window.location.href = data.authorization_url;
      }
    },
    onError: (error: Error) => {
      toast({
        title: "Payment Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const selectedChildInfo = children?.find((c) => c.id === selectedChild);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
    }).format(amount / 100);
  };

  const getTermName = (termId: string) => {
    const term = terms?.find(t => t.id === termId);
    return term?.name || termId;
  };

  const handlePayNow = (fee: OutstandingFee) => {
    setSelectedFee(fee);
    setPaymentDialogOpen(true);
  };

  const confirmPayment = () => {
    if (!selectedFee || !selectedChildInfo) return;

    const parentEmail = selectedChildInfo.email || `parent-${selectedChild}@school.com`;

    initializePaymentMutation.mutate({
      studentId: selectedChild,
      feeTypeId: selectedFee.feeType.id,
      termId: selectedFee.termId,
      email: parentEmail,
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "completed":
        return <Badge className="bg-green-600"><CheckCircle2 className="h-3 w-3 mr-1" /> Completed</Badge>;
      case "pending":
        return <Badge variant="outline"><Clock className="h-3 w-3 mr-1" /> Pending</Badge>;
      case "failed":
        return <Badge variant="destructive"><AlertCircle className="h-3 w-3 mr-1" /> Failed</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  const totalOutstanding = outstandingFees?.reduce((sum, f) => sum + f.balance, 0) || 0;
  const totalPaid = payments?.filter(p => p.status === "completed").reduce((sum, p) => sum + p.amount, 0) || 0;

  if (childrenLoading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-10 w-48" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-32" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">Fee Payments</h1>
          <p className="text-muted-foreground">View and pay your child's school fees</p>
        </div>
        {children && children.length > 0 && (
          <Select value={selectedChild} onValueChange={setSelectedChild}>
            <SelectTrigger className="w-56" data-testid="select-child">
              <SelectValue placeholder="Select your child" />
            </SelectTrigger>
            <SelectContent>
              {children.map((child) => (
                <SelectItem key={child.id} value={child.id}>
                  {child.firstName} {child.lastName}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      </div>

      {!children || children.length === 0 ? (
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <DollarSign className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No Children Linked</h3>
              <p className="text-muted-foreground">
                Contact the school administration to link your child's account.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : selectedChild ? (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card data-testid="card-outstanding-balance">
              <CardContent className="pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">Outstanding Balance</p>
                    <p className="text-2xl font-bold text-red-600" data-testid="text-outstanding-balance">
                      {formatCurrency(totalOutstanding)}
                    </p>
                  </div>
                  <AlertCircle className="h-8 w-8 text-red-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-total-paid">
              <CardContent className="pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">Total Paid</p>
                    <p className="text-2xl font-bold text-green-600" data-testid="text-total-paid">
                      {formatCurrency(totalPaid)}
                    </p>
                  </div>
                  <CheckCircle2 className="h-8 w-8 text-green-600" />
                </div>
              </CardContent>
            </Card>

            <Card data-testid="card-payment-method">
              <CardContent className="pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">Payment Method</p>
                    <p className="text-lg font-medium" data-testid="text-payment-method">
                      {paystackStatus?.configured ? "Online Payment" : "Bank Transfer"}
                    </p>
                  </div>
                  <CreditCard className="h-8 w-8 text-blue-600" />
                </div>
              </CardContent>
            </Card>
          </div>

          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList>
              <TabsTrigger value="outstanding" data-testid="tab-outstanding">
                Outstanding Fees {outstandingFees && outstandingFees.length > 0 && (
                  <Badge variant="destructive" className="ml-2">{outstandingFees.length}</Badge>
                )}
              </TabsTrigger>
              <TabsTrigger value="history" data-testid="tab-history">Payment History</TabsTrigger>
            </TabsList>

            <TabsContent value="outstanding" className="mt-4">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <AlertCircle className="h-5 w-5 text-red-600" />
                    Outstanding Fees
                  </CardTitle>
                  <CardDescription>
                    Fees that are due for payment
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {feesLoading ? (
                    <Skeleton className="h-48" />
                  ) : outstandingFees && outstandingFees.length > 0 ? (
                    <div className="space-y-4">
                      {outstandingFees.map((fee, index) => (
                        <Card key={`${fee.feeType.id}-${fee.termId}`} data-testid={`card-fee-${index}`}>
                          <CardContent className="pt-6">
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                              <div className="space-y-1">
                                <h3 className="font-semibold text-lg">{fee.feeType.name}</h3>
                                <p className="text-sm text-muted-foreground">
                                  {getTermName(fee.termId)} | {fee.feeType.description || "School fee"}
                                </p>
                                <div className="flex gap-4 text-sm">
                                  <span>Amount Due: <strong>{formatCurrency(fee.amountDue)}</strong></span>
                                  <span>Paid: <strong className="text-green-600">{formatCurrency(fee.amountPaid)}</strong></span>
                                  <span>Balance: <strong className="text-red-600">{formatCurrency(fee.balance)}</strong></span>
                                </div>
                              </div>
                              {paystackStatus?.configured && (
                                <Button 
                                  onClick={() => handlePayNow(fee)}
                                  data-testid={`button-pay-${index}`}
                                >
                                  <CreditCard className="h-4 w-4 mr-2" />
                                  Pay Now
                                </Button>
                              )}
                            </div>
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-12">
                      <CheckCircle2 className="h-12 w-12 mx-auto text-green-600 mb-4" />
                      <h3 className="text-lg font-medium">All Caught Up</h3>
                      <p className="text-muted-foreground">
                        No outstanding fees at the moment.
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="history" className="mt-4">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Receipt className="h-5 w-5" />
                    Payment History
                  </CardTitle>
                  <CardDescription>
                    All payment transactions for this child
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {paymentsLoading ? (
                    <Skeleton className="h-48" />
                  ) : payments && payments.length > 0 ? (
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Receipt #</TableHead>
                          <TableHead>Date</TableHead>
                          <TableHead>Amount</TableHead>
                          <TableHead>Method</TableHead>
                          <TableHead>Status</TableHead>
                          <TableHead className="text-right">Actions</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {payments.map((payment) => (
                          <TableRow key={payment.id} data-testid={`row-payment-${payment.id}`}>
                            <TableCell className="font-mono">
                              {payment.receiptNumber || payment.id.slice(0, 8)}
                            </TableCell>
                            <TableCell>
                              {new Date(payment.createdAt!).toLocaleDateString()}
                            </TableCell>
                            <TableCell className="font-medium">
                              {formatCurrency(payment.amount)}
                            </TableCell>
                            <TableCell className="capitalize">
                              {payment.paymentMethod.replace("_", " ")}
                            </TableCell>
                            <TableCell>
                              {getStatusBadge(payment.status)}
                            </TableCell>
                            <TableCell className="text-right">
                              {payment.status === "completed" && (
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() => window.open(`/school/receipt/${payment.id}`, '_blank')}
                                  data-testid={`button-receipt-${payment.id}`}
                                >
                                  <Receipt className="h-4 w-4 mr-1" />
                                  Receipt
                                </Button>
                              )}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  ) : (
                    <div className="text-center py-12">
                      <Receipt className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                      <h3 className="text-lg font-medium">No Payment History</h3>
                      <p className="text-muted-foreground">
                        No payments have been recorded yet.
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </>
      ) : null}

      <Dialog open={paymentDialogOpen} onOpenChange={setPaymentDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Payment</DialogTitle>
            <DialogDescription>
              You are about to pay for the following fee
            </DialogDescription>
          </DialogHeader>
          {selectedFee && (
            <div className="space-y-4 py-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">Fee Type</p>
                  <p className="font-medium">{selectedFee.feeType.name}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Term</p>
                  <p className="font-medium">{getTermName(selectedFee.termId)}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Student</p>
                  <p className="font-medium">
                    {selectedChildInfo?.firstName} {selectedChildInfo?.lastName}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Amount to Pay</p>
                  <p className="text-xl font-bold text-green-600">
                    {formatCurrency(selectedFee.balance)}
                  </p>
                </div>
              </div>
              <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                <p className="text-sm text-blue-700 dark:text-blue-300 flex items-center gap-2">
                  <ExternalLink className="h-4 w-4" />
                  You will be redirected to Paystack to complete the payment securely.
                </p>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setPaymentDialogOpen(false)}
              disabled={initializePaymentMutation.isPending}
            >
              Cancel
            </Button>
            <Button
              onClick={confirmPayment}
              disabled={initializePaymentMutation.isPending}
              data-testid="button-confirm-payment"
            >
              {initializePaymentMutation.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Processing...
                </>
              ) : (
                <>
                  <CreditCard className="h-4 w-4 mr-2" />
                  Proceed to Payment
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/pages/school/payment-receipt..content:
import { useRoute, useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import { 
  Printer, 
  Download, 
  ArrowLeft, 
  CheckCircle2,
  Building,
  User,
  Calendar,
  Hash,
} from "lucide-react";
import type { FeePayment, FeeType, SchoolUser, School } from "@shared/schema";

interface PaymentDetails extends FeePayment {
  student?: SchoolUser;
  feeType?: FeeType;
  school?: School;
}

export default function PaymentReceiptPage() {
  const [match, params] = useRoute("/school/receipt/:id");
  const [, setLocation] = useLocation();
  const paymentId = params?.id;

  const { data: payment, isLoading, error } = useQuery<PaymentDetails>({
    queryKey: [`/api/school/payments/${paymentId}`],
    enabled: !!paymentId,
  });

  const { data: school } = useQuery<School>({
    queryKey: ["/api/school/current"],
    enabled: !!payment,
  });

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
    }).format(amount / 100);
  };

  const formatDate = (date: string | Date | null) => {
    if (!date) return "N/A";
    return new Date(date).toLocaleDateString("en-NG", {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const handlePrint = () => {
    window.print();
  };

  if (!match) {
    return null;
  }

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Skeleton className="w-full max-w-2xl h-[600px]" />
      </div>
    );
  }

  if (error || !payment) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <div className="text-center">
              <h2 className="text-xl font-bold mb-2">Receipt Not Found</h2>
              <p className="text-muted-foreground mb-6">
                The payment receipt could not be found.
              </p>
              <Button onClick={() => setLocation("/school/parent/fees")}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Fees
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen p-6 bg-muted/30">
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center justify-between gap-4 mb-6 print:hidden">
          <Button variant="ghost" onClick={() => setLocation("/school/parent/fees")}>
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back to Fees
          </Button>
          <div className="flex gap-2">
            <Button variant="outline" onClick={handlePrint} data-testid="button-print">
              <Printer className="h-4 w-4 mr-2" />
              Print
            </Button>
          </div>
        </div>

        <Card className="print:shadow-none print:border-none" data-testid="card-receipt">
          <CardHeader className="text-center border-b pb-6">
            <div className="flex justify-center mb-4">
              <div className="h-16 w-16 rounded-full bg-green-100 flex items-center justify-center">
                <CheckCircle2 className="h-8 w-8 text-green-600" />
              </div>
            </div>
            <CardTitle className="text-2xl">Payment Receipt</CardTitle>
            <p className="text-muted-foreground mt-2">
              {school?.name || "StudentDrive School"}
            </p>
          </CardHeader>
          <CardContent className="pt-6 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="flex items-center gap-2">
                <Hash className="h-4 w-4 text-muted-foreground" />
                <div>
                  <p className="text-sm text-muted-foreground">Receipt Number</p>
                  <p className="font-mono font-medium" data-testid="text-receipt-number">
                    {payment.receiptNumber || payment.id.slice(0, 12)}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                <div>
                  <p className="text-sm text-muted-foreground">Date</p>
                  <p className="font-medium" data-testid="text-payment-date">
                    {formatDate(payment.paidAt || payment.createdAt)}
                  </p>
                </div>
              </div>
            </div>

            <Separator />

            <div className="space-y-4">
              <h3 className="font-semibold flex items-center gap-2">
                <User className="h-4 w-4" />
                Student Information
              </h3>
              <div className="grid grid-cols-2 gap-4 pl-6">
                <div>
                  <p className="text-sm text-muted-foreground">Student Name</p>
                  <p className="font-medium" data-testid="text-student-name">
                    {payment.student 
                      ? `${payment.student.firstName} ${payment.student.lastName}`
                      : "N/A"
                    }
                  </p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Admission Number</p>
                  <p className="font-medium" data-testid="text-admission-number">
                    {payment.student?.admissionNumber || "N/A"}
                  </p>
                </div>
              </div>
            </div>

            <Separator />

            <div className="space-y-4">
              <h3 className="font-semibold">Payment Details</h3>
              <div className="bg-muted/50 rounded-lg p-4">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-muted-foreground">Fee Type</span>
                  <span className="font-medium" data-testid="text-fee-type">
                    {payment.feeType?.name || "School Fee"}
                  </span>
                </div>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-muted-foreground">Payment Method</span>
                  <span className="font-medium capitalize" data-testid="text-payment-method">
                    {payment.paymentMethod.replace("_", " ")}
                  </span>
                </div>
                {payment.paymentReference && (
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-muted-foreground">Reference</span>
                    <span className="font-mono text-sm" data-testid="text-reference">
                      {payment.paymentReference}
                    </span>
                  </div>
                )}
                <Separator className="my-3" />
                <div className="flex justify-between items-center">
                  <span className="font-semibold">Amount Paid</span>
                  <span className="text-2xl font-bold text-green-600" data-testid="text-amount">
                    {formatCurrency(payment.amount)}
                  </span>
                </div>
              </div>
            </div>

            <div className="pt-4 text-center text-sm text-muted-foreground print:pt-8">
              <p>Thank you for your payment.</p>
              <p className="mt-1">This is a computer-generated receipt and does not require a signature.</p>
            </div>
          </CardContent>
        </Card>

        <style>{`
          @media print {
            body * {
              visibility: hidden;
            }
            [data-testid="card-receipt"],
            [data-testid="card-receipt"] * {
              visibility: visible;
            }
            [data-testid="card-receipt"] {
              position: absolute;
              left: 0;
              top: 0;
              width: 100%;
            }
          }
        `}</style>
      </div>
    </div>
  );
}

client/src/pages/school/payment-callback.content:
import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { CheckCircle2, XCircle, Loader2, Receipt, ArrowLeft } from "lucide-react";

interface VerifyResponse {
  status: "success" | "failed";
  message: string;
  payment?: {
    id: string;
    amount: number;
    receiptNumber: string;
    status: string;
  };
}

export default function PaymentCallbackPage() {
  const [, setLocation] = useLocation();
  const [reference, setReference] = useState<string | null>(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const ref = params.get("reference");
    setReference(ref);
  }, []);

  const { data, isLoading, error } = useQuery<VerifyResponse>({
    queryKey: [`/api/school/paystack/verify/${reference}`],
    enabled: !!reference,
    retry: false,
  });

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
    }).format(amount / 100);
  };

  if (!reference) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <div className="text-center">
              <XCircle className="h-16 w-16 mx-auto text-red-600 mb-4" />
              <h2 className="text-xl font-bold mb-2">Invalid Payment Reference</h2>
              <p className="text-muted-foreground mb-6">
                No payment reference was provided. Please try again.
              </p>
              <Button onClick={() => setLocation("/school/parent/fees")}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Fees
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <div className="text-center">
              <Loader2 className="h-16 w-16 mx-auto text-blue-600 mb-4 animate-spin" />
              <h2 className="text-xl font-bold mb-2">Verifying Payment</h2>
              <p className="text-muted-foreground">
                Please wait while we verify your payment...
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <div className="text-center">
              <XCircle className="h-16 w-16 mx-auto text-red-600 mb-4" />
              <h2 className="text-xl font-bold mb-2">Verification Failed</h2>
              <p className="text-muted-foreground mb-6">
                {(error as Error)?.message || "Unable to verify payment. Please contact support."}
              </p>
              <Button onClick={() => setLocation("/school/parent/fees")}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Fees
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (data.status === "success") {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <Card className="w-full max-w-md">
          <CardHeader>
            <div className="text-center">
              <CheckCircle2 className="h-16 w-16 mx-auto text-green-600 mb-4" />
              <CardTitle className="text-2xl">Payment Successful</CardTitle>
              <CardDescription>
                Your payment has been processed successfully
              </CardDescription>
            </div>
          </CardHeader>
          <CardContent>
            {data.payment && (
              <div className="space-y-4 p-4 bg-green-50 dark:bg-green-900/20 rounded-lg mb-6">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Receipt Number</span>
                  <span className="font-mono font-medium">{data.payment.receiptNumber}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Amount Paid</span>
                  <span className="font-bold text-green-600">
                    {formatCurrency(data.payment.amount)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Reference</span>
                  <span className="font-mono text-sm">{reference}</span>
                </div>
              </div>
            )}
            <div className="flex flex-col gap-3">
              {data.payment && (
                <Button
                  variant="outline"
                  onClick={() => window.open(`/school/receipt/${data.payment!.id}`, '_blank')}
                  data-testid="button-view-receipt"
                >
                  <Receipt className="h-4 w-4 mr-2" />
                  View Receipt
                </Button>
              )}
              <Button onClick={() => setLocation("/school/parent/fees")} data-testid="button-back-fees">
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Fees
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center p-6">
      <Card className="w-full max-w-md">
        <CardContent className="pt-6">
          <div className="text-center">
            <XCircle className="h-16 w-16 mx-auto text-red-600 mb-4" />
            <h2 className="text-xl font-bold mb-2">Payment Failed</h2>
            <p className="text-muted-foreground mb-6">
              {data.message || "Your payment could not be completed. Please try again."}
            </p>
            <Button onClick={() => setLocation("/school/parent/fees")}>
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Fees
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/school/student-timetabl.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useState, useEffect } from "react";
import { Clock, Calendar, MapPin, User, BookOpen } from "lucide-react";
import type { TimetablePeriod, TimetableEntry, AcademicTerm, SchoolSubject, SchoolUser } from "@shared/schema";

interface CurrentUser {
  user: {
    id: string;
    firstName: string;
    lastName: string;
    role: string;
    classId?: string;
  };
  school: {
    id: string;
    name: string;
  };
}

interface ClassInfo {
  id: string;
  name: string;
  section?: string;
}

const DAYS_OF_WEEK = [
  { value: 1, label: "Monday" },
  { value: 2, label: "Tuesday" },
  { value: 3, label: "Wednesday" },
  { value: 4, label: "Thursday" },
  { value: 5, label: "Friday" },
];

export default function StudentTimetablePage() {
  const [selectedTerm, setSelectedTerm] = useState<string>("");

  const { data: currentUser, isLoading: userLoading } = useQuery<CurrentUser>({
    queryKey: ["/api/school/auth/me"],
  });

  const { data: terms } = useQuery<AcademicTerm[]>({
    queryKey: ["/api/school/terms"],
  });

  const { data: periods } = useQuery<TimetablePeriod[]>({
    queryKey: ["/api/school/timetable-periods"],
  });

  const { data: subjects } = useQuery<SchoolSubject[]>({
    queryKey: ["/api/school/subjects"],
  });

  const { data: teachers } = useQuery<SchoolUser[]>({
    queryKey: ["/api/school/users", { role: "teacher" }],
  });

  const { data: classInfo } = useQuery<ClassInfo>({
    queryKey: [`/api/school/classes/${currentUser?.user?.classId}`],
    enabled: !!currentUser?.user?.classId,
  });

  const classId = currentUser?.user?.classId;

  const { data: entries, isLoading: entriesLoading } = useQuery<TimetableEntry[]>({
    queryKey: ["/api/school/classes", classId, "timetable", selectedTerm],
    queryFn: async () => {
      const url = selectedTerm 
        ? `/api/school/classes/${classId}/timetable?termId=${selectedTerm}`
        : `/api/school/classes/${classId}/timetable`;
      const response = await fetch(url, { credentials: 'include' });
      if (!response.ok) throw new Error("Failed to fetch timetable");
      return response.json();
    },
    enabled: !!classId && !!selectedTerm,
  });

  useEffect(() => {
    if (terms && terms.length > 0 && !selectedTerm) {
      const currentTerm = terms.find(t => t.isCurrent);
      if (currentTerm) {
        setSelectedTerm(currentTerm.id);
      } else if (terms[0]) {
        setSelectedTerm(terms[0].id);
      }
    }
  }, [terms, selectedTerm]);

  const getEntriesForDayAndPeriod = (day: number, periodId: string) => {
    return entries?.find((e) => e.dayOfWeek === day && e.periodId === periodId);
  };

  const getSubjectName = (id: string) => subjects?.find((s) => s.id === id)?.name || "";

  const getTeacherName = (id: string) => {
    const teacher = teachers?.find((t) => t.id === id);
    return teacher ? `${teacher.firstName} ${teacher.lastName}` : "";
  };

  const sortedPeriods = periods?.slice().sort((a, b) => a.orderIndex - b.orderIndex);

  const selectedTermData = terms?.find(t => t.id === selectedTerm);

  const totalPeriods = entries?.length || 0;
  const uniqueSubjects = new Set(entries?.map(e => e.subjectId)).size;

  if (userLoading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-10 w-64" />
        <Skeleton className="h-96" />
      </div>
    );
  }

  if (currentUser?.user?.role !== "student") {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">Access Denied</h3>
              <p className="text-muted-foreground">This page is only available for students.</p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!classId) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No Class Assigned</h3>
              <p className="text-muted-foreground">
                You haven't been assigned to a class yet. Please contact the administrator.
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-page-title">My Timetable</h1>
          <p className="text-muted-foreground">
            Class schedule for {currentUser?.user?.firstName} {currentUser?.user?.lastName}
            {classInfo && ` - ${classInfo.name}${classInfo.section ? ` (${classInfo.section})` : ""}`}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Select value={selectedTerm} onValueChange={setSelectedTerm}>
            <SelectTrigger className="w-48" data-testid="select-timetable-term">
              <SelectValue placeholder="Select term" />
            </SelectTrigger>
            <SelectContent>
              {terms?.map((term) => (
                <SelectItem key={term.id} value={term.id}>
                  {term.name} {term.isCurrent && "(Current)"}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-100 dark:bg-blue-900 rounded-lg">
                <Clock className="h-5 w-5 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Weekly Periods</p>
                <p className="text-2xl font-bold" data-testid="text-total-periods">{totalPeriods}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-purple-100 dark:bg-purple-900 rounded-lg">
                <BookOpen className="h-5 w-5 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Subjects</p>
                <p className="text-2xl font-bold" data-testid="text-unique-subjects">{uniqueSubjects}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calendar className="h-5 w-5" />
            Weekly Timetable
            {classInfo && (
              <Badge variant="outline" className="ml-2">
                {classInfo.name}{classInfo.section ? ` (${classInfo.section})` : ""}
              </Badge>
            )}
            {selectedTermData && (
              <Badge variant="secondary" className="ml-2">
                {selectedTermData.name}
              </Badge>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {entriesLoading ? (
            <Skeleton className="h-96" />
          ) : !periods || periods.length === 0 ? (
            <div className="text-center py-12">
              <Clock className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No Periods Configured</h3>
              <p className="text-muted-foreground">
                The school hasn't configured timetable periods yet.
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr>
                    <th className="border p-2 bg-muted text-left min-w-[100px]">Period</th>
                    {DAYS_OF_WEEK.map((day) => (
                      <th key={day.value} className="border p-2 bg-muted text-center min-w-[150px]">
                        {day.label}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {sortedPeriods?.map((period) => (
                    <tr key={period.id}>
                      <td className="border p-2 bg-muted/50">
                        <div className="font-medium">{period.name}</div>
                        <div className="text-xs text-muted-foreground">
                          {period.startTime} - {period.endTime}
                        </div>
                        {period.isBreak && (
                          <Badge variant="secondary" className="mt-1 text-xs">Break</Badge>
                        )}
                      </td>
                      {DAYS_OF_WEEK.map((day) => {
                        const entry = getEntriesForDayAndPeriod(day.value, period.id);
                        return (
                          <td key={day.value} className="border p-2" data-testid={`cell-${day.value}-${period.id}`}>
                            {period.isBreak ? (
                              <div className="text-center text-muted-foreground italic">
                                Break
                              </div>
                            ) : entry ? (
                              <div className="space-y-1">
                                <div className="font-medium text-sm text-primary">
                                  {getSubjectName(entry.subjectId || "")}
                                </div>
                                <div className="text-xs text-muted-foreground flex items-center gap-1">
                                  <User className="h-3 w-3" />
                                  {getTeacherName(entry.teacherId || "")}
                                </div>
                                {entry.room && (
                                  <div className="text-xs text-muted-foreground flex items-center gap-1">
                                    <MapPin className="h-3 w-3" />
                                    {entry.room}
                                  </div>
                                )}
                              </div>
                            ) : (
                              <div className="text-center text-muted-foreground text-sm">
                                -
                              </div>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {entries && entries.length === 0 && !entriesLoading && (
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium">No Timetable Available</h3>
              <p className="text-muted-foreground">
                Your class timetable hasn't been set up yet for this term.
              </p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

