client/src/components/quick-actions.tsx.content:
import { Link } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { LucideIcon, Zap } from "lucide-react";

interface QuickAction {
  label: string;
  icon: LucideIcon;
  href: string;
  color?: string;
  description?: string;
}

interface QuickActionsProps {
  actions: QuickAction[];
  title?: string;
  columns?: 2 | 3 | 4;
  variant?: "card" | "inline";
}

export function QuickActions({ 
  actions, 
  title = "Quick Actions", 
  columns = 4,
  variant = "card"
}: QuickActionsProps) {
  const gridCols = {
    2: "grid-cols-2",
    3: "grid-cols-2 md:grid-cols-3",
    4: "grid-cols-2 md:grid-cols-4",
  };

  const ActionButtons = () => (
    <div className={`grid ${gridCols[columns]} gap-3`}>
      {actions.map((action) => (
        <Link key={action.label} href={action.href}>
          <Button
            variant="outline"
            className="w-full h-auto min-h-[4.5rem] flex flex-col items-center justify-center gap-2 p-3"
            data-testid={`button-quick-${action.label.toLowerCase().replace(/\s+/g, '-')}`}
          >
            <div className={`p-2 rounded-full ${action.color || 'bg-primary'}`}>
              <action.icon className="h-4 w-4 text-white" />
            </div>
            <span className="text-xs font-medium text-center leading-tight">{action.label}</span>
          </Button>
        </Link>
      ))}
    </div>
  );

  if (variant === "inline") {
    return <ActionButtons />;
  }

  return (
    <Card data-testid="card-quick-actions">
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-lg">
          <Zap className="h-5 w-5" />
          {title}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <ActionButtons />
      </CardContent>
    </Card>
  );
}

export function QuickActionButton({ 
  action 
}: { 
  action: QuickAction 
}) {
  return (
    <Link href={action.href}>
      <Button
        variant="outline"
        size="sm"
        className="flex items-center gap-2"
        data-testid={`button-quick-${action.label.toLowerCase().replace(/\s+/g, '-')}`}
      >
        <action.icon className="h-4 w-4" />
        <span>{action.label}</span>
      </Button>
    </Link>
  );
}

client/src/pages/school/analytics.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PageHeader } from "@/components/page-header";
import {
  Users,
  GraduationCap,
  BookOpen,
  DollarSign,
  TrendingUp,
  TrendingDown,
  UserCheck,
  Calendar,
  BarChart3,
  PieChart,
} from "lucide-react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  LineChart,
  Line,
  PieChart as RechartsPieChart,
  Pie,
  Cell,
  Legend,
  Area,
  AreaChart,
} from "recharts";
import { useState } from "react";

interface AnalyticsData {
  overview: {
    totalStudents: number;
    totalTeachers: number;
    totalParents: number;
    totalClasses: number;
    activeTerms: number;
    totalSubjects: number;
  };
  attendance: {
    averageRate: number;
    presentToday: number;
    absentToday: number;
    lateToday: number;
    monthlyTrend: Array<{ month: string; rate: number }>;
  };
  grades: {
    averageScore: number;
    passRate: number;
    subjectPerformance: Array<{ subject: string; average: number }>;
    gradeDistribution: Array<{ grade: string; count: number }>;
  };
  fees: {
    totalDue: number;
    totalCollected: number;
    collectionRate: number;
    pendingPayments: number;
    monthlyCollections: Array<{ month: string; amount: number }>;
  };
  enrollment: {
    classSizes: Array<{ class: string; count: number }>;
    genderDistribution: Array<{ gender: string; count: number }>;
  };
}

const COLORS = ['#3b82f6', '#22c55e', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4'];

function MetricCard({
  title,
  value,
  subtitle,
  icon: Icon,
  trend,
  trendValue,
}: {
  title: string;
  value: string | number;
  subtitle?: string;
  icon: any;
  trend?: 'up' | 'down' | 'neutral';
  trendValue?: string;
}) {
  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">{title}</CardTitle>
        <Icon className="h-4 w-4 text-muted-foreground" />
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold">{value}</div>
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          {subtitle && <span>{subtitle}</span>}
          {trend && trendValue && (
            <Badge
              variant={trend === 'up' ? 'default' : trend === 'down' ? 'destructive' : 'secondary'}
              className="text-xs"
            >
              {trend === 'up' ? <TrendingUp className="h-3 w-3 mr-1" /> : <TrendingDown className="h-3 w-3 mr-1" />}
              {trendValue}
            </Badge>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

export default function AnalyticsDashboard() {
  const [selectedPeriod, setSelectedPeriod] = useState("current_term");

  const { data: analytics, isLoading } = useQuery<AnalyticsData>({
    queryKey: ["/api/school/analytics", selectedPeriod],
    queryFn: async () => {
      const response = await fetch(`/api/school/analytics?period=${encodeURIComponent(selectedPeriod)}`);
      if (!response.ok) {
        throw new Error("Failed to fetch analytics");
      }
      return response.json();
    },
  });

  const handlePeriodChange = (newPeriod: string) => {
    setSelectedPeriod(newPeriod);
  };

  const { data: terms } = useQuery<Array<{ id: string; name: string }>>({
    queryKey: ["/api/school/terms"],
  });

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 0,
    }).format(amount / 100);
  };

  if (isLoading) {
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <PageHeader
          title="Analytics Dashboard"
          description="School performance metrics and insights"
        />
        <div className="flex-1 overflow-auto p-6">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            {[1, 2, 3, 4].map((i) => (
              <Skeleton key={i} className="h-32" />
            ))}
          </div>
        </div>
      </div>
    );
  }

  const overview = analytics?.overview || {
    totalStudents: 0,
    totalTeachers: 0,
    totalParents: 0,
    totalClasses: 0,
    activeTerms: 0,
    totalSubjects: 0,
  };

  const attendance = analytics?.attendance || {
    averageRate: 0,
    presentToday: 0,
    absentToday: 0,
    lateToday: 0,
    monthlyTrend: [],
  };

  const grades = analytics?.grades || {
    averageScore: 0,
    passRate: 0,
    subjectPerformance: [],
    gradeDistribution: [],
  };

  const fees = analytics?.fees || {
    totalDue: 0,
    totalCollected: 0,
    collectionRate: 0,
    pendingPayments: 0,
    monthlyCollections: [],
  };

  const enrollment = analytics?.enrollment || {
    classSizes: [],
    genderDistribution: [],
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader
        title="Analytics Dashboard"
        description="School performance metrics and insights"
      />

      <div className="flex-1 overflow-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <Tabs defaultValue="overview" className="w-full">
            <div className="flex items-center justify-between flex-wrap gap-4">
              <TabsList data-testid="analytics-tabs">
                <TabsTrigger value="overview" data-testid="tab-overview">Overview</TabsTrigger>
                <TabsTrigger value="attendance" data-testid="tab-attendance">Attendance</TabsTrigger>
                <TabsTrigger value="grades" data-testid="tab-grades">Grades</TabsTrigger>
                <TabsTrigger value="fees" data-testid="tab-fees">Fees</TabsTrigger>
                <TabsTrigger value="enrollment" data-testid="tab-enrollment">Enrollment</TabsTrigger>
              </TabsList>

              <Select value={selectedPeriod} onValueChange={handlePeriodChange}>
                <SelectTrigger className="w-[180px]" data-testid="select-period">
                  <SelectValue placeholder="Select period" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="current_term">Current Term</SelectItem>
                  <SelectItem value="last_term">Last Term</SelectItem>
                  <SelectItem value="current_year">Current Year</SelectItem>
                  <SelectItem value="all_time">All Time</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <TabsContent value="overview" className="space-y-6 mt-6">
              <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                <MetricCard
                  title="Total Students"
                  value={overview.totalStudents}
                  subtitle="Enrolled students"
                  icon={GraduationCap}
                  trend="up"
                  trendValue="+12%"
                />
                <MetricCard
                  title="Total Teachers"
                  value={overview.totalTeachers}
                  subtitle="Active staff"
                  icon={Users}
                />
                <MetricCard
                  title="Classes"
                  value={overview.totalClasses}
                  subtitle={`${overview.totalSubjects} subjects`}
                  icon={BookOpen}
                />
                <MetricCard
                  title="Fee Collection"
                  value={`${fees.collectionRate}%`}
                  subtitle="Collection rate"
                  icon={DollarSign}
                  trend={fees.collectionRate >= 80 ? 'up' : 'down'}
                  trendValue={`${fees.pendingPayments} pending`}
                />
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <BarChart3 className="h-5 w-5" />
                      Attendance Overview
                    </CardTitle>
                    <CardDescription>Today's attendance summary</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-3 gap-4 text-center">
                      <div>
                        <div className="text-2xl font-bold text-green-600">{attendance.presentToday}</div>
                        <div className="text-sm text-muted-foreground">Present</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-red-600">{attendance.absentToday}</div>
                        <div className="text-sm text-muted-foreground">Absent</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-yellow-600">{attendance.lateToday}</div>
                        <div className="text-sm text-muted-foreground">Late</div>
                      </div>
                    </div>
                    <div className="mt-4 text-center">
                      <div className="text-3xl font-bold">{attendance.averageRate}%</div>
                      <div className="text-sm text-muted-foreground">Average Attendance Rate</div>
                    </div>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <TrendingUp className="h-5 w-5" />
                      Academic Performance
                    </CardTitle>
                    <CardDescription>Grade averages and pass rates</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-2 gap-4 text-center">
                      <div>
                        <div className="text-2xl font-bold">{grades.averageScore}%</div>
                        <div className="text-sm text-muted-foreground">Average Score</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-green-600">{grades.passRate}%</div>
                        <div className="text-sm text-muted-foreground">Pass Rate</div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </div>

              <Card>
                <CardHeader>
                  <CardTitle>Fee Collection Trend</CardTitle>
                  <CardDescription>Monthly fee collection overview</CardDescription>
                </CardHeader>
                <CardContent className="h-[300px]">
                  {fees.monthlyCollections.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={fees.monthlyCollections}>
                        <defs>
                          <linearGradient id="colorAmount" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
