          {isLoading ? (
            <div className="space-y-4">
              {[1, 2, 3, 4, 5].map((i) => (
                <div key={i} className="flex items-center gap-4">
                  <Skeleton className="h-12 w-12 rounded-md" />
                  <div className="flex-1 space-y-2">
                    <Skeleton className="h-4 w-48" />
                    <Skeleton className="h-3 w-32" />
                  </div>
                  <Skeleton className="h-6 w-20" />
                </div>
              ))}
            </div>
          ) : filteredSchools.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <School className="h-12 w-12 mx-auto mb-4 opacity-20" />
              <p>No schools found</p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>School</TableHead>
                  <TableHead>Subdomain</TableHead>
                  <TableHead>Subscription</TableHead>
                  <TableHead>Users</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="w-[80px]">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredSchools.map((school) => (
                  <TableRow key={school.id} data-testid={`row-school-${school.id}`}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar className="h-10 w-10 rounded-md">
                          <AvatarImage src={school.logoUrl || undefined} />
                          <AvatarFallback className="rounded-md bg-primary/10">
                            {school.name[0].toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <p className="font-medium">{school.name}</p>
                          <p className="text-sm text-muted-foreground">{school.email}</p>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <code className="text-xs bg-muted px-2 py-1 rounded">
                          {school.subdomain}
                        </code>
                        <Button 
                          variant="ghost" 
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => window.open(`https://${school.subdomain}.studentdrive.com`, '_blank')}
                        >
                          <ExternalLink className="h-3 w-3" />
                        </Button>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="space-y-1">
                        {getSubscriptionBadge(school.subscriptionStatus)}
                        {school.subscriptionPlanName && (
                          <p className="text-xs text-muted-foreground">
                            {school.subscriptionPlanName}
                          </p>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-3 text-sm text-muted-foreground">
                        <span className="flex items-center gap-1">
                          <GraduationCap className="h-3 w-3" />
                          {school.studentsCount || 0}
                        </span>
                        <span className="flex items-center gap-1">
                          <Users className="h-3 w-3" />
                          {school.teachersCount || 0}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1">
                        {school.isActive ? (
                          <Badge variant="default" className="bg-green-600 gap-1">
                            <CheckCircle className="h-3 w-3" />
                            Active
                          </Badge>
                        ) : (
                          <Badge variant="secondary" className="gap-1">
                            <XCircle className="h-3 w-3" />
                            Inactive
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon" data-testid={`button-school-actions-${school.id}`}>
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => {
                            setSelectedSchool(school);
                            setShowSchoolDialog(true);
                          }}>
                            <Eye className="h-4 w-4 mr-2" />
                            View Details
                          </DropdownMenuItem>
                          <DropdownMenuItem asChild>
                            <Link href={`/super-admin/schools/${school.id}/users`}>
                              <Users className="h-4 w-4 mr-2" />
                              View Users
                            </Link>
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => {
                            window.open(`https://${school.subdomain}.studentdrive.com`, '_blank');
                          }}>
                            <ExternalLink className="h-4 w-4 mr-2" />
                            Visit Portal
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => handleImpersonate(school)}>
                            <Shield className="h-4 w-4 mr-2" />
                            Impersonate School
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => {
                            updateSchoolMutation.mutate({
                              schoolId: school.id,
                              data: { isActive: !school.isActive }
                            });
                          }}>
                            {school.isActive ? "Deactivate School" : "Activate School"}
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => {
                            updateSchoolMutation.mutate({
                              schoolId: school.id,
                              data: { isVerified: !school.isVerified }
                            });
                          }}>
                            {school.isVerified ? "Remove Verification" : "Verify School"}
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={showSchoolDialog} onOpenChange={setShowSchoolDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>School Details</DialogTitle>
            <DialogDescription>
              View and manage school information
            </DialogDescription>
          </DialogHeader>
          {selectedSchool && (
            <div className="space-y-6">
              <div className="flex items-center gap-4">
                <Avatar className="h-16 w-16 rounded-md">
                  <AvatarImage src={selectedSchool.logoUrl || undefined} />
                  <AvatarFallback className="rounded-md bg-primary/10 text-lg">
                    {selectedSchool.name[0].toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <h3 className="font-semibold text-lg">{selectedSchool.name}</h3>
                  <code className="text-sm bg-muted px-2 py-1 rounded">
                    {selectedSchool.subdomain}.studentdrive.com
                  </code>
                </div>
              </div>

              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-1">
                  <p className="text-sm text-muted-foreground">Subscription Status</p>
                  {getSubscriptionBadge(selectedSchool.subscriptionStatus)}
                </div>
                <div className="space-y-1">
                  <p className="text-sm text-muted-foreground">School Status</p>
                  <div className="flex gap-2">
                    {selectedSchool.isActive ? (
                      <Badge variant="default" className="bg-green-600">Active</Badge>
                    ) : (
                      <Badge variant="secondary">Inactive</Badge>
                    )}
                    {selectedSchool.isVerified && (
                      <Badge variant="default" className="bg-blue-600">Verified</Badge>
                    )}
                  </div>
                </div>
              </div>

              <div className="grid gap-4 md:grid-cols-2">
                {selectedSchool.email && (
                  <div className="flex items-center gap-2 text-sm">
                    <Mail className="h-4 w-4 text-muted-foreground" />
                    {selectedSchool.email}
                  </div>
                )}
                {selectedSchool.phone && (
                  <div className="flex items-center gap-2 text-sm">
                    <Phone className="h-4 w-4 text-muted-foreground" />
                    {selectedSchool.phone}
                  </div>
                )}
                {selectedSchool.website && (
                  <div className="flex items-center gap-2 text-sm">
                    <Globe className="h-4 w-4 text-muted-foreground" />
                    <a href={selectedSchool.website} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline">
                      {selectedSchool.website}
                    </a>
                  </div>
                )}
                {(selectedSchool.city || selectedSchool.state || selectedSchool.country) && (
                  <div className="flex items-center gap-2 text-sm">
                    <MapPin className="h-4 w-4 text-muted-foreground" />
                    {[selectedSchool.city, selectedSchool.state, selectedSchool.country].filter(Boolean).join(", ")}
                  </div>
                )}
              </div>

              <div className="grid gap-4 md:grid-cols-3">
                <Card>
                  <CardContent className="pt-4">
                    <div className="flex items-center gap-2">
                      <GraduationCap className="h-5 w-5 text-blue-600" />
                      <div>
                        <p className="text-xl font-bold">{selectedSchool.studentsCount || 0}</p>
                        <p className="text-xs text-muted-foreground">Students</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="pt-4">
                    <div className="flex items-center gap-2">
                      <Users className="h-5 w-5 text-green-600" />
                      <div>
                        <p className="text-xl font-bold">{selectedSchool.teachersCount || 0}</p>
                        <p className="text-xs text-muted-foreground">Teachers</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="pt-4">
                    <div className="flex items-center gap-2">
                      <Users className="h-5 w-5 text-amber-600" />
                      <div>
                        <p className="text-xl font-bold">{selectedSchool.parentsCount || 0}</p>
                        <p className="text-xs text-muted-foreground">Parents</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </div>

              {selectedSchool.description && (
                <div className="space-y-1">
                  <p className="text-sm text-muted-foreground">Description</p>
                  <p className="text-sm">{selectedSchool.description}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter className="flex-wrap gap-2">
            <Button variant="outline" onClick={() => setShowSchoolDialog(false)}>
              Close
            </Button>
            {selectedSchool && (
              <>
                <Button 
                  variant="outline"
                  asChild
                  data-testid="button-view-users"
                >
                  <Link href={`/super-admin/schools/${selectedSchool.id}/users`}>
                    <Users className="h-4 w-4 mr-2" />
                    View Users
                  </Link>
                </Button>
                <Button onClick={() => window.open(`https://${selectedSchool.subdomain}.studentdrive.com`, '_blank')}>
                  <ExternalLink className="h-4 w-4 mr-2" />
                  Visit Portal
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={showImpersonateDialog} onOpenChange={setShowImpersonateDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shield className="h-5 w-5 text-amber-500" />
              Impersonate School
            </DialogTitle>
            <DialogDescription>
              You are about to impersonate {selectedSchool?.name}. This action will be logged for audit purposes.
            </DialogDescription>
          </DialogHeader>
          {selectedSchool && (
            <div className="space-y-4">
              <div className="p-4 rounded-md bg-amber-500/10 border border-amber-500/20">
                <p className="text-sm text-amber-700 dark:text-amber-300">
                  Impersonation allows you to view the school's dashboard as their administrator. 
                  All actions during impersonation will be tracked.
                </p>
              </div>
              <div className="space-y-2">
                <Label htmlFor="reason">Reason for Impersonation (optional)</Label>
                <Textarea
                  id="reason"
                  placeholder="e.g., Troubleshooting login issues..."
                  value={impersonateReason}
                  onChange={(e) => setImpersonateReason(e.target.value)}
                  className="resize-none"
                  data-testid="input-impersonate-reason"
                />
              </div>
            </div>
          )}
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => {
                setShowImpersonateDialog(false);
                setImpersonateReason("");
              }}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleStartImpersonation}
              disabled={impersonateMutation.isPending}
              data-testid="button-start-impersonation"
            >
              {impersonateMutation.isPending ? "Starting..." : "Start Impersonation"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/pages/super-admin/dashboard.t.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Link } from "wouter";
import { 
  Users, 
  School, 
  BookOpen, 
  FileText, 
  ClipboardList,
  TrendingUp,
  DollarSign,
  Activity,
  Building2,
  GraduationCap,
  CreditCard,
  ArrowUpRight,
  Crown,
} from "lucide-react";

interface PlatformStats {
  lms: {
    totalUsers: number;
    activeUsers: number;
    totalInstitutions: number;
    totalCourses: number;
    totalMaterials: number;
    totalQuizzes: number;
    newUsersToday: number;
    newUsersThisWeek: number;
  };
  sms: {
    totalSchools: number;
    activeSchools: number;
    trialSchools: number;
    paidSchools: number;
    totalStudents: number;
    totalTeachers: number;
    totalParents: number;
    totalRevenue: number;
    monthlyRevenue: number;
  };
  recentActivity: {
    type: string;
    message: string;
    timestamp: string;
  }[];
}

function StatCard({ 
  title, 
  value, 
  icon: Icon, 
  description, 
  trend,
  href,
}: { 
  title: string; 
  value: string | number; 
  icon: any;
  description?: string;
  trend?: { value: number; positive: boolean };
  href?: string;
}) {
  const content = (
    <Card className="hover-elevate">
      <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">{title}</CardTitle>
        <Icon className="h-4 w-4 text-muted-foreground" />
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold" data-testid={`stat-${title.toLowerCase().replace(/\s+/g, '-')}`}>
          {value}
        </div>
        {description && (
          <p className="text-xs text-muted-foreground mt-1">{description}</p>
        )}
        {trend && (
          <div className="flex items-center gap-1 mt-1">
            <TrendingUp className={`h-3 w-3 ${trend.positive ? 'text-green-500' : 'text-red-500'}`} />
            <span className={`text-xs ${trend.positive ? 'text-green-500' : 'text-red-500'}`}>
              {trend.positive ? '+' : ''}{trend.value}% from last month
            </span>
          </div>
        )}
      </CardContent>
    </Card>
  );

  if (href) {
    return <Link href={href}>{content}</Link>;
  }
  return content;
}

function StatCardSkeleton() {
  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-2">
        <Skeleton className="h-4 w-24" />
        <Skeleton className="h-4 w-4" />
      </CardHeader>
      <CardContent>
        <Skeleton className="h-8 w-16 mb-1" />
        <Skeleton className="h-3 w-32" />
      </CardContent>
    </Card>
  );
}

export default function SuperAdminDashboard() {
  const { data: stats, isLoading } = useQuery<PlatformStats>({
    queryKey: ["/api/super-admin/stats"],
  });

  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto space-y-8">
      <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Crown className="h-6 w-6 text-amber-500" />
            <h1 className="text-section font-heading text-foreground">
              Super Admin Dashboard
            </h1>
          </div>
          <p className="text-muted-foreground">
            Complete platform overview and control center for LMS and SMS
          </p>
        </div>
        <div className="flex gap-2">
          <Link href="/super-admin/analytics">
            <Button variant="outline" data-testid="button-view-analytics">
              <Activity className="h-4 w-4 mr-2" />
              View Analytics
            </Button>
          </Link>
        </div>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-primary/10">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <BookOpen className="h-5 w-5 text-primary" />
                <CardTitle>Learning Management System (LMS)</CardTitle>
              </div>
              <Link href="/super-admin/users">
                <Button variant="ghost" size="sm" data-testid="button-lms-manage">
                  Manage <ArrowUpRight className="h-4 w-4 ml-1" />
                </Button>
              </Link>
            </div>
            <CardDescription>Public learning platform statistics</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
              {isLoading ? (
                <>
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                </>
              ) : (
                <>
                  <StatCard 
                    title="Total Users" 
                    value={stats?.lms.totalUsers || 0} 
                    icon={Users}
                    description={`${stats?.lms.newUsersToday || 0} new today`}
                    href="/super-admin/users"
                  />
                  <StatCard 
                    title="Active Users" 
                    value={stats?.lms.activeUsers || 0} 
                    icon={Activity}
                    description="Last 30 days"
                  />
                  <StatCard 
                    title="Institutions" 
                    value={stats?.lms.totalInstitutions || 0} 
                    icon={Building2}
                    href="/super-admin/institutions"
                  />
                  <StatCard 
                    title="Courses" 
                    value={stats?.lms.totalCourses || 0} 
                    icon={BookOpen}
                    href="/super-admin/courses"
                  />
                  <StatCard 
                    title="Materials" 
                    value={stats?.lms.totalMaterials || 0} 
                    icon={FileText}
                    href="/super-admin/materials"
                  />
                  <StatCard 
                    title="Quizzes" 
                    value={stats?.lms.totalQuizzes || 0} 
                    icon={ClipboardList}
                    href="/super-admin/quizzes"
                  />
                </>
              )}
            </div>
          </CardContent>
        </Card>

        <Card className="border-green-500/20 bg-gradient-to-br from-green-500/5 to-green-600/10">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <School className="h-5 w-5 text-green-600" />
                <CardTitle>School Management System (SMS)</CardTitle>
              </div>
              <Link href="/super-admin/schools">
                <Button variant="ghost" size="sm" data-testid="button-sms-manage">
                  Manage <ArrowUpRight className="h-4 w-4 ml-1" />
                </Button>
              </Link>
            </div>
            <CardDescription>Multi-tenant school platform statistics</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
              {isLoading ? (
                <>
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                  <StatCardSkeleton />
                </>
              ) : (
                <>
                  <StatCard 
                    title="Total Schools" 
                    value={stats?.sms.totalSchools || 0} 
                    icon={School}
                    href="/super-admin/schools"
                  />
                  <StatCard 
                    title="Active Schools" 
                    value={stats?.sms.activeSchools || 0} 
                    icon={Activity}
                  />
                  <StatCard 
                    title="Trial Schools" 
                    value={stats?.sms.trialSchools || 0} 
                    icon={School}
                    description="In trial period"
                  />
                  <StatCard 
                    title="Paid Subscriptions" 
                    value={stats?.sms.paidSchools || 0} 
                    icon={CreditCard}
                    href="/super-admin/subscriptions"
                  />
                  <StatCard 
                    title="Students" 
                    value={stats?.sms.totalStudents || 0} 
                    icon={GraduationCap}
                  />
                  <StatCard 
                    title="Teachers" 
                    value={stats?.sms.totalTeachers || 0} 
                    icon={Users}
                  />
                </>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="h-5 w-5 text-green-600" />
              Revenue Overview
            </CardTitle>
            <CardDescription>Subscription revenue from schools</CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="space-y-4">
                <Skeleton className="h-20 w-full" />
                <Skeleton className="h-20 w-full" />
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex items-center justify-between p-4 rounded-lg bg-muted/50">
                  <div>
                    <p className="text-sm text-muted-foreground">Total Revenue</p>
                    <p className="text-2xl font-bold" data-testid="stat-total-revenue">
                      ₦{(stats?.sms.totalRevenue || 0).toLocaleString()}
                    </p>
                  </div>
                  <DollarSign className="h-8 w-8 text-green-600/50" />
                </div>
                <div className="flex items-center justify-between p-4 rounded-lg bg-muted/50">
                  <div>
                    <p className="text-sm text-muted-foreground">Monthly Revenue</p>
                    <p className="text-2xl font-bold" data-testid="stat-monthly-revenue">
                      ₦{(stats?.sms.monthlyRevenue || 0).toLocaleString()}
                    </p>
                  </div>
                  <TrendingUp className="h-8 w-8 text-blue-600/50" />
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Activity className="h-5 w-5 text-blue-600" />
              Recent Activity
            </CardTitle>
            <CardDescription>Latest platform events</CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="space-y-3">
                {[1, 2, 3, 4, 5].map((i) => (
                  <div key={i} className="flex items-center gap-3">
                    <Skeleton className="h-2 w-2 rounded-full" />
                    <Skeleton className="h-4 flex-1" />
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-3">
                {stats?.recentActivity?.length ? (
                  stats.recentActivity.map((activity, index) => (
                    <div key={index} className="flex items-start gap-3">
                      <div className={`h-2 w-2 rounded-full mt-2 ${
                        activity.type === 'user' ? 'bg-blue-500' :
                        activity.type === 'school' ? 'bg-green-500' :
                        activity.type === 'payment' ? 'bg-amber-500' :
                        'bg-muted-foreground'
                      }`} />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm truncate">{activity.message}</p>
                        <p className="text-xs text-muted-foreground">
                          {new Date(activity.timestamp).toLocaleString()}
                        </p>
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="text-sm text-muted-foreground text-center py-4">
                    No recent activity
                  </p>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <Link href="/super-admin/users">
          <Card className="hover-elevate cursor-pointer">
            <CardContent className="flex items-center gap-4 p-4">
              <div className="p-3 rounded-lg bg-blue-500/10">
                <Users className="h-6 w-6 text-blue-600" />
              </div>
              <div>
                <p className="font-medium">Manage Users</p>
                <p className="text-xs text-muted-foreground">View all platform users</p>
              </div>
            </CardContent>
          </Card>
        </Link>
        <Link href="/super-admin/schools">
          <Card className="hover-elevate cursor-pointer">
            <CardContent className="flex items-center gap-4 p-4">
              <div className="p-3 rounded-lg bg-green-500/10">
