export default function SchoolUsersPage() {
  const [, params] = useRoute("/super-admin/schools/:schoolId/users");
  const schoolId = params?.schoolId;
  const { toast } = useToast();
  const { startImpersonation, isImpersonating, isStarting: isImpersonationStarting } = useImpersonation();

  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [editingUser, setEditingUser] = useState<SchoolUser | null>(null);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [showImpersonateDialog, setShowImpersonateDialog] = useState(false);
  const [impersonateUser, setImpersonateUser] = useState<{user: SchoolUser; school: School} | null>(null);
  const [impersonateReason, setImpersonateReason] = useState("");

  const { data, isLoading, error } = useQuery<SchoolUsersResponse>({
    queryKey: ["/api/super-admin/schools", schoolId, "users", { role: roleFilter, search }],
    enabled: !!schoolId,
  });

  const updateUserMutation = useMutation({
    mutationFn: async (updates: Partial<SchoolUser>) => {
      return apiRequest(
        "PATCH",
        `/api/super-admin/schools/${schoolId}/users/${editingUser?.id}`,
        updates
      );
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ 
        queryKey: ["/api/super-admin/schools", schoolId, "users"] 
      });
      setShowEditDialog(false);
      setEditingUser(null);
      toast({
        title: "User updated",
        description: "The user has been updated successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update user",
        variant: "destructive",
      });
    },
  });


  const handleEditUser = (user: SchoolUser) => {
    setEditingUser(user);
    setShowEditDialog(true);
  };

  const handleSaveUser = (updates: Partial<SchoolUser>) => {
    updateUserMutation.mutate(updates);
  };

  const handleImpersonateUser = (user: SchoolUser, school: School) => {
    if (isImpersonating) {
      toast({
        title: "Already Impersonating",
        description: "Please end your current impersonation session first.",
        variant: "destructive",
      });
      return;
    }
    setImpersonateUser({ user, school });
    setShowImpersonateDialog(true);
  };

  const handleStartImpersonation = async () => {
    if (!impersonateUser) return;
    try {
      await startImpersonation(
        impersonateUser.school.id, 
        impersonateReason, 
        impersonateUser.user.id
      );
      setShowImpersonateDialog(false);
      setImpersonateUser(null);
      setImpersonateReason("");
      toast({ 
        title: "Impersonation Started", 
        description: `You are now viewing as ${impersonateUser.user.firstName} ${impersonateUser.user.lastName}`,
      });
    } catch (error: any) {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    }
  };

  if (!schoolId) {
    return (
      <div className="p-6 md:p-8 max-w-7xl mx-auto">
        <div className="text-center py-12">
          <p className="text-muted-foreground">Invalid school ID</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 max-w-7xl mx-auto space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/super-admin/schools">
          <Button variant="ghost" size="icon" data-testid="button-back">
            <ArrowLeft className="h-4 w-4" />
          </Button>
        </Link>
        <div>
          <h1 className="text-section font-heading text-foreground">
            {isLoading ? (
              <Skeleton className="h-8 w-48" />
            ) : (
              data?.school?.name || "School Users"
            )}
          </h1>
          <p className="text-muted-foreground">
            Manage users in this school
          </p>
        </div>
      </div>

      {data?.school && (
        <Card>
          <CardContent className="p-4">
            <div className="flex flex-col md:flex-row md:items-center gap-4 md:gap-6">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-primary/10 rounded-lg">
                  <School className="h-6 w-6 text-primary" />
                </div>
                <div>
                  <p className="font-medium">{data.school.name}</p>
                  <p className="text-sm text-muted-foreground">
                    {data.school.subdomain}.studentdrive.com
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                {data.school.email && (
                  <span className="flex items-center gap-1">
                    <Mail className="h-4 w-4" />
                    {data.school.email}
                  </span>
                )}
                {data.school.phone && (
                  <span className="flex items-center gap-1">
                    <Phone className="h-4 w-4" />
                    {data.school.phone}
                  </span>
                )}
              </div>
              <Badge 
                variant={data.school.subscriptionStatus === 'active' ? 'default' : 'secondary'}
