import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useAuth } from "@/hooks/useAuth";

interface ImpersonationSession {
  id: string;
  superAdminId: string;
  targetSchoolId: string;
  targetSchoolName: string;
  targetUserId?: string;
  targetUserEmail?: string;
  targetUserRole?: string;
  startedAt: string;
  sessionToken: string;
}

interface ImpersonationContextType {
  isImpersonating: boolean;
  activeSession: ImpersonationSession | null;
  startImpersonation: (schoolId: string, reason: string, targetUserId?: string) => Promise<void>;
  endImpersonation: () => Promise<void>;
  isStarting: boolean;
  isEnding: boolean;
}

const ImpersonationContext = createContext<ImpersonationContextType | undefined>(undefined);

export function ImpersonationProvider({ children }: { children: ReactNode }) {
  const { user, isSuperAdmin } = useAuth();
  const [activeSession, setActiveSession] = useState<ImpersonationSession | null>(null);

  const { data: activeImpersonation, refetch } = useQuery<{ active: ImpersonationSession | null }>({
    queryKey: ["/api/super-admin/impersonation/active"],
    enabled: !!isSuperAdmin,
    refetchInterval: 60000,
  });

  useEffect(() => {
    if (activeImpersonation?.active) {
      setActiveSession(activeImpersonation.active);
    } else {
      setActiveSession(null);
    }
  }, [activeImpersonation]);

  const startMutation = useMutation({
    mutationFn: async ({ schoolId, reason, targetUserId }: { schoolId: string; reason: string; targetUserId?: string }) => {
      const response = await apiRequest("POST", `/api/super-admin/impersonate/${schoolId}`, {
        reason,
        targetUserId,
      });
      return response.json();
    },
    onSuccess: (data) => {
      setActiveSession({
        id: data.impersonationId,
        superAdminId: user?.id || "",
        targetSchoolId: data.school.id,
        targetSchoolName: data.school.name,
        targetUserId: data.targetUser?.id,
        targetUserEmail: data.targetUser?.email,
        targetUserRole: data.targetUser?.role,
        startedAt: data.startedAt || new Date().toISOString(),
        sessionToken: data.sessionToken,
      });
      queryClient.invalidateQueries({ queryKey: ["/api/super-admin/impersonation/active"] });
      queryClient.invalidateQueries({ queryKey: ["/api/super-admin/activity-feed"] });
    },
  });

  const endMutation = useMutation({
    mutationFn: async () => {
      if (!activeSession) return;
      await apiRequest("POST", `/api/super-admin/impersonate/${activeSession.targetSchoolId}/end`, {});
    },
    onSuccess: () => {
      setActiveSession(null);
      queryClient.invalidateQueries({ queryKey: ["/api/super-admin/impersonation/active"] });
      queryClient.invalidateQueries({ queryKey: ["/api/super-admin/activity-feed"] });
    },
  });

  const startImpersonation = useCallback(async (schoolId: string, reason: string, targetUserId?: string) => {
    await startMutation.mutateAsync({ schoolId, reason, targetUserId });
  }, [startMutation]);

  const endImpersonation = useCallback(async () => {
    await endMutation.mutateAsync();
  }, [endMutation]);

  return (
    <ImpersonationContext.Provider
      value={{
        isImpersonating: !!activeSession,
        activeSession,
        startImpersonation,
        endImpersonation,
        isStarting: startMutation.isPending,
        isEnding: endMutation.isPending,
      }}
    >
      {children}
    </ImpersonationContext.Provider>
  );
}

export function useImpersonation() {
  const context = useContext(ImpersonationContext);
  if (context === undefined) {
    throw new Error("useImpersonation must be used within an ImpersonationProvider");
  }
  return context;
}

server/session-security-service.ts.content:
import { db } from "./db";
import { userActiveSessions, securityEvents, type InsertUserActiveSession, type InsertSecurityEvent } from "@shared/schema";
import { eq, desc, and, gte, lte, count, sql, or, isNull } from "drizzle-orm";
import type { Request } from "express";
import { UAParser } from "ua-parser-js";

// Parse user agent to extract device info
function parseUserAgent(userAgent: string | undefined) {
  if (!userAgent) return { deviceType: "unknown", browser: "unknown", os: "unknown" };

  const parser = new UAParser(userAgent);
  const result = parser.getResult();

  let deviceType = "desktop";
  if (result.device.type === "mobile") deviceType = "mobile";
  else if (result.device.type === "tablet") deviceType = "tablet";

  return {
    deviceType,
    browser: result.browser.name || "unknown",
    os: result.os.name || "unknown",
  };
}

// Session Types
export type SecurityEventType = 
  | "login_failed"
  | "login_success"
  | "logout"
  | "password_reset_requested"
  | "password_changed"
  | "account_locked"
  | "account_unlocked"
  | "suspicious_activity"
  | "session_hijack_attempt"
  | "brute_force_detected"
  | "ip_blocked"
  | "mfa_failed"
  | "permission_denied"
  | "session_terminated"
  | "bulk_action";

export type SecuritySeverity = "info" | "warning" | "error" | "critical";

// Create a new active session
export async function createActiveSession(params: {
  userId: string;
  userEmail: string;
  userRole?: string;
  userName?: string;
  platform: "lms" | "sms";
  schoolId?: string;
  schoolName?: string;
  sessionId: string;
  req?: Request;
  expiresAt?: Date;
}) {
  try {
    const ipAddress = params.req?.ip || params.req?.socket?.remoteAddress || null;
    const userAgent = params.req?.get("user-agent") || null;
    const deviceInfo = parseUserAgent(userAgent || undefined);

    // Calculate expiry (7 days from now if not specified)
    const expiresAt = params.expiresAt || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    const [session] = await db.insert(userActiveSessions).values({
      userId: params.userId,
      userEmail: params.userEmail,
      userRole: params.userRole,
      userName: params.userName,
      platform: params.platform,
      schoolId: params.schoolId,
      schoolName: params.schoolName,
      sessionId: params.sessionId,
      ipAddress,
      userAgent,
      deviceType: deviceInfo.deviceType,
      browser: deviceInfo.browser,
      os: deviceInfo.os,
      isActive: true,
      expiresAt,
    }).returning();

    return session;
  } catch (error) {
    console.error("Error creating active session:", error);
    return null;
  }
}

// Update session last activity
export async function updateSessionActivity(sessionId: string) {
  try {
    await db.update(userActiveSessions)
      .set({ lastActivityAt: new Date() })
      .where(eq(userActiveSessions.sessionId, sessionId));
    return true;
  } catch (error) {
    console.error("Error updating session activity:", error);
    return false;
  }
}

// End a session (logout)
export async function endSession(sessionId: string) {
  try {
    await db.update(userActiveSessions)
      .set({ 
        isActive: false,
        terminatedAt: new Date(),
      })
      .where(eq(userActiveSessions.sessionId, sessionId));
    return true;
  } catch (error) {
    console.error("Error ending session:", error);
    return false;
  }
}

// Force terminate a session (by super admin)
export async function forceTerminateSession(params: {
  sessionId: string;
  terminatedBy: string;
  reason?: string;
}) {
  try {
    const [terminated] = await db.update(userActiveSessions)
      .set({ 
        isActive: false,
        terminatedAt: new Date(),
        terminatedBy: params.terminatedBy,
        terminationReason: params.reason || "Terminated by administrator",
      })
      .where(and(
        eq(userActiveSessions.sessionId, params.sessionId),
        eq(userActiveSessions.isActive, true)
      ))
      .returning();

    return terminated;
  } catch (error) {
    console.error("Error force terminating session:", error);
    return null;
  }
}

// Force terminate all sessions for a user
export async function forceTerminateUserSessions(params: {
  userId: string;
  terminatedBy: string;
  reason?: string;
}) {
  try {
    const terminated = await db.update(userActiveSessions)
      .set({ 
        isActive: false,
        terminatedAt: new Date(),
        terminatedBy: params.terminatedBy,
        terminationReason: params.reason || "All sessions terminated by administrator",
      })
      .where(and(
        eq(userActiveSessions.userId, params.userId),
        eq(userActiveSessions.isActive, true)
      ))
      .returning();

    return terminated;
  } catch (error) {
    console.error("Error force terminating user sessions:", error);
    return [];
  }
}

// Force terminate all sessions for a school
export async function forceTerminateSchoolSessions(params: {
  schoolId: string;
  terminatedBy: string;
  reason?: string;
}) {
  try {
    const terminated = await db.update(userActiveSessions)
      .set({ 
        isActive: false,
        terminatedAt: new Date(),
        terminatedBy: params.terminatedBy,
        terminationReason: params.reason || "All school sessions terminated by administrator",
      })
      .where(and(
        eq(userActiveSessions.schoolId, params.schoolId),
        eq(userActiveSessions.isActive, true)
